quests[265] = { id = 265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattensuche geht weiter", description = "Hier habt Ihr Euer Buch zurück, {name}, und viel Glück noch bei Eurer Suche. Vielleicht können Euch ja andere in der Stadt mehr Hinweise geben, wenn Ihr sie fragt.\n\nIch habe jedenfalls noch einen für Euch - obwohl der Autor dieses Buches in Dunkelhain fremd ist, wurde das Buch selbst hier gekauft.", sourceObjective = "Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben.", progress = "Manchmal verkaufe ich leere Bücher an Gelehrte oder Magier oder an irgendwen, der ein Tagebuch führen möchte.\n\nIch kann mich gut an jeden erinnern, dem ich in den letzten paar Monaten ein Buch verkauft habe...", completion = "Ach ja. Ich habe dieses Buch vor einem Monat an eine zwielichtige Type verkauft. Er hat mir seinen Namen nicht gesagt, aber er war ein nervöser, hektischer Kerl, der laufend über seine Schulter sah.\n\nIch hoffe, das hilft Euch weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[266] = { id = 266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachforschungen im Gasthaus", description = "Hier habt Ihr Euer Buch zurück, und noch viel Glück bei Euren Nachforschungen.\n\nVielleicht wollt Ihr Eure Suche auf das Gasthaus ausweiten. Wenn die Person, die Ihr sucht, einige Zeit hier in der Stadt verbracht hat, dann hat sie dort vielleicht jemand gesehen.", sourceObjective = "Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt.", progress = "Der Rote Rabe läuft nicht mehr so gut wie früher, aber hier kommen immer noch Reisende durch.\n\nWenn Ihr mir die Person beschreibt, nach der Ihr sucht, dann erinnere ich mich vielleicht an sie.", completion = "Oh ja, ich erinnere mich an dieses Buch. Sein Besitzer mietete sich hier für ein paar Tage ein und verbrachte die Abende schreibend an der Bar.\n\nEr verließ die Stadt überhastet und brummelte dabei etwas darüber, dass er gejagt würde von... irgendetwas. Als ich ihn das letzte Mal sah, verließ er die Stadt in Richtung Westen, auf der Suche nach einem neuen Versteck.\n\nDer erste Ort, in dem er landen würde, wäre Rabenflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[267] = { id = 267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung durch die Troggs", description = "{class}, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Ironforge zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über das Tor hier zu wachen, und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir 8 Trogg-Steinzähne als Beweis.", sourceObjective = "Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne.", progress = "Könnt Ihr mir 8 Trogg-Steinzähne zeigen? Wenn nicht, dann habt Ihr immer noch etwas zu erledigen, {name}.", completion = "Ich bin ziemlich beeindruckt, {name}. Ihr habt dem Volk der Zwerge einen großen Dienst erwiesen, indem Ihr unser Land verteidigt habt. Selbst König Magni Bronzebeard wäre stolz auf Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[268] = { id = 268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Sven", description = "Das Buch, das Ihr gefunden habt, war nur zur Hälfte fertig geschrieben. Ich musste es auf Svens Hof zurücklassen, als ich hierher floh... \n\nHier. Nehmt mein vollständiges Tagebuch und bringt es zu Sven. Es beschreibt wesentlich genauer, was auf seinem Hof passierte.\n\nObwohl dieses Tagebuch in den letzten Wochen meine einzige Gesellschaft war, gebe ich es gern auf, wenn ich mir dadurch erspare, Sven und seiner Wut zu begegnen.", sourceObjective = "Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück.", progress = "Habt Ihr herausgefunden, wer die Schattengestalt war?", completion = "Dieses Tagebuch macht mir vieles klar und zeigt mir den Weg, den ich gegen die dunklen Reiter zu gehen habe! Ich habe diese Reiter im Dämmerwald und im Gespräch mit dem Zauberer Morbent Fel am verlassenen Gut gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[269] = { id = 269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Weisheit", description = "Geht nach Stormwind und sprecht dort mit Bischof Farthing in der Kathedrale des Lichts. Gebt ihm Jitters' Tagebuch und sagt ihm, dass Ihr vorhabt, Euch Morbent Fel zu stellen.\n\nAuch wenn Stormwind Dunkelhain aufgegeben hat, ist Farthing doch eine gute Seele und sehr weise. Er könnte Euch bei Eurem Versuch, uns zu retten, behilflich sein.\n\nEure Mission ist gefahrvoll, aber beeilt Euch dennoch, {name}. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über dem Dämmerwald mehr und mehr.", sourceObjective = "Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch.", progress = "Ruht Euch erst einmal aus, Bruder. Ich sehe Euch an, dass Ihr weit gereist seid und eine schwere Bürde tragt. Könnt Ihr mir erzählen, was diesen dunklen Schatten über Euch wirft?", completion = "<Nachdem er das Tagebuch gelesen und Eure Absichten erfahren hat... >\n\nEine böse Besudelung hat im ohnehin bereits belagerten Dämmerwald Fuß gefasst. Ich danke dem Licht, dass wir einen Helden wie Euch haben, der sich ihm stellen will.\n\nAber zuerst müsst Ihr Euch auf die kommenden Strapazen vorbereiten... denn der Totenbeschwörer Morbent Fel ist ungeheuer mächtig, und er hat dunkle Verzauberungen auf sich selbst gewirkt, um sich vor körperlichen Angriffen zu schützen. Wenn Ihr ihn besiegen wollt, werdet Ihr eine Waffe benötigen, die gegen diese Schutzzauber gefeit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[270] = { id = 270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Flotte", description = "Vor vielen Jahren sank die dritte Flotte von Kul'Tiras vor der Küste des Sumpflandes, einem Moorgebiet nördlich des Zwergenkönigreichs von Ironforge. Auf einem der Schiffe befand sich eine Ladung Lichtgeschmiedetes Eisen.\n\nDieses Metall ist wertvoll für uns, da Gegenstände, die daraus gefertigt werden, mit heiliger Wahrheit zuschlagen. Wenn Ihr Morbent Fel entgegentreten wollt, dann werdet Ihr eine solche Waffe brauchen.\n\nGeht zum Hafen von Menethil und sprecht mit meinem zwergischen Kollegen Glorin Steelbrow. Wenn dieses verlorene Metall überhaupt gefunden werden kann, dann weiß er, wo man danach suchen muss.", sourceObjective = "Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow.", completion = "Lichtgeschmiedetes Eisen ist ein wertvolles Metall, aber es scheint, als hättet Ihr eine schreckliche Aufgabe vor Euch. Ihr seid weit gereist, Bruder. Mit Glück findet Ihr aber gerade das, was Ihr sucht!\n\nUnd falls Ihr das Eisen findet: Ich kenne da jemanden, der es zu einer Waffe gegen den Totenbeschwörer im Dämmerwald, von dem Ihr redet, formen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[271] = { id = 271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Weitschreiter-Lodge, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nDer Bär, Old Sooty, hält sich irgendwo in der Nähe seines Baus in den Hügeln über Thelsamar auf.", sourceObjective = "Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk.", progress = "Ah, {name}! Schon wieder hier? Zweifelsohne wart Ihr wieder auf der Jagd! Keine Sorge, es ist nicht schlimm, wenn Ihr ein paar Rückschläge einstecken müsst, davon werdet Ihr auf lange Sicht nur besser.\n\n... viel schlechter könntet Ihr ja sowieso nicht mehr werden...", completion = "Äh... was ist das da? Ein Bärenschädel, wie es aussieht.\n\n<Er fährt unbewusst mit einem Finger an seiner Narbe entlang>\n\nNun, das ist eine ziemlich interessante Beute, die Ihr da habt. Kann eigentlich nicht der Bär von damals sein...\n\n<Seine Stimme verliert sich, und er fängt sichtbar an zu zittern.>\n\nOh, nehmt das weg, nehmt es weg! Schafft dieses grausige Ding hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[272] = { id = 272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Seelöwen", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", sourceObjective = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", progress = "Habt Ihr Euren Anhänger geschaffen, auf dass ich ihn mir ansehen kann, {name}? Falls Ihr Hilfe beim Aufspüren der Teile braucht, bittet am besten die örtliche Bevölkerung um Hinweise. Ihr werdet dabei nicht nur finden, was Ihr sucht, sondern habt außerdem noch einen guten Grund, dieses wunderbare und heilige Tal zu erforschen.", completion = "Ihr habt die Prüfung des Seelöwen erfolgreich beendet, {name}... Glückwunsch.\n\nJede Teilaufgabe bei der Beschaffung des Anhängers zeigt, dass man sowohl Beweglichkeit als auch Ausdauer benötigt, um in Harmonie mit dem agieren zu können, was Ihr unter Wasser tun wollt. Keine der Eigenschaften kann ohne die andere existieren, und beide können nicht erreicht werden ohne Euren Willen, den Aspekt des Seelöwen in Euch aufzunehmen.\n\nMerkt Euch diese Lektionen gut und verlasst Euch auf sie, wenn Ihr Eure Wassergestalt erworben habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[273] = { id = 273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Ausgrabungsstätte", description = "Es ist noch nicht zu spät, Ihr könnt gern losziehen und Huldar suchen. Er kann noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können Miran und Saean dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind.\n\nSie nehmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang.\n\nIhr solltet keine Probleme haben, sie zu finden, solange sie nicht bereits dort angekommen sind.", sourceObjective = "Sprecht mit Huldar.", completion = "Hmpf, es wird mehr als einen Überfall durch die Dunkeleisenzwerge brauchen, um die Lieferungen zu stoppen!\n\nAber Saean... Ich hätte nie vermutet, dass er einer ihrer Sympathisanten ist. Wir arbeiten schon seit fast einem Jahr mit ihm zusammen... vielleicht habe ich die Anzeichen übersehen.\n\nNun ja, darüber werde ich später nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[274] = { id = 274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Dies ist kein gewöhnliches Sprengpulver. Seht diese winzigen Silberkristalle. Und der eindeutige Geruch! Es ist sonnenklar, dass es sich hier um Zephyriumpulver handelt. Zephyrium an sich ist harmlos. Aber wenn es nass wird, könnte es ganz Ironforge aus dem Berg sprengen.\n\nDie chemische Reaktion kann entschärft werden, indem man vier Komponenten mischt: Lauerergift, einen zerstoßenen Kristall der Mo'grosh, eine Krokiliskenträne und diese Entschärfungspaste. Jetzt geht und erklärt es Hinderweir, ehe es zu spät ist!", sourceObjective = "Ashlan Stonesmirk möchte, dass Ihr zum Chefingenieur Hinderweir zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt.", progress = "Was bringt Ihr da von Ashlan?", completion = "Eine Entschärfungspaste? Für Zephyrium? Oh Himmel!", sourceObjectiveStatus = "unverified-source-field" }
quests[275] = { id = 275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärendes Land", description = "Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.\n\nDie Moorkrabbler watscheln mitten in den Wasserwegen des Sumpflandes herum.", sourceObjective = "Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", progress = "Das Sumpfland weint noch, und die Moorkrabbler wüten noch. Kommt zurück, wenn Eure Aufgabe erledigt ist.", completion = "Das Leiden des Landes wurde durch Eure Taten gemildert, und dafür werde ich Euch belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[276] = { id = 276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stapfende Pfoten", description = "Die Moosfellgnolle lebten viele Jahre friedlich im Sumpfland, aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer.\n\nSie befinden sich nicht mehr im Gleichgewicht mit dem Land. Wenn das Sumpfland überleben soll, müssen die Gnolle dezimiert werden.\n\nTötet 15 Gnolle der Moosfelle und 10 Bastarde der Moosfelle. Jagt sie im Süden, nahe dem Zwergentor von Algaz. Wenn Ihr das getan habt, kehrt zu mir zurück.", sourceObjective = "Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", progress = "Eure Aufgabe steht noch an, junger {class}.", completion = "Indem Ihr die Anzahl der Gnolle verringert habt, habt Ihr Euch um das Wohlergehen des Sumpflandes gekümmert. Obwohl mein Vertrauen in Euer Volk in der Vergangenheit belastet wurde, {race}, kann es vielleicht doch noch wieder hergestellt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[277] = { id = 277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer-Tabu", description = "Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Ich werde diesen Schmerz nicht länger ertragen!\n\nEntledigt die Moosfelle ihrer kunstlosen Feuersteine, der Werkzeuge, die sie zum Feuermachen verwenden. Die meisten Moosfelle tragen diese Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.", sourceObjective = "Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine.", progress = "Habt Ihr die Feuermach-Werkzeuge der Gnolle?", completion = "... Danke. Ich werde diese Feuersteine zertrümmern und ins Meer werfen, auf dass sie nie wieder dazu verwendet werden können, lebendiges Holz zu verbrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[278] = { id = 278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Fangt gleich damit an, die Stoffe zum Entschärfen zusammenzusuchen, {name}. Lauerergift kann von den im Loch Modan heimischen Spinnen gewonnen werden. Krokiliskentränen findet man ebenfalls hier im Loch. Ein Kristall der Mo'grosh hingegen dürfte sehr schwierig zu bekommen sein. Die Oger im Nordosten bauen sie ab, aber die Kristalle sind ein sehr seltener Rohstoff.\n\nWir müssen einen Angriff der Dunkeleisenzwerge abwehren können! Kommt zurück, wenn Ihr alle erforderlichen Dinge zusammenhabt, und ich werde die Mixtur vorbereiten.", sourceObjective = "Chefingenieur Hinderweir möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt.", progress = "Habt Ihr die benötigten Dinge? Die Zeit drängt!!", completion = "Gerade rechtzeitig, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[279] = { id = 279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen aus der Tiefe", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", sourceObjective = "Tötet 12 Murlocs der Blaukiemen.\n\nErschlagt Gobbler und nehmt Euch seinen Kopf.\n\nBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil", progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, {name}.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine.", sourceObjectiveStatus = "unverified-source-field" }
quests[280] = { id = 280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Heute habe ich einige Aufrührer der Dunkeleisenzwerge gesehen, die mit einem Fässchen in Richtung Damm geschwommen sind. Es waren keine Gebirgsjäger zur Hand, um sie aufzuhalten! Ich fürchte, sie haben das Zephyrium am Fuße des Dammes deponiert, und es könnte jede Minute hochgehen! Lasst mich diese ganzen Zutaten zur Entschärfungsmixtur zusammenmischen. Na bitte!\n\nIhr müsst jetzt diese Mixtur mitnehmen und in das Fässchen einrühren, bevor es zu spät ist! Beeilt Euch!", sourceObjective = "Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern.", progress = "Der Deckel des Fässchens schraubt sich langsam ab.", completion = "Das Fässchen zischt ein wenig, als sich die Entschärfungsmixtur darin löst.", sourceObjectiveStatus = "unverified-source-field" }
quests[281] = { id = 281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waren-Wiederbeschaffung", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blind Princess, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murloc an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Menethil-Statuette und bringt sie mir wieder.", sourceObjective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet einen Arm voll rot gefärbter Flaschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[282] = { id = 282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senirs Beobachtungen", description = "Ich hatte ursprünglich vor, meinen Lehrling mit meinem Bericht zu meinem Bruder Senir zu schicken, aber ich würde mich viel besser fühlen, wenn er in etwas... verlässlicheren Händen wäre. Natürlich nur, wenn es Euch nichts ausmacht?\n\nHmm... Ihr müsstet den Tunnel nehmen, um nach Kharanos zu gelangen.\n\nSprecht mit Gebirgsjäger Thalos, bevor Ihr durch den Tunnel geht. Er ist mittlerweile vollständig von den Troggs überrannt.\n\nFolgt der Straße zurück nach Anvilmar und geht dann weiter nach Osten zum Tunnel. Thalos ist ganz in seiner Nähe stationiert.", sourceObjective = "Sprecht mit Gebirgsjäger Thalos.", progress = "Seid gegrüßt! Seid vorsichtig, {name}, der Tunnel nach Dun Morogh ist mit Troggs verseucht und nicht sicher zu bereisen.\n\nWenn Ihr keine eiligen Geschäfte in Dun Morogh zu erledigen habt, möchte ich Euch bitten, hier in Anvilmar zu bleiben, bis der Tunnel wieder sicherer ist.", completion = "Hm, nun gut, wenn Whitebeard Euch mit wichtigen Geschäften nach Dun Morogh schickt, kann ich Euch ja schlecht aufhalten, oder?\n\nLasst mich Euch wenigstens ein paar Ratschläge und Anweisungen geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[283] = { id = 283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dunkle Bedrohung", description = "Das Fässchen zischt ein wenig.", sourceObjective = "Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten.", completion = "Vielen, vielen Dank, {name}! Ihr habt den Stonewroughtdamm gerettet! Ohne Eure Hilfe hätten die Terroristen der Dunkeleisenzwerge bestimmt für den Untergang dieses mächtigen Wahrzeichens gesorgt. Mit Eurer Tapferkeit habt Ihr das Königreich und die Allianz stolz gemacht, {class}.\n\nDer Damm ist wieder sicher ... zumindest vorläufig ...", sourceObjectiveStatus = "unverified-source-field" }
quests[284] = { id = 284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche geht weiter", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur von der Menethil-Statuette.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", sourceObjective = "Sucht nach der Menethil-Statuette.", completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[285] = { id = 285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in weiteren Hütten", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Menethil-Statuette enthalten!", sourceObjective = "Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette.", completion = "Dieses Fass ist unter Schlamm und Gras halb begraben...", sourceObjectiveStatus = "unverified-source-field" }
quests[286] = { id = 286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe der Statuette", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Menethil-Statuette sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", sourceObjective = "Bringt Karl Boran die Menethil-Statuette.", progress = "Habt Ihr die Statuette?", completion = "Der Kapitän der Blind Princess wird erleichtert sein zu hören, dass seine kostbare Fracht geborgen wurde. Ihr habt Euch diesen Lohn durch die geleisteten Dienste wohl verdient.\n\nEs tut gut, verlässliche Leute wie Euch zu kennen, insbesondere in so beschwerlichen Zeiten wie diesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[287] = { id = 287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhle der Frostmane", description = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, {name}. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.\n\nWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.\n\nNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Iceflowsee erreicht. Am linken Ufer werdet Ihr Brewnall vorfinden. Die Höhle liegt südwestlich des Dorfes.", sourceObjective = "Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos.", completion = "Ah, {name}! Ich hätte nicht gedacht, dass Ihr Probleme hättet, dorthin zu finden. Meine Richtungsangaben sind vortrefflich, wisst Ihr...\n\nLasst mich gerade noch schnell meinen Bericht fertig stellen.\n\n\n\nHier! Nun, haha, ja, das ist jetzt wirklich lustig... Kann ich davon ausgehen, {name}, dass es Euch nichts ausmachen würde, mir einen letzten Gefallen zu tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[288] = { id = 288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dritte Flotte", description = "Ich war einst erster Maat auf der HERRIN DER MEERE, einem Linienschiff der dritten Flotte von Kul Tiras, der verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs beherrscht wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Oh, mir brummt der Schädel! Ich werde einen frischen Drink brauchen, wenn ich mit diesem Kater klarkommen und meine Geschichte fortsetzen soll.", sourceObjective = "Spendiert dem ersten Maat Fitzsimmons einen Krug Met.", progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[289] = { id = 289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfluchte Crew", description = "<Gestärkt setzt Fitzsimmons seine Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen dritten Flotte von Kul Tiras, die vor der Küste im Norden vernichtet wurde. Aber obwohl ich das einzige Mitglied der Flotte bin, das noch atmet, bin ich nicht der einzige, der noch herumläuft! Denn auf einem unserer Schiffe war ein großer und schrecklicher Schatz versteckt, und dessen unheimliche Macht hält die Seelen meiner Brüder in den verrottenden Wracks gefangen.\n\nWenn Ihr allerdings einige meiner Brüder befreien könnt, könnt Ihr vielleicht auch den Fluch brechen, der auf ihnen lastet.", sourceObjective = "Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil.", progress = "Ich kann manchmal in meinen Träumen das unselige Stöhnen meiner Brüder hören! Bitte, guter Herr, befreit sie von ihren Fesseln und lasst ihre Schreie verstummen.", completion = "Ich danke Euch, {name}. Und den Dank meiner verfluchten Brüder habt Ihr ebenfalls.", sourceObjectiveStatus = "unverified-source-field" }
quests[290] = { id = 290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen des Fluchs", description = "Um den Fluch zu brechen und alle meine Brüder zu befreien, müsst Ihr das... Ding... das auf meinem Schiff verstaut ist, bergen und reinigen! Ich weiß nicht, was es war, aber ich weiß, dass es sicher in der Geldkassette des Schiffs verwahrt wurde, zu dem nur Kapitän Halyndor den Schlüssel hatte.\n\nMein alter Kapitän erscheint mir immer noch in meinen Träumen. Ich bin mir sicher, dass er auf meinem untergegangenen Schiff, der INTREPID, herumläuft. Besorgt Euch den Schlüssel von ihm und öffnet damit die Geldkassette der INTREPID.\n\nAnschließend, wenn Ihr das verfluchte Ding habt, bringt es zu Glorin Steelbrow, dem Priester, hier in der Stadt.", sourceObjective = "Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.\n\nVerwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss.", sourceObjectiveStatus = "unverified-source-field" }
quests[291] = { id = 291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berichte", description = "Wunderbar! Überbringt Senator Barin Redstone meinen Bericht. Er ist ein missmutiger Geselle, also stört Euch nicht an seinem wenig sonnigen Gemüt. Er ist in Ironforge, in der Halle, in der König Magni Hof hält.\n\nIhr kennt den Weg nach Ironforge nicht? Nehmt die Straße aus Kharanos heraus nach Norden, überquert die Brücke und folgt dann der Straße nach Osten den Berghang hinauf. Einige große Banner flankieren diese Straße.\n\nAch ja, und könntet Ihr es vielleicht vermeiden, zu erwähnen, dass Ihr mir geholfen habt? Ich kann die ja nicht glauben lassen, ich würde hier draußen nicht hart arbeiten, nicht wahr?", sourceObjective = "Überbringt Senator Barin Redstone in Ironforge Senirs Bericht.", progress = "Hmm... Es scheint, als würden meine Wachen neuerdings jeden Bittsteller durchlassen. Nun, was wollt Ihr? Fasst Euch kurz.", completion = "<Er überfliegt das Dokument.>\n\nVollmacht des KÖNIGS!? Hat Magni jetzt völlig den Verstand verloren? Und dieser schändliche Whitebeard... hat die Dinge selbst in die Hand genommen, was? Der Senat wird nicht erfreut sein, hiervon zu hören, nicht das kleinste bisschen.\n\nWas, Ihr seid immer noch hier? Geht, bevor ich die Wachen rufe!", sourceObjectiveStatus = "unverified-source-field" }
quests[292] = { id = 292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Paleth", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies ist der Schatz, von dem Fitzsimmons gesprochen hat: ein verfluchtes Auge von Paleth.\n\nBringt das verfluchte Auge von Paleth zum Zwergen-Priester Glorin Steelbrow im Hafen von Menethil. Fragt ihn, wie man den Fluch des Auges brechen kann.", sourceObjective = "Bringt Glorin Steelbrow das verfluchte Auge von Paleth.", progress = "Dieser Säufer Fitzsimmons hat Euch zu mir geschickt? Nun, Ihr könnt ihm sagen, dass ich kein Ale übrig habe. Er wird wohl jemand anderes anbetteln müssen!", completion = "Ein Auge von Paleth? Erstaunlich! Hmm... irgendetwas stimmt nicht mit diesem hier. Ihr habt es auf einem der Schiffswracks gefunden? Das erklärt einiges! Allerdings... wusste ich gar nicht, dass sie in der dritten Flotte ein solches Auge hatten... \n\nKein Wunder, dass Fitzsimmons so verängstigt war. Ein verfluchtes Auge von Paleth ist kein Grund zur Fröhlichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[293] = { id = 293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Auges", description = "Ich kann den Fluch nicht von dem Auge von Paleth nehmen. Die Augen wurden von Menschen-Priestern hergestellt, daher werdet Ihr nach Stormwind gehen müssen, um jemanden zu finden, der Euch helfen kann. Sprecht mit Erzbischof Benedictus. Er steht der Kathedrale des Lichts in Stormwind vor. Er kann helfen.\n\nDas hoffe ich jedenfalls, um euretwillen.", sourceObjective = "Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind.", progress = "Was habt Ihr da für eine Kugel? Sie sieht so... befleckt aus.", completion = "Ein Auge von Paleth. Aber dieses hat viel Leid gesehen... es muss Zeuge einer schrecklichen, grauenhaften Tragödie gewesen sein.\n\nLasst es mich reinigen, denn die Augen wurden geschaffen, um hell zu erstrahlen, und ihre Kräfte können sehr gefährlich sein, wenn sie wie dieses hier besudelt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[294] = { id = 294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormers Rache", description = "Die Lage ist ernst, soviel ist sicher. Als wir diese Knochen freigelegt haben, hat das die Raptoren angelockt. Diese dreckigen Bestien haben meine Brüder getötet und mich, Merrin und den armen Ausgrabungsleiter hier festgesetzt.\n\nHelft mit, das Sumpfland von diesen Raptoren zu säubern, {name}. Scheckige Raptoren und Scheckige Kreischer befinden sich direkt westlich der Klippe hier. Tötet jeweils 10, wenn Ihr könnt.\n\nDas wäre ein guter Anfang für die Rache, die ich mir für sie ausgedacht habe.", sourceObjective = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet.", progress = "Tötet 10 Scheckige Raptoren und 10 Scheckige Kreischer, {name}. Meine Mitarbeiter hatten das Schicksal nicht verdient, das ihnen zuteil wurde. Es ist an der Zeit, die Rechnung zu begleichen.", completion = "Töten ist ein schmutziges Geschäft, aber Ihr habt Eure Sache gut gemacht, {name}. Wenn ich nicht dazu verpflichtet wäre, hier beim Ausgrabungsleiter und Merrin zu bleiben, würde ich an Eurer Seite da unten Blut vergießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[295] = { id = 295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormers Rache", description = "Es ist an der Zeit, diese abscheulichen Raptoren ihren Blutdurst bereuen zu lassen. Gleich da unten gibt es Dutzende von scheckigen Sensenklauen- und Scharfzahnraptoren. Lasst diese scheußlichen Kreaturen bezahlen, indem Ihr 10 von jeder Sorte erschlagt.", sourceObjective = "Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt.", completion = "Ihr habt beim Aufräumen unter diesen Raptoren phantastische Arbeit geleistet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[296] = { id = 296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormers Rache", description = "Während Ihr da unten wart, ist mir aufgefallen, dass eines der Biester aus der Menge herausstach. Es war größer und bedrohlicher. Ich könnte wetten, das ist derjenige, der die anderen hierher geführt hat und für die Störung der Ausgrabungsstätte verantwortlich ist.\n\nIch erbitte eine letzte Aufgabe von Euch, {name}. Sorgt dafür, dass Sarlatan seine gerechte Strafe erhält. Und wenn man die Schwere seiner Verbrechen bedenkt, bedeutet Gerechtigkeit in diesem Falle den Tod! Bringt mir eine seiner Krallen als Beweis, dass er tot ist.", sourceObjective = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt.", progress = "Ist Sarlatan tot? Seid Ihr dem Andenken der Gefallenen gerecht geworden?", completion = "Danke, {name}. Eure Anstrengungen hier werden nicht in Vergessenheit geraten. Viele unschuldige Zwerge starben an dieser Stätte, während sie einfach nur ihrer Arbeit nachgingen. Die Rache, die Ihr über diese bösen Kreaturen gebracht habt, sollte dafür sorgen, dass sie es sich zweimal überlegen, bevor sie je wieder König Magnis Untertanen angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[297] = { id = 297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzen sammeln", description = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt. Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen. Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", sourceObjective = "Bringt Magmar Fellhew 8 verzierte Steingötzen.", progress = "Habt Ihr die Götzen? Wir müssen sie studieren und Ironforge von unseren Ergebnissen berichten!", completion = "Ihr habt sie! Gut gemacht, {name}!\n\nUnd Ihr seht nicht einmal besonders angeschlagen aus, trotz all der wild gewordenen Troggs. Ich werde Euch im Auge behalten... Ihr seid viel versprechend.", sourceObjectiveStatus = "unverified-source-field" }
quests[298] = { id = 298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht über den Fortschritt der Ausgrabungen", description = "Ich muss einen Fortschrittsbericht nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung meiner Anfrage nach mehr Sprengpulver! Hier ist der Bericht. Bringt ihn Jern Hornhelm. Er ist unser örtlicher Kontaktmann in Thelsamar.\n\nKeine schwierige Aufgabe, aber sie muss erledigt werden.", sourceObjective = "Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar.", progress = "Oh, ein Fortschrittsbericht von der Stätte? Sehr gut!", completion = "Pah! Ironband hat Probleme mit den Troggs. Ich frage mich, ob er das Sprengpulver will, um ihm bei seinen Ausgrabungen zu helfen oder um ihn bei seinen Bemühungen gegen die Trogg-Bestien zu unterstützen...\n\nNun ja, so oder so ist das gute Pulver sinnvoll eingesetzt!\n\nEs ist allerdings etwas seltsam, dass ich ihm vor ein paar Wochen eine Menge Sprengpulver geschickt habe. Ich frage mich ja, wo das hingekommen ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[299] = { id = 299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllung der Vergangenheit", description = "Kurz vor der Invasion habe ich eine große Schrifttafel gefunden, die man den Goazstein nennt. Der übersetzte Text reißt an 4 Stellen ab. Der Text spricht von einem \"göttlichen Plan\" und einer \"schicksalhaften Prophezeiung\".\n\nIch fürchte, uns läuft die Zeit davon. Ich bin zu alt, um hinunterzugehen und diesen Bestien zu trotzen. Aber Ihr seid stark.\n\nDurchkämmt die Ausgrabungsstätte und sucht die 4 fehlenden Tafelfragmente: Ados, Modr, Golm und Neru. Sucht sie in alten Artefakten oder dort, wo das Erdreich locker ist. Bringt sie mir, auf dass ich damit beginnen kann, ihre Geheimnisse zu enträtseln!", sourceObjective = "Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru.", progress = "Habt Ihr die vier Fragmente bereits gefunden, {name}? Ados, Modr, Golm und Neru...", completion = "Ah, der Goazstein ist vollständig! Ausgezeichnete Arbeit, {name}. Wirklich ausgezeichnete Arbeit. Jetzt kann ich mit der kniffligen Übersetzung dieser Titanenschrift weitermachen. Ich kann bereits neue Worte erkennen! Hmm... es heißt hier \"Alte Götter... angekettet unter dem Land\". Dies ist der Anfang von etwas Epischem.", sourceObjectiveStatus = "unverified-source-field" }
quests[301] = { id = 301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung in Ironforge", description = "Wir werden eine Bewilligung brauchen, um Ironband mehr Sprengpulver zu beschaffen. Ihr müsst seinen Bericht zum Hauptquartier der Forscherliga in Ironforge bringen.\n\nHier ist der Bericht. Gebt ihn Ausgrabungsleiter Stormpike und vergesst nicht, Euch zu ducken, nachdem Ihr ihn abgeliefert habt. Stormpike ist ein Hitzkopf, und es wird ihn nicht erfreuen, wenn er von Ironbands langsamem Vorankommen an der Ausgrabungsstätte hört.\n\nIhr findet Stormpike in der Versammlungshalle der Forscher.", sourceObjective = "Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike.", progress = "Wir Stormpikes lassen uns nicht gern von unbedeutenden Angelegenheiten stören, {class}. Ich hoffe, Ihr bringt Neuigkeiten, die meine Aufmerksamkeit verdienen.", completion = "Verflucht sei Ironband! Ich habe ihm schon vor Wochen eine Ladung Sprengpulver geschickt, aber er erwähnt es nicht mal in diesem Bericht.\n\nAlso... wo ist das Sprengpulver hin?!?", sourceObjectiveStatus = "unverified-source-field" }
quests[302] = { id = 302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulver für Ironband", description = "Wenn Ironband immer noch Sprengpulver braucht, dann, bei Magni, soll er es haben! Ich habe die Bewilligung bereits mit einem Boten nach Thelsamar zu Jern Hornhelm vorausgeschickt. Er wird das Pulver und andere Vorräte zum Transport zu Ironband bereitstellen.\n\nAch, und noch was: Ich will, dass Ihr persönlich dafür Sorge tragt, dass diese Pulverlieferung ihren Bestimmungsort erreicht. Die letzte kam nicht an, also haltet Euren Verstand wach und Eure Augen offen.", sourceObjective = "Sprecht in Thelsamar mit Jern Hornhelm.", completion = "Was? Stormpike will, dass Ihr die Lieferung persönlich zu Ironband bringt?\n\nIch... denke, das geht in Ordnung, aber das Problem ist, dass ich Huldar bereits mit den Trägern Miran und Saean losgeschickt habe. Ihr habt sie gerade verpasst, sie sind vor einer kurzen Weile erst aufgebrochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[303] = { id = 303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkeleisenkrieg", description = "Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandol-Übergang verwüstet. Dun Modr fiel kurz darauf.\n\nIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.\n\nUnd jetzt beeilt Euch!", sourceObjective = "Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", progress = "Roggo konnte keinen Kontakt zu den Reserven herstellen. Wir müssen offensiven Druck auf dieses Lager der Dunkeleisenzwerge ausüben, {class}. Und jetzt geht wieder da raus und erfüllt Eure Pflicht König Magni gegenüber!", completion = "Ihr habt Eure Befehle gut ausgeführt, {class}. Ihr habt bewiesen, dass Ihr ein tapferer Soldat und loyaler Diener König Magnis' seid, und dafür bewundere ich Euch. Durch den Druck, den Ihr auf das Lager der Dunkeleisenzwerge ausgeübt habt, haben wir jetzt eine Chance, sie für immer aus unseren Landen zu vertreiben... wenn nur die verdammte Reserve endlich auftauchen würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[304] = { id = 304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Aufgabe", description = "Viele meiner Soldaten fielen in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über dem Thandol-Übergang zerstört wurde. Jawohl, die Dunkeleisenzwerge sind eine teuflische Brut. Soweit Roggo das in Erfahrung bringen konnte, ist der Anführer dieses Verbrecherpacks im Sumpfland ein Hexenmeister namens Balgaras der Niederträchtige. Er ist allerdings ein ziemlicher Feigling. Er kommandiert seine Soldaten herum, bleibt aber selbst im Hintergrund, jegliche Gefahr meidend.\n\nWenn Ihr diesen rückgratlosen Abschaum finden könnt, erschlagt ihn und bringt mir sein Ohr. Ich werde Euch dafür entlohnen, {class}.", sourceObjective = "Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr.", progress = "Konntet Ihr Balgaras den Niederträchtigen schon aufspüren, {class}? Er weicht uns schon eine ganze Weile aus.", completion = "Balgaras der Niederträchtige ist endlich tot. Wenn sein Tod auch die vielen unschuldigen Zwerge nicht zurückbringt, die sinnlos durch seine Hand starben, so wird dies doch zum Seelenfrieden derer beitragen, die überlebt haben. Nachdem Balgaras nun tot ist, sollte es ein Leichtes sein, mit dem restlichen Dunkeleisenpack fertig zu werden. Jetzt müssen wir den Abschaum auslöschen, bevor ein neuer Anführer in diese Gegend entsandt wird.\n\nIhr habt Eure Sache gut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[305] = { id = 305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Ausgrabungstrupp", description = "Wie schön, Ihr müsst der Späher sein, den Longbraid zu schicken versprach. Ihr könnt Euch nicht vorstellen, wie besorgt ich war.\n\nMeine Frau, Merrin, hat mir im letzten Monat jede Woche Briefe geschickt. Sie gehört zum Whelgar-Ausgrabungstrupp. Aber es sind fast zwei Wochen seit unserem letzten Briefwechsel vergangen. Irgendetwas ist bestimmt schief gelaufen!\n\nLongbraid versprach, dass er einen Späher schicken würde, der sich dort mal umsieht, wenn wir nicht bald etwas vom Trupp hören. Ich nehme mal an, dieser Späher seid Ihr, {name}. Findet Merrin in der Ausgrabungsstätte im Osten!", sourceObjective = "Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt.", completion = "Oh, dank sei den Himmeln, dass Ihr hier seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[306] = { id = 306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Ausgrabungstrupp", description = "Es war grauenhaft! Wir hatten einige seltene Artefakte enthüllt und fingen an, welche von diesen großen Knochen zu finden.\n\nBevor wir wussten, wie uns geschah, überrannten diese Scheckigen Raptoren die Ausgrabungsstätte. Viele ließen ihr Leben.\n\nOrmer hier rettete - ganz tapfer - den Ausgrabungsleiter und mich. Er verteidigte uns, während wir Schutz suchten. Jetzt sind wir gefangen. Und unsere harte Arbeit liegt in Trümmern.\n\nHier, nehmt diese Nachricht mit zurück zu meinem süßen Tarrel. Sie wird ihm die Situation klarmachen.", sourceObjective = "Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück.", progress = "Habt Ihr Merrin gefunden? Hat sie eine Nachricht geschickt?", completion = "Welch grausige Neuigkeiten! Immerhin haben 3 von ihnen überlebt. Doch wann wird das Töten endlich aufhören? Ich sehne mich nach dem Tag, an dem König Magnis Untertanen ohne Angst leben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[307] = { id = 307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Pfoten", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", sourceObjective = "Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.\n\nKehrt dann zu Gebirgsjäger Stormpike zurück.", progress = "Habt Ihr die Bergarbeiter-Ausstattung, {name}?", completion = "Habt Ihr da drin viele Kobolde gesehen? Ich kann den Befehl, sie aus der Mine zu werfen, kaum erwarten. Der Gedanke daran, wie ihre schmutzigen Hände in unserer Mine herumkratzen, verursacht mir Bauchschmerzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[308] = { id = 308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarvens Ablenkung", progress = "Hmpf! Hier steht so viel Alkohol herum, aber ich habe strikte Befehle, ihn nicht anzurühren. Wenn ich nur einen Schluck unseres Donnerbiers bekommen könnte... das würde meinen Verstand anregen, ehrlich!", completion = "Für mich? Ihr seid ein wahrer Held, {name}!" }
quests[309] = { id = 309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschützen der Fracht", description = "Bereit zum Aufbruch, {name}?\n\nAls Erstes müssen wir dieses Pulver zu Ironband bringen. Für mich allein wäre es zu viel zu tragen und diese Gegend kann gefährlich werden - und wer weiß, was diese Dunkeleisenzwerge noch für mich bereithalten?\n\nIch werde mich viel besser fühlen, wenn Ihr mitkommt.", sourceObjective = "Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis.", completion = "Oh, gelobt sei das Licht, dass das Pulver hier ist. Allerdings bringt Ihr auch Besorgnis erregende Neuigkeiten. Wenn ich nur daran denke, dass die Dunkeleisenzwerge Sympathisanten haben, die solches Material für ihre heimtückischen Pläne beschaffen können.\n\nDoch das ist eine Angelegenheit, um die sich jemand anderes zu gegebener Zeit kümmern muss. Ich muss dieses Pulver einer guten Verwendung zuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[310] = { id = 310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittere Rivalen", description = "Ich muss zugeben, diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist! Vielleicht könnt Ihr mir helfen, ihnen diese Lehre zu erteilen...\n\nHier, nehmt dieses Fass mit Gerstenbräu. Schleicht Euch in den Keller der Brauerei Donnerbräu in Kharanos und vertauscht es mit einem ihrer Fässer Donnerbier. Dann werden wir ja sehen, ob ihre Kundschaft mein Gebräu lieber mag als ihres!\n\nAch ja, und falls die Fässer bewacht sein sollten, müsstet Ihr eventuell den Wächter irgendwie ablenken...", sourceObjective = "Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu.", progress = "Die Datumsangabe auf diesem Fass legt nahe, dass es demnächst angestochen werden wird.", completion = "Schnell stellt Ihr Marleths Fass voll Gerstenbräu zwischen die Fässer der Brauerei Donnerbräu.", sourceObjectiveStatus = "unverified-source-field" }
quests[311] = { id = 311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Marleth", description = "Nachdem Ihr ein Fass von Marleths Gerstenbräu im Keller der Brauerei Donnerbräu abgestellt habt, schnappt Ihr Euch zum Beweis ein Fass Donnerbier...", sourceObjective = "Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier.", progress = "Habt Ihr den Austausch vollzogen?", completion = "Nicht schlecht, {name}! War es schwierig, an der Wache vorbeizukommen?\n\nEgal - vielen Dank, und wenn Ihr jemals ein Starkbier mit Pepp haben wollt, denkt an die Gerstenbräus!", sourceObjectiveStatus = "unverified-source-field" }
quests[312] = { id = 312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tundra MacGranns gestohlene Vorräte", description = "Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meinem Fleisch-Spind davongemacht. Er wird allerdings nicht durch das Thorium kommen. Ich wiederum werde verhungern, wenn ich mein Fleisch nicht wiederbekomme.\n\nIhr seht verstohlener aus als ich. Vielleicht könnt Ihr meinen Vorrat wiederbeschaffen? Ich würde es mit meinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.", sourceObjective = "Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten.", progress = "Habt Ihr es geschafft, an den Inhalt meines Fleisch-Spindes ranzukommen, {name}?", completion = "Was für eine gute Seele Ihr doch seid, {name}! Dank Eurer Tapferkeit werde ich nicht hungern müssen, wenn in der kalten Jahreszeit die Schneestürme toben.", sourceObjectiveStatus = "unverified-source-field" }
quests[313] = { id = 313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der altgediente Bau", description = "Nicht jeder ist dazu geschaffen, eine Belagerungsmaschine zu fahren. Dazu braucht man eine eiserne Hand und Nerven aus Stahl... zum Glück besitze ich beides! Wie steht's mit Euch? Wie groß ist euer Talent? Wollt Ihr es mir nicht zeigen?\n\nWie auch immer... ich versuche gerade, meine Maschine, Trollplow, etwas gemütlicher zu machen. Wie wäre es, wenn Ihr mir einen Haufen Wendigomähnen aus dem altgedienten Bau westlich von Kharanos besorgt? Diese Mähnen könnten einen tollen Teppich für das Innendeck abgeben!", sourceObjective = "Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear.", progress = "He, {name}. Wart Ihr schon im altgedienten Bau? Diese Wendigos können ziemlich heftig sein.", completion = "Oh ja, diese Mähnen sind genau richtig! Ihr zeigt viel Schneid, {class} - ich wette, man kann noch viele großartige Taten von Euch erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[314] = { id = 314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herde beschützen", description = "Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht. Da der Großteil von König Magnis Armee irgendwo in weit entfernten Landen an der Seite der Allianz kämpft, ist niemand mehr da, der Vagash in Schach halten könnte.\n\nVielleicht seid Ihr tapfer genug, die Bestie aufzuspüren und zu erschlagen. Bringt mir einen Fangzahn der Bestie, und ich werde Euch belohnen. Vagash lauert direkt oberhalb der Ranch hier, aber seid gewarnt, die Bestie ist tödlich.", sourceObjective = "Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt.", progress = "Vagash terrorisiert immer noch die Herde! Bitte helft uns, indem Ihr die elende Bestie umbringt.", completion = "Sehr gut gemacht! Veron wird begeistert sein, wenn er die gute Nachricht vernimmt. Vagash zu töten, kann keine leichte Aufgabe gewesen sein. Ich schätze, Ihr werdet eines Tages Seite an Seite mit König Magnis Mannen an der Allianzfront kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[315] = { id = 315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Perfekte Starkbier", description = "Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden...\n\nWeit oben in den Bergen im Osten bauen die Trolle der Frostmane eine Pflanze an, Schimmerkraut genannt. Sie verwenden sie in ihren seltsamen Stammesritualen. Wir Zwerge haben bisher keine wirkliche Verwendung dafür gefunden, aber sie hat einen einzigartigen Geschmack... und ich möchte damit in meinen Gebräuen herumexperimentieren.\n\nBesorgt mir etwas Schimmerkraut von den Sehern der Frostmane oder klaut es aus den Schimmerkrautkörben der Trolle.", sourceObjective = "Bringt Rejold Gerstenbräu in Brewnall 6 Schimmerkräuter.", progress = "Habt Ihr das Schimmerkraut? Ich habe eine Fuhre Starkbier so gut wie braufertig und möchte das Kraut versuchsweise in diese Mischung mit hineinwerfen.", completion = "Großartig! Ich kann es kaum erwarten, sie in einigen meiner Rezepte auszuprobieren. Ich glaube, in ein bestimmtes würde es wunderbar hineinpassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[317] = { id = 317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Jetsteam", description = "Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Jetsteam mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Steelgrill an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?\n\nIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des altgedienten Baus.", sourceObjective = "Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab.", progress = "Die Vorbereitungen laufen gut. Wie geht es mit der Jagd voran?", completion = "Bei Magnis Bart, Ihr habt wirklich ganz schön viel gejagt!! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[318] = { id = 318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immerschimmer", description = "Rejold Gerstenbräu experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige... nun, einige hauen selbst den stärksten Zwerg um.\n\nEr lebt in Brewnall, westlich von Kharanos, und ich will Immerschimmer, eines seiner Getränke. Es wird mich warmhalten, während ich in der Kälte unterwegs bin.\n\nAußerdem brennt das gesegnete Zeug so heiß, dass ich es in Jetsteams Brennofen kippen kann, um einen Energieschub zu erzeugen! Diese nette Taktik hat mich schon aus mehr als einer haarigen Situation gerettet.", sourceObjective = "Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer.", completion = "Bellowfiz braucht etwas von meinem Immerschimmer? Hm... in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[319] = { id = 319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für etwas Immerschimmer", description = "Ich habe ein Fässlein mit Immerschimmer zur Hand, aber... könnt Ihr mir einen Gefallen tun? Brewnall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah.\n\nWir haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn Ihr Euch für uns um diese Tiere kümmern könntet, hätten wir mehr Zeit für unser Handwerk und unsere Braukunst.", sourceObjective = "Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück.", progress = "Habt Ihr Euch um die wilden Tiere gekümmert?", completion = "Danke, {name}. Es wird angenehm sein, unser Handwerk auszuüben, ohne ständig irgendwelches Knurren und Schnauben vor dem Dorf zu hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[320] = { id = 320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Bellowfiz", description = "Hier habt Ihr Euer Fässlein mit Immerschimmer, {name}. Und wie gesagt, vielen Dank für die Jagd kürzlich.", sourceObjective = "Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer.", progress = "Habt Ihr den Immerschimmer bekommen können?", completion = "Ja, das ist genau richtig. Ich denke, ich werde gleich mal eine Flasche aufmachen und einen Schluck zu mir nehmen...", sourceObjectiveStatus = "unverified-source-field" }
quests[321] = { id = 321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtgeschmiedetes Eisen", description = "Diese Schiffswracks hier vor der Küste sind die verlorene dritte Flotte von Kul'Tiras, die während des letzten großen Krieges von roten Drachen verbrannt und versenkt wurde.\n\nDie Flotte stammte aus Lordaeron, bis auf ein Schiff, einen elfischen Zerstörer: die Flying Osprey. Es transportierte eine Ladung Lichtgeschmiedetes Eisen und schloss sich der dritten Flotte aus Sicherheitsgründen an. Welche Ironie, dass es von denselben Drachen versenkt wurde... \n\nGenug Geschichte. Die Flying Osprey liegt südlich vom Hafen von Menethil auf Grund. Wenn Ihr das Lichtgeschmiedetes Eisen darin finden könnt, bringt es zu mir.", sourceObjective = "Durchsucht das Wrack der FLYING OSPREY im Sumpfland.", completion = "Diese Truhe ist vollgesogen und seitlich aufgebrochen. Viele Klauenspuren verunstalten sowohl die Innen- wie auch die Außenseite der Truhe... als hätten Murlocs sie durchsucht und ihren Schatz gestohlen.\n\nDoch ganz tief in der Truhe versteckt findet sich ein einzelner Lichtschmiedeblock. Dummerweise werden noch viele weitere benötigt, wenn man genug Metall zusammenbekommen möchte, um eine Waffe daraus zu fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[322] = { id = 322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnete Waffe", description = "Im Zwergendistrikt von Stormwind gibt es einen zwergischen Waffenschmied, der Lichtgeschmiedetes Eisen verarbeiten kann. Er heißt Grimand Elmore.\n\nIch habe das von Euch gefundene Eisen in eine Kiste gepackt. Bringt sie zu Grimand und erzählt ihm Eure Geschichte. Ich bin mir sicher, er wird jemandem, der auf einem Kreuzzug wie dem Euren ist, gefällig sein und Euch eine Waffe schmieden - eine Waffe, vor der sich sogar Morbent Fel fürchten wird.", sourceObjective = "Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken.", progress = "Wie kann ich Euch behilflich sein, {class}?", completion = "Das ist eine ganz schöne Geschichte, die Ihr da erzählt. Und dann habt Ihr auch noch Lichtgeschmiedetes Eisen! Ich habe seit Jahren nicht mehr mit dieser Art Eisen gearbeitet. Es wird mir eine Ehre sein, es erneut zu formen. Und Ihr müsst später mit der Geschichte Eurer Schlacht gegen den Totenbeschwörer zurückkehren.\n\nAber wir greifen den Dingen vor. Erstmal kümmen wir uns um Eure Waffe gegen Morbent Fel...", sourceObjectiveStatus = "unverified-source-field" }
quests[323] = { id = 323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Morbent Fel ist ein Totenbeschwörer und ein Verbündeter der dunklen Reiter. Ich würde Euch ja erlauben, Euch der Macht von Morbent Fel entgegenzustellen, aber ich werde Euch erst gegen diese widerwärtige Satanskreatur kämpfen lassen, wenn ich Eure wahre Stärke kenne.\n\nIhr habt mir Eure Tapferkeit bereits bewiesen, aber wenn Ihr dem Totenbeschwörer wirklich trotzen wollt, dann beweist Euer Geschick zuerst an seinen Dienern.", sourceObjective = "Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück.", progress = "Kämpft hart, {name}. Und verzweifelt nicht, denn die Verzweiflung ist die größte Waffe des Bösen.", completion = "Euer Kampfgeschick, {name}, steht außer Frage. Eure Entschlossenheit könnte uns tatsächlich das Ende von Morbent Fel erleben lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[324] = { id = 324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Blöcke", description = "Nachdem Ihr den einzelnen Lichtschmiedeblock aus der voll gelaufenen Kiste genommen habt, ist Euch klar, dass die Murlocs wohl den Rest gestohlen haben. Jagt die Murlocräuber in der Nähe des Wracks der Flying Osprey, um an das verloren gegangene Lichtgeschmiedetes Eisen zu kommen.", sourceObjective = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück.", progress = "Habt Ihr das Lichtgeschmiedetes Eisen gefunden, das Ihr braucht?", completion = "Ah, Ihr habt es bekommen! Jetzt lasst uns dieses Lichtgeschmiedetes Eisen in eine nützliche Form hämmern, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[325] = { id = 325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnet und bereit", description = "Hier ist die Waffe gegen die Satanskreatur, von der Ihr spracht. Ihr seid bestens vorbereitet, {name}. Viel Glück, und ich freue mich schon darauf, von Eurer Ruhmestat zu hören!", sourceObjective = "Bringt Morbents Bann zu Sven im Dämmerwald.", progress = "Hallo, {name}. Ihr wart nicht allzu lange weg, aber ich sehe ein Feuer in Euren Augen, das dort vorher noch nicht leuchtete.", completion = "Ah, das wird Sicherheit gegen die Satanskreatur Morbent Fel geben! Gut gemacht!\n\nIhr seid bereit. Morbent Fel wird fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[328] = { id = 328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der versteckte Schlüssel", description = "In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel.\n\nUnd nach genauerem Studium seiner Notizen finden sich in den verschiedenen Dokumenten einige Verweise auf eine \"sichere Geldkassette\". Die Geldkassette befindet sich irgendwo innerhalb des Vorratslagers - des Höhlenkomplexes weiter hinten in Kurzens Truppenlager.\n\nWenn diese sichere Geldkassette gefunden wird und der kleine Messingschlüssel ihn öffnen kann, dann kann das Geheimnis um Thorsens Entdeckung vielleicht offenbart werden.", sourceObjective = "Verwendet den kleinen Messingschlüssel, um Buchhalter Herods Geldkassette zu öffnen.", progress = "Die Geldkassette ist erstaunlich groß, mit Bronze beschlagen, sehr stabil gebaut und sehr schwer.", completion = "Als Ihr die Geldkassette öffnet, wird klar, dass dies der Ort ist, an dem Herod seine wertvolleren Münzen und Gegenstände aufbewahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[329] = { id = 329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entlarvte Spion", description = "Unter den Wertgegenständen in der Geldkassette befindet sich eine schlammverschmierte, gekritzelte Notiz. Wenn sie auch kaum lesbar ist, so scheint es, als wäre es eine Abhandlung über den Gefreiten Thorsen. Sie beschreibt ausführlich seine Patrouillenrouten, mit wem er so spricht und wie er seine Zeit bei den Rebellen verbringt. Sie ist nur mit einem einzelnen Buchstaben unterschrieben: -M.\n\nDennoch muss, wer auch immer diese Notiz verfasst hat, stets in Thorsens Nähe gewesen sein. Wer auch immer diese Notiz verfasst hat, ist der Verräter im Rebellen-Lager.", sourceObjective = "Bringt die schlammverschmierte Notiz zu Lieutenant Doren im Rebellen-Lager.", progress = "Habt Ihr herausgefunden, wer von Thorsens Geheimnis wusste? Gibt es einen Verräter unter uns?", completion = "Danke, {name}. Diese Notiz ist der Hinweis, den wir brauchen, um den Verräter aufzustöbern!", sourceObjectiveStatus = "unverified-source-field" }
quests[330] = { id = 330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouillen-Pläne", description = "Die Notiz, die Ihr mir gegeben habt, ist mit einem \"-M\" unterzeichnet... Ich weiß nicht, was das heißen könnte.\n\nAber... die Notiz sagt auch aus, dass diese Person letzte Woche die gleichen Patrouillenrouten wie Thorsen hatte. Also muss, wer auch immer mit Thorsen letzte Woche auf Patrouille war, der Verräter sein!\n\nGeht zu Corporal Sethman. Er kümmert sich um die Patrouillenpläne und wird Euch sagen können, wer mit Thorsen unterwegs war.", sourceObjective = "Sprecht mit Corporal Sethman.", completion = "Oh, klar kann ich das für Euch überprüfen. Mal sehen... letzte Woche war es... \n\n... nun, es war Gefreiter Merle, der mit Thorsen eingeteilt war. Sie hatten die gesamte letzte Woche die gleichen Patrouillenzeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[331] = { id = 331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Doren", description = "Wollte Lieutenant Doren, dass Ihr Euch mit diesen Patrouillen-Informationen wieder bei ihm meldet?", sourceObjective = "Sprecht mit Lieutenant Doren.", completion = "Es schmerzt mich, herauszufinden, dass es Merle war, der uns verraten hat. Er war immer ein tapferer Soldat, und ich dachte, sein Herz sei rein. Aber es ist eine große Erleichterung, dass Ihr ihn entlarvt habt - mit einem Spion wie ihm unter uns... würden wir Colonel Kurzen nicht lange standhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[332] = { id = 332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weinladen-Werbung", description = "Wenn Ihr Euch mit irgendwem über Weine unterhaltet, werdet Ihr erfahren, dass wir Gallinas die besten Weine in ganz Stormwind verkaufen. Wir sind auch nicht weit weg, immer noch innerhalb des Handelsdistrikts entlang der herrlichen Kanäle der Stadt.\n\nHier, nehmt dieses Flugblatt. Bringt es meiner Schwester Suzetta in unseren Laden, und Ihr erhaltet eine Gratis-Flasche unseres berühmten Pinot Noir. Ihr werdet es nicht bereuen!", sourceObjective = "Geht zum Weingut Gallina und gebt Suzetta Gallina den Wein-Gutschein, um eine kostenlose Flasche Wein zu erhalten.", progress = "Seid gegrüßt und fühlt Euch willkommen, edler Herr. Habt Ihr schon einmal einen unserer ausgezeichneten Weine versucht?", completion = "Ah, Ihr wart also bei Renato? Na dann, hier, bitte, werter Herr. Eine Flasche unseres außergewöhnlichen Pinot Noir. Ihr werdet nirgendwo in Azeroth etwas Vergleichbares finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[333] = { id = 333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harlan braucht Nachschub", description = "Wir hatten hier in der letzten Zeit viel Betrieb. Es scheint so, als wollte wirklich jeder Rüstungen und robuste Kleidung kaufen. Als würden alle eine kalte, harte Jahreszeit erwarten... \n\nAber das sind alles Zukunftssorgen. Meine heutige Sorge ist eher, dass mir die gestrickten Kleidungsstücke ausgehen. Ich brauche eine weitere Fuhre von unserem Lieferanten.\n\nWenn Ihr diesen Auftrag zu Rema Schneider in die Schneiderei und Anpasserei am Kanal bringen könntet, währe ich Euch sehr dankbar.", sourceObjective = "Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema SchneiderHarlan Bagleys Kleidungs-Auftrag.", progress = "Ihr bringt Nachricht von Herrn Bagley?", completion = "Hier steht, dass Harlans Geschäfte florieren. Das sind gute Neuigkeiten, aber ich frage mich, wozu die Leute all diese Rüstungen brauchen. Ich habe nichts von einem Krieg gehört... gibt es da etwas, was uns die Adligen nicht erzählen?\n\nNun gut, danke, dass Ihr die Anfrage überbracht habt. Hier ist Eure Bezahlung, und ich werde dafür sorgen, dass Harlan seine Lieferung erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[334] = { id = 334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Thurman", description = "Mein Sohn Thurman ist Lehrling beim Konfektionsgeschäft Larson im Magierviertel. Er hatte es heute etwas eilig und vergaß seine Schere und Nadeln. Ich weiß, ein großer {class} wie Ihr hat bestimmt wichtige Aufgaben zu erledigen, aber ohne sein Handwerkszeug kann er seine Lehrarbeiten nicht erledigen!\n\nBitte, {name}. Könnt Ihr meinem Sohn sein Nähkästchen vorbeibringen? Das Konfektionsgeschäft Larson ist einer von zwei Kleiderläden im Magierviertel - es ist das, das etwas weiter drin liegt, ganz in der Nähe des Magierturms.", sourceObjective = "Geht zum Konfektionsgeschäft Larson im Magierviertel von Stormwind und gebt Thurman Schneider sein Nähkästchen.", progress = "Seid Ihr hier, um Kleidung zu kaufen?", completion = "Oh, verflucht! Ich dachte, wenn ich mein Nähzeug vergesse, muss ich heute nicht arbeiten. Ich schätze, jetzt muss ich den Larsons beim Nähen helfen... \n\nNa ja. Ich denke, das Vergnügen muss wohl noch etwas warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[335] = { id = 335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nobles Bräu", description = "Lord Wishock sorgt im Oberhaus ganz schön für Unruhe. Er wurde auf unseren kleinen \"Betrieb\" hier unten aufmerksam gemacht und propagiert jetzt eine genaue Untersuchung. Ich habe einen Plan, um Wishock... zu beschäftigen... aber ich benötige Eure Hilfe. \n\nEs gibt eine Blume, die in Stalvans Garten in den Außenbezirken von Dunkelhain wächst. Diese kleine weiße Blume ist als Tilloaträne bekannt. Ich werde außerdem eine Bisamwurzel brauchen, die man nur am Fuße des Wasserfalls tief unter dem Stonewroughtdamm im Sumpfland findet.", sourceObjective = "Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt.", progress = "Wishock wird bald genug Unterstützung haben, um uns jede Menge Ärger zu machen. Habt Ihr es endlich geschafft, Euch die Tilloaträne oder die Bisamwurzel anzueignen?", completion = "Ganz exzellent! Dies sind wirklich sehr schöne Exemplare!", sourceObjectiveStatus = "unverified-source-field" }
quests[336] = { id = 336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nobles Bräu", description = "Lord Wishock hat, wie alle Menschen, seine Schwächen. Bei seiner handelt es sich um eine Vorliebe für alkoholische Getränke. Seine Scheinheiligkeit ist verblüffend. Dieser spießige Trottel verbringt seine Tage damit zu versuchen, unsere kleine \"Taverne\" schließen zu lassen, während er seine Nächte im Obergeschoss zubringt und dabei Rechnungen anschreiben lässt, die er niemals bezahlt. Na, mal sehen, wie Wishock dieses besondere Gebräu schmeckt, das ich für ihn vorbereitet habe: Blackclaw-Starkbier. Es haut ziemlich rein, {name}.\n\nBringt es ihm und seht, wie es ihm schmeckt. Höchstwahrscheinlich treibt sich der alte Trottel in der Halle der Bittsteller herum.", sourceObjective = "Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier.", progress = "Seht Ihr nicht, dass ich beschäftigt bin? Meine Worte müssen gehört werden! Ich bin sehr wichtig für die Zukunft dieses Königreichs!\n\nOh... was habt Ihr denn da? Na, das sieht doch nach einem erfrischenden Getränk aus...", completion = "Ah, danke, dass Ihr mir dieses lecker aussehende Starkbier gebracht habt, Diener. Hier habt Ihr eine Kupfermünze. Und jetzt verschwindet aus meinem Blickfeld und lasst mich mein Getränk genießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[337] = { id = 337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein altes Geschichtsbuch", description = "Obwohl der Einband dieses Buches von Kratzern überzogen und von Schmutz verkrustet ist, kann man auf dem Buchrücken noch immer die Worte \"Die Geschichte von Stormwind\" lesen. Wenn man das Buch aufmacht, kann man das Siegel der Bibliothek von Stormwind erkennen, das deutlich auf der ersten Seite prangt.\n\nEs sieht so aus, als hätte jemand dieses Buch ausgeliehen, aber nie zurückgegeben.", sourceObjective = "Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück.", progress = "Oh! Was ist denn das für ein altes Buch, was Ihr da habt? Kann ich es mal sehen?", completion = "Ach du liebe Güte! Dieses Buch hat zuletzt in diesen Regalen gelegen, noch bevor Stormwind vor vielen Jahren wieder aufgebaut wurde. Es muss natürlich restauriert werden, denn es ist in einem üblen Zustand, aber es wäre mir eine Ehre, es in unsere Sammlung seltener Bücher aufzunehmen.\n\nDanke, werter Herr. Bitte nehmt dies als Bezahlung dafür an, dass Ihr das Buch zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[338] = { id = 338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grünen Hügel des Schlingendorntals", description = "Meister Nesingwary wird furchtbar wütend sein, wenn er das herausfindet!\n\nEr vertraute mir das Manuskript für seinen Roman, \"Die Grünen Hügel des Schlingendorntals\", zum Korrekturlesen an. Es lief auch alles glatt, aber dann wehte ein großer Windstoß durch das Lager und hat die Seiten überall verteilt.\n\nIch konnte die meisten Seiten wieder zusammensuchen, aber viele sind noch über den halben Dschungel verstreut. Sammelt die Seiten, mit denen man die vier Kapitel vervollständigen kann.\n\nIch werde Euch helfen, sie zu ordnen. Bringt mir die Kapitel zurück, wenn Ihr alle vier beisammen habt.", sourceObjective = "Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals”. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück.", progress = "Habt Ihr die Kapitel bereits zusammengefügt, {name}?", completion = "Ihr habt mir sicherlich einen Haufen Ärger erspart, {name}! Ich kann Euch gar nicht genug danken. Es dürfte nun nicht mehr lange dauern, bis man Meister Nesingwarys Buch in Bibliotheken überall auf der Welt finden wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[339] = { id = 339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel I", description = "Kapitel I war ziemlich fesselnd! Meister Nesingwary baut den Hintergrund der Geschichte auf und erwähnt seine Jagdgefährten, mich eingeschlossen! \n\nAber das tut gerade nichts zur Sache. Lasst mich mal sehen, welche Seiten noch fehlen. So wie es aussieht sind die Seiten 1, 4, 6 und 8 immer noch irgendwo da draußen im Dschungel!", sourceObjective = "Bringt Barnil Stonepot die Seiten 1, 4, 6 und 8 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel I zu vervollständigen.", progress = "Ich nehme nicht an, dass Ihr es geschafft habt, die Seiten 1, 4, 6 und 8 aufzuspüren? Uns fehlen nur diese vier, um Kapitel I wieder zusammenzusetzen.", completion = "Endlich! Kapitel I ist vollständig!", sourceObjectiveStatus = "unverified-source-field" }
quests[340] = { id = 340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel II", description = "Kapitel II war voll gestopft mit aufregenden Geschichten von der Panther- und Tigerjagd. Ich könnte mir dafür in den Hintern treten, dass ich die Seiten habe davonfliegen lassen. \n\n Es sieht aus, als hätte ich alle Seiten wiedergefunden, bis auf die Seiten 10, 11, 14 und 16.", sourceObjective = "Bringt Barnil Stonepot die Seiten 10, 11, 14 und 16 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel II zu vervollständigen.", progress = "Wir brauchen immer noch die Seiten 10, 11, 14 und 16, um Kapitel II zu vollenden, {name}.", completion = "Kapitel II ist endlich vollständig! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[341] = { id = 341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel III", description = "Kapitel III gefiel mir am besten. Es erzählt von Sire Erlgadins und Lady Rouacks erstem Blattschuss mit einem Zwergen-Gewehr. Und am Ende von Kapitel III, Mann, solche eine Spannung! \n\nWenn ich das richtig sehe, brauchen wir noch die Seiten 18, 20, 21 und 24, um das Kapitel fertig zu stellen. Diese Seiten sind irgendwo da draußen...", sourceObjective = "Bringt Barnil Stonepot die Seiten 18, 20, 21 und 24 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel III zu vervollständigen.", progress = "Hattet Ihr Glück mit den Seiten 18, 20, 21 oder 24? Das sind die einzigen, die wir brauchen, um Kapitel III zusammenzusetzen.", completion = "Puh! Gute Arbeit, {name}. Kapitel III ist jetzt wieder beisammen!", sourceObjectiveStatus = "unverified-source-field" }
quests[342] = { id = 342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitel IV", description = "Ah, Kapitel IV; Das große Finale! Und was für ein Ende es war! \n\nUns fehlen nur drei Seiten aus diesem Kapitel. Wir brauchen die Seiten 25, 26 und 27, um Kapitel IV wieder zusammenzusetzen.", sourceObjective = "Bringt Barnil Stonepot die Seiten 25, 26 und 27 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel IV zu vervollständigen.", progress = "{name}, wir brauchen nur drei Seiten, um Kapitel IV fertig zu stellen. Habt Ihr mittlerweile die Seiten 25, 26 oder 27?", completion = "Phantastisch! Jetzt haben wir Kapitel IV fertig!", sourceObjectiveStatus = "unverified-source-field" }
quests[343] = { id = 343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reden über Kraft", description = "Ich werde eine Rede über die Kraft des Geistes halten, und ich würde dazu gern einige Auszüge aus einem bestimmten Buch über Metallurgie zitieren - \"Belastbarkeit von Eisen\". Eine Abschrift dieses Buches dürfte sich in der königlichen Bibliothek der Burg Stormwind finden. Könnt Ihr es für mich holen? Wenn dem so ist, dann mögen die Segnungen des Lichts mit Euch sein!\n\nDie königliche Bibliothek ist sehr groß, aber der oberste Bibliothekar, Milton Sheaf, kennt jedes Regal, als wäre es sein eigenes Kind. Sprecht mit ihm, und er wird Euch das Buch holen.", sourceObjective = "Geht in die königliche Bibliothek der Feste von Stormwind und sprecht mit Milton Sheaf. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt.", completion = "Metallurgie? Oh ja, wir haben viele Bücher über dieses Thema, und wir helfen Bruder Kristoff gern mit seiner Rede! Nun sagt... welches Buch genau war das noch gleich, das der gute Bruder benötigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[344] = { id = 344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder Paxton", description = "Belastbarkeit von Eisen? Ja, ich kenne das Buch. Ziemlich gut, vor einigen Jahrzehnten von dem Zwergenminenarbeiter Margulf Blaggon geschrieben. Er verbrachte den Großteil seines Lebens tief in den Bergen von Khaz Modan, Erze schürfend. Kluger Kerl!\n\nAber wo war ich doch gleich? Ach ja, die \"Belastbarkeit von Eisen\"! Ich fürchte, das Buch wurde in die Abtei von Nordhain verlegt. Der Verwalter der Bibliothek der Abtei, Bruder Paxton, wollte eine Kopie des Buches für seine eigenen Regale anfertigen.\n\nDas war allerdings vor Monaten. Ich frage mich, warum er so lange dafür braucht...", sourceObjective = "Sprecht mit Bruder Paxton in der Abtei von Nordhain.", completion = "Herr Sheaf möchte wissen, wo sein Buch ist? Nun, das ist etwas peinlich. Ich habe das Buch, aber ich bin immer noch dabei, es abzuschreiben und daher noch nicht wirklich bereit, das Original wieder herzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[345] = { id = 345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tinten-Zutaten", description = "Ich will meine Abschrift von \"Belastbarkeit von Eisen\" schon länger fertig stellen, aber... \n\nNun, ich stelle für die Bücher, die ich abschreibe, meine Tinte selbst her, versteht Ihr? Es handelt sich um mein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell! Meine letzte Portion ist ausgetrocknet, bevor ich die Abschrift beenden konnte, und ich hatte bisher keine Gelegenheit, mehr Tinte herzustellen!\n\nUm mehr herzustellen, benötige ich Rethbaneisenerz aus dem Rotkammgebirge. Großknecht Oslow in Seenhain ist mein üblicher Lieferant.", sourceObjective = "Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz.", completion = "Ihr braucht was?? Vielleicht ist es Euch nicht aufgefallen, aber wir sind damit beschäftigt, Seenhains Verteidigungsanlagen zu befestigen und die Schäden von den letzten Orcangriffen zu reparieren. Wenn Ihr Rethbaneisenerz braucht, dann müsst Ihr es Euch schon selbst holen!", sourceObjectiveStatus = "unverified-source-field" }
quests[346] = { id = 346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Kristoff", description = "Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von \"Belastbarkeit von Eisen\" haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir Leid.", sourceObjective = "Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\".", progress = "Konntet Ihr das Buch finden?", completion = "Das ist es! Danke, {name}. Möge das Licht Euren Körper und Eure Seele hell erleuchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[347] = { id = 347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethbanerz", description = "Rethbanerz wurde nach dem Mann benannt, der es als Erster entdeckt hat, Bart Rethban. Wenn es geschmolzen wird, ist es nicht so stark wie Eisen, aber sein Erz hat eine dunkle, glatte Farbe, die einige Schreiber in ihren Farbtinten verwenden. Man kann es in den Rethbanhöhlen nördlich von hier finden.\n\nWir haben normalerweise etwas davon auf Lager, aber wir sind zu sehr damit beschäftigt, uns auf Orcangriffe vorzubereiten, als dass wir welches sammeln könnten. Und nur so nebenbei... In den Rethbanhöhlen leben jetzt Rotkammgnolle und deren Zwangsarbeiter bauen das Erz selbst ab.\n\nWenn Ihr also welches benötigt, müsst Ihr es Euch selbst besorgen.", sourceObjective = "Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain.", progress = "Habt Ihr das Rethbanerz?", completion = "Oh, prächtig! Ich kann dieses Erz verwenden, um meine Farbtinte herzustellen, und kann dann die Abschrift von \"Belastbarkeit von Eisen\" fertig stellen.\n\nDanke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[348] = { id = 348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingendornfieber", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", sourceObjective = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket.", progress = "... Mutter?\n\n... so kalt... \n\n... ich fahre hinab in den wirbelnden Nether... h-h-h-halt mich fest, Mutter...", completion = "... fühle die Kraft zurückkehren... \n\nWo bin ich? Booty Bay? Ach du meine Güte! Ich hatte einen seltsamen Traum... \n\n... die Schwäche hat mich nicht vollständig verlassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[349] = { id = 349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingendornfieber", progress = "Hexendoktor Unbagwa wissen, was Mokk der Wilde mögen. Ja, ja!\n\nIch sprechen mit Geistern und lassen ihn herkommen, tue ich.\n\nAber andere Gorillabiester mögen Geistersprechen auch. Ihr beschützen Hexendoktor Unbagwa und ich lassen ihn herkommen.\n\nHexendoktor Unbagwa will erst etwas. Ihr bringen 10 Gorillafangzähne und ich fangen an Geistersprechen.", completion = "Hexendoktor Unbagwa gefallen Gorillafangzähne! Für Euch, ich reden mit Geistern. Lassen Mokk den Wilden kommen.\n\nIhr aber beschützen Hexendoktor Unbagwa vor anderen Gorillabiestern, oder kein Mokk für Euch!" }
quests[350] = { id = 350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf einen alten Freund verlassen", description = "Marzon würde ein Mitglied der Defias kontaktieren und er hat Verbindungen zu Lescovar... \n\nDa van Cleef und Thredd tot sind, wäre es schwierig, einen Richtspruch gegen Lescovar zu erwirken, denn Eure Beweise sind wertlos ohne deren Zeugnis. Und dabei wird noch nicht einmal die Tatsache berücksichtigt, dass Lescovar ja ein Adliger ist und viele Beziehungen hat. Das stellt ihn gewissermaßen über das Gesetz.\n\nWir werden weitere Hilfe benötigen. Ich tu das nur äußerst ungern, aber ich kenne jemanden, der uns helfen wird. Ihr findet Trias im Handelsdistrikt der Stadt.", sourceObjective = "Sprecht mit Elling Trias in Stormwind.", completion = "Macht Ihr Witze? Shaw bittet mich erneut um Hilfe? Der hat Nerven...\n\nDie Bruderschaft der Defias, sagt Ihr? Tja, Ihr seid wirklich der Überbringer wunderbarer Neuigkeiten, was? Als Nächstes werdet Ihr mir erzählen, dass Deathwing noch am Leben sei und die Stadt angreift.\n\nNa gut, erzählt mir alles von Anfang an. Und lasst nichts aus, was Euch vielleicht nicht wichtig erscheint. Ich muss alles wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[351] = { id = 351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet OOX-17/TN!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe und mein Leitroboter ist verloren gegangen! Ich würde Euch belohnen, wenn Ihr ihn aufspürt! Bringt dem Roboter bitte diesen Signalgeber. Hervorragend, jetzt habe ich die Koordinaten für Euch berechnet! Er ist in der Nähe der Klaffenden Schlucht in Tanaris abgestürzt!\"", sourceObjective = "Bringt das Notsignal zum Leitroboter von Oglethorpe.", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-17/TN funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[353] = { id = 353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpikes Lieferung", description = "Die Stormpikes sind ein geachteter Zwergenklan und bekannt für ihren feinen und kritischen Geschmack. Daher ist es nicht verwunderlich, dass Gringer Stormpike, ein Gebirgsjäger aus Ironforge, mich beauftragte, ihm eine Waffe zu schmieden.\n\nDie Waffe ist fertig, aber... Gebirgsjäger Stormpike ist weit weg, am fernen Loch Modan. Wenn Ihr ohnehin vorhabt, nordwärts zu reisen, könntet Ihr ihm dieses Päckchen überbringen?\n\nMeine letzte Nachricht von Gebirgsjäger Stormpike besagte, dass er im nördlichen Wachturm des Loch Modan stationiert ist.", sourceObjective = "Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan.", progress = "Ihr seid den ganzen weiten Weg von Stormwind gekommen? Ich habe gehört, es wird da unten in den Menschenlanden dank herumlaufender Briganten und Orcs etwas brenzlig. An einem solchen Ort kann ein {class} sich perfekt beweisen!", completion = "Aha! Grimand hat also endlich meine Axt fertig gestellt! Ich kann es kaum erwarten, sie an einigen Troggs und Kobolden auszuprobieren!\n\nVielen Dank, {name}. Ihr habt für diese Lieferung eine weite Strecke zurückgelegt. Hier habt Ihr ein paar Münzen für eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[354] = { id = 354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesfälle in der Familie", description = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.\n\nAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wir waren loyale Narren.\n\nDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!\n\nDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", sourceObjective = "Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste.", progress = "Habt Ihr die sterblichen Überreste der Agamands? Sind diese verfluchten Bestien endlich vernichtet?", completion = "Rache hat einen süßen Geschmack, findet Ihr nicht? Als Ihr die Agamands vernichtet habt, habt Ihr da irgendeinen Hinweis auf einen freien Willen in ihnen bemerkt? Ich hoffe es. Ich hoffe, sie hatten Angst, bevor sie in die Vergessenheit zerschlagen wurden.\n\nDas ist eine närrische Hoffnung, ich weiß. Aber es ist dennoch eine Hoffnung, die ich hege.", sourceObjectiveStatus = "unverified-source-field" }
quests[355] = { id = 355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Sevren", description = "Ihr habt mir die Überreste der Agamands gegeben und meinen Rachedurst gestillt. Aber Agamands Mühlen sind eine Bedrohung für alle Verlassenen, nicht nur für mich.\n\nIch habe mit Magistrat Sevren über Eure Heldentaten gegen die Agamands geredet, und er wünscht, mit Euch zu sprechen.", sourceObjective = "Sprecht mit Magistrat Sevren in Brill.", completion = "Coleman erzählt Gutes über Euch, {name}, wenn er von Euren erfolgreichen Vorstößen in Agamands Mühlen spricht.\n\nDie Verlassenen brauchen Eure Talente erneut...", sourceObjectiveStatus = "unverified-source-field" }
quests[356] = { id = 356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouille zur Rückendeckung", description = "Die Verteidiger auf dem Bollwerk, die Tirisfal vor den Pestländern schützen, sind immer wachsam. Aber manchmal schafft es die Geißel, an ihnen vorbeizuschlüpfen.\n\nUnser Erfolg am Bollwerk hängt an einer Ein-Fronten-Schlacht - wir können keinen Angriff von hinten zulassen, und noch weniger können wir zulassen, dass die Versorgungslinie unserer Verteidiger unterbrochen wird.\n\nUnterstützt das Bollwerk. Patrouilliert ostwärts und erschlagt alle Untoten, die Ihr findet. Seid auf Balnirs Bauernhof im Osten besonders gründlich. Es hat sich zu einem Zufluchtsort für eindringende Untote entwickelt.", sourceObjective = "Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager.", progress = "Habt Ihr einen Bericht von Eurer Patrouille?", completion = "Sehr gut. Eure Anstrengungen helfen sehr dabei, die Geißel in Schach zu halten. Meinem Vorgesetzten, Exekutor Zygand, wird eine Empfehlung zugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[357] = { id = 357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Identität des Lichs", description = "Es gibt einen Lich, der auf einer Insel im Blendwassersee im Norden haust. Obwohl er ein Verlassener mit freiem Willen ist, glaubt er, dass alle anderen Untoten Sklaven der Geißel sind, und hetzt seine Diener auf jeden, der sich ihm nähert.\n\nAber da er ein Verlassener ist, wird die Königin ihn haben wollen. Und wenn er in der Totenbeschwörung bewandert ist, dann wäre sein Wissen... recht nützlich für uns.\n\nUm etwas über seine Identität und sein Können herauszufinden, muss ich mir sein Zauberbuch ansehen. Stehlt Euch in sein Lager, verschafft es Euch und kehrt dann zu mir zurück.", sourceObjective = "Bringt das Zauberbuch des Lichs zu Bethor Iceshard in Undercity.", progress = "{name}, habt Ihr das Buch beschafft?", completion = "Sehr gut, {name}. Ich werde dieses Buch studieren und die Identität des Lichs herausfinden. Ihr habt Eurer Königin gut gedient.\n\n\n\nErstaunlich! Das Buch, das Ihr besorgt habt, gehört keinem Geringeren als Gunther Arcanus!\n\nGunther war ein bewanderter Totenbeschwörer im Leben; er und ich waren Freunde und Waffengefährten, vor der Seuche. Und nach diesem Buch zu urteilen, wurde er im Tode noch mächtiger.\n\nSeine Fähigkeiten wären ein großer Segen für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[358] = { id = 358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabräuber", description = "Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der... eindrucksvollen... Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über uns kam. \n\nDen Toten in diesen Gräbern blieb der Untod bisher erspart, aber die Geißel schickt jetzt Moderfellgnolle, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. Das können wir nicht zulassen!\n\nIhr habt zweierlei Aufgaben: Erschlagt die Moderfelle am Massengrab und in Garrens Schlupfwinkel und nehmt Euch von ihnen das Einbalsamierungssekret, das ihnen Leben verleiht.", sourceObjective = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle. \n\nBringt Magistrat Sevren in Brill 8 Einbalsamierungssekrete.", progress = "Ist Eure Aufgabe abgeschlossen? Habt Ihr diese Hundeviecher vernichtet und sie ihres Sekrets beraubt?", completion = "Meisterlich erledigt, {name}. Die Geißel irrt sich, wenn sie denkt, dass sie diese Leichen gegen uns verwenden könnte, und die Flüssigkeit, die Ihr von den  der Moderfellsklaven gesammelt habt, wird von unseren Apothekern untersucht werden. Vielleicht enthält sie Geheimnisse, die wir gegen sie verwenden können.\n\nWie gesagt, gut gemacht. Aber unser Kampf geht weiter, und dieser Konflikt wird Euch sicher noch mehr Möglichkeiten bieten, den Verlassenen Euren Wert zu beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[359] = { id = 359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlassenen-Pflichten", description = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.\n\nIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!\n\nReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", sourceObjective = "Sprecht mit Todeswache Linnea.", completion = "Magistrat Sevren will einen Bericht? Nun gut: Die Verteidiger auf dem Bollwerk halten den Großteil der Geißel in Schach, aber gelegentlich schlüpfen ein paar durch. \n\nWir haben sporadisch Aktivitäten der Geißel östlich dieses Postens gesichtet, und diese häufen sich um Balnirs Bauernhof.", sourceObjectiveStatus = "unverified-source-field" }
quests[360] = { id = 360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Magistrat", description = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.\n\nUnd solltet Ihr unterwegs welche von der Geißel sehen, schaltet sie aus - wir können sie nicht unbehelligt durch unser Land spazieren lassen.", sourceObjective = "Kehrt zu Magistrat Sevren nach Brill zurück.", completion = "Es ist beunruhigend zu hören, dass die Geißel am Bollwerk vorbeischlüpft. Der Lichkönig und seine Diener greifen uns unaufhörlich an.\n\nAber wir werden nicht nachgeben. Er wird nicht noch einmal von uns Besitz ergreifen!", sourceObjectiveStatus = "unverified-source-field" }
quests[361] = { id = 361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nie zugestellter Brief", description = "Dies ist ein Brief, der von Thurman, dem ältesten Sohn von Gregor Agamand, geschrieben wurde. Er ist an Yvette Farthing adressiert, aber er scheint nicht bei ihr angekommen zu sein...", sourceObjective = "Findet Yvette Farthing und bringt Ihr den Brief von Thurman Agamand.", progress = "Ja?", completion = "Oh... mein armer Thurman! Ich habe ihn angefleht, Agamands Mühlen mit mir und meinem Vater zu verlassen, aber seine Familienbande waren zu stark! Und ich habe es genau gewusst! Ich wusste einfach, dass Brand ihm Böses wollte! Oh, verflucht seien diese Seuche und die Geißel!\n\n<Yvettes Gesicht glättet sich und wird dann kalt.>\n\nAber Selbstvorwürfe sind etwas für die Schwachen. Als eine Verlassene habe ich neue Ziele, und Liebe ist keines davon. Ich danke Euch, dass Ihr diesen Brief überbracht habt, denn ich hatte mich schon gefragt, was mit meiner alten Liebe geschehen war.\n\nDoch dieses Leben ist vorüber. Auf ewig.", sourceObjectiveStatus = "unverified-source-field" }
quests[362] = { id = 362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spuk-Mühle", description = "Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Thurman war groß und sanft, während sein jüngerer Bruder schwach und scharfzüngig war.\n\nAls Agamands Mühlen der Seuche anheim fielen, war ich nicht überrascht zu hören, dass Devlin ihr schnell erlag. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.\n\nIch sammle die Überreste der Agamands und ich möchte den armen Devlin. Findet ihn, vernichtet ihn und bringt mir seine Knochen.", sourceObjective = "Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Farthing nach Brill.", progress = "Habt Ihr Devlin gefunden?", completion = "Danke. Devlins Knochen werden eine gute Trophäe abgeben.\n\nWenn mein kaltes Herz überhaupt Wärme finden kann, dann in dem Wissen, dass die Agamands vernichtet sind. Sie haben mich und meine Familie im Stich gelassen, als die Seuche kam - jetzt schwöre ich, dass ich ihre Überreste unter meiner Sohle zermalmen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[363] = { id = 363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsanftes Erwachen", description = "Wurde auch Zeit, dass Ihr aufwacht. Wir wollten Euch gerade mit den anderen ins Feuer werfen, aber es sieht so aus, als hättet Ihr es geschafft.\n\nIch bin Mordo, der Verwalter der Deathknell-Gruft. Und Ihr seid kein Sklave des Lichkönigs mehr.\n\nSprecht mit Schattenpriester Sarvis in der Kapelle am Fuße des Hügels, er wird Euch mehr über das erzählen, was Ihr wissen müsst.", sourceObjective = "Sprecht mit Schattenpriester Sarvis.", completion = "Noch einer der wandelnden Toten, hm? Muss ein ziemlicher Schock gewesen sein, so in der Gruft aufzuwachen, wo es nur Kälte und Mordo gab, um Euch zu begrüßen... \n\nIch sehe Verwirrung in Eurem Gesicht. Lasst mich mal versuchen, Euch unsere... Situation... zu erklären.\n\nWir wurden durch unsere neue Anführerin, Lady Sylvanas, von der Kontrolle durch den Lichkönig befreit. Die dunkle Fürstin führt uns in unserem Krieg gegen die verhasste Geißel und die Bastionen der Menschheit, die jeden unserer Schritte verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[364] = { id = 364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hirnlosen", description = "Wir Verlassenen liegen im Krieg mit der Geißel, der Armee des Lichkönigs: durch Nekromantie erweckte Armeen von Untoten, grausige Bestien des Nordens und gepeinigte Schreckgespenster.\n\nDer nördliche Teil des Dorfes wurde von den Hirnlosen überrannt, und diese müssen vernichtet werden. Vernichtet sie, zeigt ihnen keine Gnade, auch wenn sie unsere früheren Brüder und Schwestern gewesen sein mögen. Die Gefallenen sind nichts als Sklaven des Lichkönigs.", sourceObjective = "Schattenpriester Sarvis will, dass Ihr 8 hirnlose Zombies und 8 elende Zombies tötet.", completion = "Es ist schade, dass die Geißel nicht bei uns eingegliedert werden kann, denn ihre große Zahl wäre in den kommenden Schlachten sehr nützlich.\n\nDoch sie werden sich uns nicht anschließen, und daher haben wir keine andere Wahl, als sie zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[365] = { id = 365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felder des Kummers", description = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, {class}. Wenn Ihr darauf hofft, Euch der dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.\n\nIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.\n\nSobald Ihr 10 beisammen habt, bringt sie zu Apotheker Johaan nach Brill.", sourceObjective = "Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Deathknell und bringt sie zu Apotheker Johann nach Brill.", progress = "Todeswache Simmer ließ mich wissen, dass Ihr mich mit einigen dringend benötigten Reagenzien versorgen würdet. Habt Ihr bereits 10 Kürbisse gesammelt, {name}?", completion = "Ihr habt Eure Befehle gut ausgeführt, {class}. Ihr habt Euch als eine echte Hilfe für die Armee der dunklen Fürstin erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[366] = { id = 366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe des Buches", description = "Vor langer Zeit waren Gunther und ich, wie auch der jetzt der Geißel dienende Totenbeschörer Thule Rabenklaue, Freunde und Schüler beim Kirin Tor, einer Magiergesellschaft in Dalaran.\n\nGunther und ich fielen beide der Seuche anheim, aber ich dachte, er wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Es tut gut zu wissen, dass er frei ist.\n\nWir müssen ihn für uns gewinnen. Ich habe einen Zauber auf dieses Buch gelegt, der ihm, sobald er ihn sieht, zeigen wird, dass ich ebenfalls frei vom Einfluss des Lichkönigs bin. Ich hoffe, dass er sich uns anschließt, wenn er das erfährt.", sourceObjective = "Bringt Gunthers Zauberbuch zu ihm auf die \"Gunthers Zufluchtsort\" genannte Insel zurück.", progress = "Eure Meister sind Narren, Euch hierher zu entsenden, denn ich werde niemals wieder ein Sklave der Geißel sein!", completion = "Mein Buch?!? Also wart Ihr der Dieb, der es stahl!\n\nDoch... was ist das für eine neue Verzauberung darauf... Bethor? Er ist in Lordaeron?\n\nWenn es ihn immer noch gibt, dann konnte er sich vielleicht ebenfalls dem Zugriff des Lichkönigs entziehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[367] = { id = 367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Lady Sylvanas hat sich an die königliche Apothekervereinigung gewandt. Die dunkle Fürstin glaubt, dass unser Wissen, gepaart mit der neuentdeckten Magie, der Schlüssel zu Arthas' Untergang sein wird. Sie hat uns aufgefordert, eine neue Seuche zusammenzubrauen, eine Seuche, tödlicher als jedes Leiden in ganz Azeroth. Diese neue Krankheit wird Arthas' Armee der Geißel ins Verderben stürzen.\n\nMeine Studien zeigen, dass das Blut von Bestien der Schlüssel sein könnte. Bringt mir 5 Phiolen Schattenhundblut, damit ich meine Theorie ausprobieren kann.", sourceObjective = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt.", progress = "Habt Ihr 5 Phiolen Schattenhundblut gesammelt, {name}? Die Zeit drängt!", completion = "Das habt Ihr gut gemacht, {name}, und ich danke Euch für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[368] = { id = 368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Während Ihr unterwegs wart und Proben für mich gesammelt habt, haben meine Experimente ergeben, dass noch weitere Reagenzien benötigt werden, wenn sich diese Krankheit ordentlich ausbreiten soll. Ein paar unglückliche Opfer zu vergiften, ist eine Kleinigkeit. Eine ganze Welt erkranken zu lassen, erweist sich als etwas komplizierter.\n\nIch werde 5 Finsterflossenschuppen von den Murlocs in der Umgebung brauchen. Ihr findet die Kreaturen entlang der Küste im Norden oder Westen von hier.", sourceObjective = "Apotheker Johaan in der Stadt Brill benötigt 5 Finsterflossenschuppen von den Murlocs in Tirisfal.", progress = "{name}, habt Ihr 5 Finsterflossenschuppen von den Murlocs beschaffen können?", completion = "Die Schuppen sind perfekt, {name}. Genau das, was ich für dieses Gebräu brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[369] = { id = 369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Während Ihr sammeln wart, habe ich einen alten Text in einem meiner Bücher entdeckt, der darauf hindeutet, dass eine uralte Seuche Tausende unschuldiger Opfer ausgelöscht hat. Man fand später heraus, dass der tödliche Erreger im Gift der Nachtweberspinnen erhalten blieb.\n\nBringt mir etwas Gift eines heimtückischen Nachtwebers, um dieses Experiment abzuschließen. Ich möchte sehen, ob das ansteckende Element des Giftes mit meinem neuen Gebräu harmoniert. Gerüchten zufolge leben die Spinnen im östlichen Tirisfal.", sourceObjective = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt.", progress = "Habt Ihr endlich etwas Gift eines heimtückischen Nachtwebers, {name}? Das ist die letzte Komponente, die mir fehlt, um mein Experiment zu testen.", completion = "Ah, dieses Gift wird genau richtig sein, {name}. Alles andere wurde bereits mit meinem Gebräu verkocht. Jetzt bin ich endlich so weit, diesen neuen tödlichen Erreger auszuprobieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[370] = { id = 370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Die strategischen Dokumente von Exekutor Arren enthalten alle Angaben, die wir brauchen, um die menschliche Plage aus den Ländern zu tilgen. Nach diesen Informationen hat der Scharlachrote Kreuzzug Captain Perrine mit einer Brigade dem verfallenen Turm südwestlich von Brill zugeteilt.\n\nTötet Perrine, sowie 3 Zeloten und 3 Missionare und erstattet mir dann Meldung.", sourceObjective = "Exekutor Zygand in Brill möchte, dass Ihr Captain Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet.", completion = "Perrines Tod wird die dunkle Fürstin zweifelsohne zufrieden stellen. Ihr habt Eure Befehle gut ausgeführt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[371] = { id = 371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg mit dem Scharlachroten Kreuzzug", description = "Wir befinden uns noch immer im Krieg, und der Scharlachrote Kreuzzug gewinnt an Stärke. Der Bericht, den mir Exekutor Arren schickte, zeigt auf, dass die Scharlachroten Kreuzzügler ihre Überfälle von dem verfallenen Turm im südöstlichen Tirisfal, nahe Balnirs Bauernhof, unter dem Kommando von Captain Vachon ausgeführt haben.\n\nTötet Vachon, zusammen mit 5 Scharlachroten Ordensmitgliedern. Das sollte sich als vernichtender Schlag für den Kreuzzug erweisen!", sourceObjective = "Exekutor Zygand in Brill hat Euch damit beauftragt, Captain Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen.", completion = "Captain Vachons Tod wird den Vormarsch des Scharlachroten Kreuzzugs in Tirisfal deutlich verlangsamen. Aber es lauern noch andere Gefahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[372] = { id = 372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg mit dem Scharlachroten Kreuzzug", description = "Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Captain Melrache diese bösartige Truppe an.\n\nIch vertraue Euch eine besondere und gefahrvolle Mission an. Erschlagt Melrache und seine beiden Leibwachen im Namen der dunklen Fürstin.", sourceObjective = "Exekutor Zygand in der Stadt Brill möchte, dass Ihr Captain Melrache und seine beiden Leibwachen ermordet.", completion = "Das habt Ihr sehr gut gemacht, {class}. Dank unnachgiebiger Krieger wie Euch, die im Namen der Verlassenen Siege davontragen, ist unser Volk einen Schritt näher dran, Arthas ein für alle Mal zu besiegen. Ich habe ein gutes Gefühl bei Euch, Kamerad.", sourceObjectiveStatus = "unverified-source-field" }
quests[373] = { id = 373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nie verschickte Brief", description = "Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an \"Baros Alexston, Stadtarchitekt von Stormwind, Rathaus, Kathedralenplatz\".\n\nEr scheint erst vor kurzem geschrieben und versiegelt worden zu sein.", sourceObjective = "Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston.", progress = "Ja? Kann ich Euch irgendwie helfen?", completion = "Edwin van Cleef, sagt Ihr? Mit einem Brief von meiner toten Großmutter hätte ich eher gerechnet... Ihr habt ihn also getötet? Verzeiht, wenn ich das sage, aber ich bin etwas überrascht. Er war ein unvergleichlicher Krieger in seinen jungen Jahren. Lasst mich mal sehen, weswegen er mir nach so vielen Jahren auf einmal schreiben muss.\n\n<Baros überfliegt den Brief.>\n\nEdwin... Die Jahre haben dich offensichtlich kein bisschen verändert, immer noch der alte Idealist und Romantiker. Es kümmert ihn nicht, wen er verletzt, {name}. Die Rache hat ihn verzehrt. Allerdings weiß ich nicht, ob ich ihm daraus einen Vorwurf machen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[374] = { id = 374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweise des Ablebens", description = "Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.\n\nVarimathras, Offizier der dunklen Fürstin, kümmert sich persönlich darum, dass der Abschaum Azeroths, die Menschen, völlig ausgelöscht wird. Hier in Tirisfal stehen wir einer besonders lästigen Menschenbrut gegenüber: dem Scharlachroten Kreuzzug.\n\nBegebt Euch hinaus und führt eine Offensive gegen den Scharlachroten Kreuzzug, {class}. Bringt mir 10 scharlachrote Insignienringe zum Beweis Eurer Loyalität Varimathras und der dunklen Fürstin gegenüber.", sourceObjective = "Bringt Todeswache Burgess in Brill 10 scharlachrote Insignienringe.", progress = "Habt Ihr bereits 10 scharlachrote Insignienringe gesammelt, {class}?", completion = "Varimathras wäre stolz. Ihr dient Euren Anführern gut, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[375] = { id = 375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kälte des Todes", description = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.\n\nJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze und etwas groben Faden bringen würdet, könnte ich mir eine Decke nähen. Helft mir, {name}, auf dass ich der Sache weiter dienen kann.", sourceObjective = "Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden.", progress = "Habt Ihr schon fünf Nachtsaugerpelze und etwas groben Faden, {name}?", completion = "Ich weiß Eure Mühen zu schätzen, {name}. Möge Sylvanas Eure Tapferkeit eines Tages anerkennen...", sourceObjectiveStatus = "unverified-source-field" }
quests[376] = { id = 376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verdammten", description = "Meine Pflichten umfassen, die verwundeten Krieger zu versorgen, Rüstung und Kleidung zu schneidern und Schattenpriester Sarvis in jeder erdenklichen Weise zu unterstützen.\n\nEs sieht so aus, als würdet Ihr ebenfalls in seine Dienste aufgenommen... wahrscheinlich um die Hirnlosen zu jagen, wie ich ihn kenne. Tja, wenn Ihr dabei in einem Stück bleiben wollt - und ich bezweifle nicht, dass Ihr das wollt -, dann kann ich Euch vielleicht helfen. Mir gehen die Tatzen und Flügel aus, und wenn Ihr mir einige davon bringt, besorge ich Euch eine Rüstung. Ihr werdet im Norden eine Menge Wölfe und Fledermäuse finden.", sourceObjective = "Novize Elreth benötigt 6 Aasfressertatzen und 6 Nachtsaugerflügel.", progress = "Bemüht Euch, unverletzt zu bleiben, bis ich Euch irgendeine Rüstung besorgt habe.", completion = "Danke, {name}. Diese Rüstung sollte Euch etwas helfen.\n\nHoffentlich hilft sie Euch mehr als ihrem letzten Träger...", sourceObjectiveStatus = "unverified-source-field" }
quests[377] = { id = 377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrechen und Strafe", description = "Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Stormwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Ebonlockes Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.\n\nWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Fel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Stormwind seine Gefangensetzung.\n\nErmordet Ward im Verlies von Stormwind - bringt mir seine Hand - und ich werde Euch belohnen.", sourceObjective = "Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", progress = "So lange einem Leichenschänder wie Dextren Ward erlaubt wird, weiterzuleben, ist das Verrat an der Gerechtigkeit. Kehrt zu mir zurück, sobald Lord Ebonlockes Todesurteil an diesem Entweiher Ward vollstreckt wurde. Wir werden für die Familien der Toten den Schlussstrich ziehen, den sie verdienen und, noch wichtiger, dem Oberhaus in Stormwind eine klare Botschaft senden.", completion = "Dextren Ward hat also endlich für seine Verbrechen an der Menschheit bezahlt? Ich wünsche diesem Abschaum eine gute Reise. Und meinen Beifall an Euch, mein Freund! Ihr habt nicht nur den Familien der Toten den Seelenfrieden gebracht, den sie verdienen, sondern auch eine klare Botschaft an diese korrupten Bürokraten im Oberhaus geschickt. Stormwind muss sich der Probleme der Leute aus dem Dämmerwald annehmen, oder wir werden uns von ihrer Tyrannei befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[378] = { id = 378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief empfundener Zorn", description = "Ihr habt Eure Loyalität zu König Magni bewiesen, {class}. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener.\n\nEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Deepfury einer der Verschwörer beim Angriff auf den Thandol-Übergang war. Durch Deepfurys Pläne verlor Longbraid seine Sippe.\n\nDeepfury wird aus politischen Gründen im Verlies von Stormwind festgehalten. Ich will ihn tot sehen, {name}. Für Longbraid! Bringt mir seinen Kopf!", sourceObjective = "Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf.", progress = "Ich werde nicht zulassen, dass närrische Menschen-Bürokratie zwergischen Angelegenheiten in die Quere kommt, {name}. Kam Deepfury ist erwiesenermaßen einer der Verschwörer des Angriffs auf den Thandol-Übergang. König Magnis gute Gefolgsleute ließen dank Deepfurys Verrat ihr Leben. Den Menschen mag es genug sein, Deepfury im Verlies verrotten zu lassen, aber ich werde nicht mehr ruhig schlafen, bis Deepfury erschlagen ist.", completion = "Kam Deepfury hat also endlich herausgefunden, wie es ist, den Tod selbst zu erfahren? Gut. Geschieht dem feigen Dunkeleisenabschaum recht. Ihr habt Eure Sache gut gemacht, {class}. Die Gefallenen des Angriffs auf den Thandol-Übergang waren nur Opfer in einer Welt voller Krieg und Unfrieden. Ihre Familien werden Frieden in dem Wissen finden, dass Deepfury die Strafe erhielt, die er verdiente. Der Tod von Longbraids Bruder wurde gerächt.", sourceObjectiveStatus = "unverified-source-field" }
quests[379] = { id = 379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durstlöscher", description = "Ihr möchtet eine Kraftquelle. Da kann ich Euch helfen. Wisst Ihr, was ich möchte? Ich möchte etwas zu Trinken! Bringt mir fünf Wasserbeutel eines Wüstenläufers und ich werde Euch die 4711-FTZ geben.\n\nUnd jetzt... ratet einmal, wo Ihr solche Wasserbeutel finden könnt! Warum geht Ihr nicht zu einem der Wüstenläufernomaden östlich von hier und bittet ihn um einen? Lasst mich wissen, ob das klappt.", sourceObjective = "Bringt Chefingenieur Bilgewhizzle in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", progress = "Na, haben die Nomanden Euch die Wasserbeutel \"freiwillig\" gegeben?", completion = "Hervorragend, die Kraftquelle gehört Euch. Vorsicht, sie wurde nicht für die Verwendung mit wissenschaftlichen Geräten wie diesen entwickelt. Ihr habt also nur begrenzt Zeit, bevor die von Euch gesammelten Daten auf Nimmerwiedersehen verschwinden!\n\nWenn Ihr alles gesammelt habt, was für das, was auch immer es sei, nötig ist, dann bringt sie zu mir und ich werde sie richtig ausschalten. Ihr habt höchstens zwei Stunden Zeit, um alles zu erledigen, was Ihr vorhabt.\n\nFalls Ihr es in dieser Zeit nicht schafft, kann ich Euch aber eine weitere Kraftquelle für einen neuen Versuch verkaufen. Ihr habt richtig gehört - \"verkaufen\"!", sourceObjectiveStatus = "unverified-source-field" }
quests[380] = { id = 380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtweber", description = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.\n\nEs gibt eine Goldmine im Nordwesten, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.\n\nBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, {name}.", sourceObjective = "Exekutor Arren will, dass Ihr 10 junge Nachtweber und 8 Nachtweber tötet.", progress = "Hütet Euch vor dem Gift dieser Spinnen, {name}. Wenn Ihr ein scharfes Brennen verspürt, solltet Ihr vielleicht jemanden danach sehen lassen.", completion = "Hmm, nun ja, es ist ein Anfang. Es wird ein paar Wochen oder Monate dauern, das Ungeziefer gänzlich auszumerzen. Danach müssen wir mit ein paar Fackeln da runtergehen und die Netze niederbrennen.\n\nIhr habt Eure Pflicht gut erfüllt, {name}, und ich bin mir sicher, ich finde noch etwas anderes für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[381] = { id = 381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Kreuzzug", description = "Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen. Nun können wir uns anderen Belangen zuwenden.\n\nMeine Späher haben berichtet, dass eine Abteilung des Scharlachroten Kreuzzugs südöstlich von hier ein Lager errichtet. Der Scharlachrote Kreuzzug ist eine verabscheuungswürdige Organisation, die uns jagt, und sie wird nicht ruhen, ehe nicht alle Untoten - ganz gleich, ob Teil der Geißel des Lichkönigs oder nicht - vernichtet sind. Wir müssen ihnen zuvorkommen!\n\nSeid vorsichtig, denn der unheilige Eifer dieser Leute macht sie zu gefährlichen Gegnern.", sourceObjective = "Bringt Exekutor Arren insgesamt 12 scharlachrote Armbinden von scharlachroten Konvertiten und scharlachroten Initianden.", progress = "Diese Narren... Sie schaufeln sich fröhlich ihre eigenen Gräber.", completion = "Wenn sie nur auf die Stimme der Vernunft hören würden, hm, {name}? Vielleicht könnten wir sie dazu bringen, sich mit uns zu einem vernünftigen Gespräch zusammenzusetzen... ha!\n\nVom Licht geblendete Narren.", sourceObjectiveStatus = "unverified-source-field" }
quests[382] = { id = 382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rote Bote", description = "Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Deathknell entsendet wurde. Nach diesen Berichten führt dieser Bote wichtige Informationen mit sich. Ich kann nicht mit Einzelheiten dienen, aber was auch immer es ist, wir müssen es haben!\n\nIhr seid die qualifizierteste Person, die ich darauf ansetzen kann, {name}. Findet diesen Boten und bringt mir alle Informationen, die er bei sich trägt.", sourceObjective = "Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück.", progress = "Wie läuft es mit Eurem Auftrag, {name}?", completion = "Hmmm... Mal sehen, was Ihr da habt... \n\n<Er fängt an, die von Euch beschafften Dokumente durchzublättern.>\n\nNachrichten von ihren Aktionen gegen uns... Wertlos. Spähberichte... Neue Befehle wie \"Baut das Lager nahe der verfallenen Stadt weiter auf...\". Nichts, was wir nicht bereits wüssten... Ah... was haben wir denn hier? Eine Karte, auf der die derzeitigen Posten einiger ihrer Kommandanten und Agenten verzeichnet sind. Damit lässt sich etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[383] = { id = 383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidende Informationen", description = "Das muss zu meinem Vorgesetzten, Exekutor Zygand, nach Brill gebracht werden. Mit diesen Informationen können wir dem Scharlachroten Kreuzzug einen entscheidenden Schlag versetzen. Eure Dienste waren hier in Deathknell nützlich, aber ich benötige jemanden, der dies zu Zygand bringt, und ich denke, er wird angemessenere Arbeiten für Euch finden. \n\nNehmt die Straße nach Norden, hinaus aus Deathknell. Kurz nachdem Ihr nach Tirisfal hineinkommt, trefft Ihr auf eine Kreuzung. Nehmt die Abzweigung nach Osten und behaltet diese Richtung dann bei. Ihr werdet unterwegs am Coldhearth-Anwesen vorbeikommen.", sourceObjective = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Exekutor Zygand nach Brill.", progress = "Ja, was wollt Ihr?", completion = "Ja, das ist sehr gut. Diese Informationen zu beschaffen, war gute Arbeit, {name}. Hmm... Die Namen der Offiziere in Tirisfal... \n\nStellt Euch nur vor, welchen Schlag wir der Moral dieser verfluchten Fanatiker verpassen könnten, wenn wir es schaffen, all ihre Anführer auf einen Schlag zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[384] = { id = 384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eberrippchen in Biersauce", description = "Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. \n\nVielleicht könnt Ihr mir helfen? Wenn Ihr mir sechs Klippeneberrippchen bringt und ein Rhapsody-Malzbier von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce, und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!", sourceObjective = "Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier.", progress = "Ich werde sechs Klippeneberrippchen und einen Krug Rhapsody-Malzbier benötigen, {name}.", completion = "Das Malzbier ist gebraut, die Wildschweine sind abgestochen\nDoch bevor das letzte Wort gesprochen\nWerden wir um dieses leckere Essen\nDer Eberrippchen in Biersauce\nUns erst im Kampfe messen!", sourceObjectiveStatus = "unverified-source-field" }
quests[385] = { id = 385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenjagd", description = "So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Kroks zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.\n\nWir handeln ein wenig damit, aber nicht wirklich viel, denn die Krokilisken sind wild und haben sich auf den Inseln im Loch verschanzt. Aber ich will Euch nicht davon abbringen, denn es ist ein unvergessliches Erlebnis, mit den Kiefern der Bestien zu ringen.\n\nAch ja, das eine Mal damals...", sourceObjective = "Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge.", progress = "Hab ich Euch eigentlich erzählt, wie ich damals beinahe meine Hand an einen der Kroks verloren hätte? Ein übles Viech war das, mit Zähnen wie Messer. Aber ich hatte Glück... Hab dem Monster mit meinem Messer das Maul gestopft. Ich habe das Messer sogar noch irgendwo herumliegen...", completion = "Na, wenn das nicht ein paar Prachtexemplare sind, die Ihr da gesammelt habt, {name}. Für hochwertiges Material gibt es selbstverständlich auch eine ordentliche Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[386] = { id = 386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrechen lohnt sich nicht", description = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Stormwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.\n\nMacht Targorr dem Schrecklichen ein Ende, {name}. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.", sourceObjective = "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", progress = "Wart Ihr bereits in Stormwind, im Verlies? Ich fürchte, dass das falsche Spiel, das Targorr den Schrecklichen so lange am Leben erhalten hat, ihm irgendwann seine Freiheit wiederbringen wird. Er wurde zum Tode verurteilt, {name}, nicht dazu, als Schachfigur in den politischen Plänen irgendeines Adeligen missbraucht zu werden.", completion = "Targorr den Schrecklichen hat endlich sein Schicksal ereilt. Es freut mich jedenfalls, zu hören, dass diese Bestie jetzt weiß, wie es ist, selbst im ewigen Griff des Todes zu stecken. Ihr habt Eure Sache gut gemacht, {name}. Manchmal kann wahre Gerechtigkeit nur außerhalb des Gerichtssaales und der Kurzsichtigkeit der Politik gefunden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[387] = { id = 387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niederschlagung des Aufstandes", description = "Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Stormwinds niederzuringen.\n\nDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.", sourceObjective = "Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet.", progress = "Das Verlies ist immer noch besetzt! Diesen Defiasratten muss endlich klargemacht werden, dass ihre Taten nicht toleriert werden. Und jetzt geht wieder da runter und zeigt Stärke!", completion = "Eure Bemühungen im Verlies waren tapfer, {name}. Es ist offensichtlich, dass dieses Problem etwas über unserer beider Fähigkeiten liegt. Aber ihr habt Eure Sache gut gemacht, und dafür bin ich Euch dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[388] = { id = 388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Farbe von Blut", description = "Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.\n\nIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.", sourceObjective = "Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", progress = "Wie ich sehe, seid Ihr wieder zurück, {class}. Habt Ihr bereits 10 rote Wollkopftücher der Defias von diesem Abschaum im Verlies gesammelt?", completion = "Diese Kopfwickel - diese schmutzigen Wahrzeichen der Korruption - sind es also, wofür mein Mac sterben musste? Was für eine Verschwendung. Welch tragisches Opfer. \n\nDoch leider kann ich nicht in die Vergangenheit zurückkehren. Wisset jedoch, {name}, dass Ihr meiner Familie mit Euren Taten Gerechtigkeit verschafft habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[389] = { id = 389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bazil Thredd", description = "Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Stormwinds nach dem Krieg.\n\nAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.\n\nSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten.", sourceObjective = "Sprecht mit Aufseher Thelwater im Verlies.", completion = "Was, beim Licht, wollt Ihr? Könnt Ihr nicht sehen, dass wir hier in einer Krisensituation sind?\n\nBazil Thredd?! Warum solltet Ihr mit diesem Bastard sprechen wollen? Woher soll ich wissen, ob Ihr nicht einer seiner Spießgesellen seid, der herkam, um ihm bei seinem verdammten Aufstand zu helfen? Wenn die verfluchten Zellen nicht alle offen wären, würde ich Euch für eine Weile in eine davon werfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[391] = { id = 391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand im Verlies", description = "Lasst uns eine Sache klarstellen, {name}: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.\n\nAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.", sourceObjective = "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies.", progress = "Entweder bringt Ihr mir Thredds Kopf oder ich nehme mir den Euren, kapiert, {name}?", completion = "Jetzt, wo Thredd sie nicht mehr anführen kann, ist der Aufstand hoffentlich eher unter Kontrolle zu bringen... Wir werden sehen.\n\nIch muss gestehen, dass ich nach einer halben Stunde kaum mehr erwartete, dass Ihr wieder herauskommen würdet, aber ich habe Euch wohl falsch eingeschätzt.\n\nIch nehme daher mal an, dass Ihr nicht viele nützliche Informationen aus ihm herausbekommen habt. Aber ich weiß bereits das eine oder andere über Thredds Aktivitäten, das für Euch von Interesse sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[392] = { id = 392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der seltsame Besucher", description = "In den ersten Jahren von Thredds Gefangenschaft bekam er niemals Besuch. Ich ging davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ.\n\nAber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch ... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ. Ich hatte da so meinen Verdacht, aber alle seine Papiere waren in Ordnung.\n\nLaut seinen Dokumenten war sein Name Maelik; hier habt Ihr seine Beschreibung. Ich glaube nicht, dass er noch einmal kommen wird, um Thredd zu besuchen.", sourceObjective = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Baros Alexston.", progress = "Ja, {name}? Was habt Ihr gefunden?", completion = "Hmm. Maelik? Nein, der Name sagt mir nichts und auch nicht diese Beschreibung. Aber es könnte ein jeder sein! Ein früherer Steinmetz, einer von der Bruderschaft der Defias... Wenn er allerdings tatsächlich so viele Verbindungen hat, wie Thelwater andeutet, dann erkennt ihn vielleicht jemand anderes. Lasst mich nachdenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[393] = { id = 393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten der Vergangenheit", description = "Ich habe wirklich keine Ahnung, {name}. Aber es gibt da jemand anderen, der Euch vielleicht helfen kann, und wie es der Zufall so will, schuldet dieser Jemand mir einen Gefallen, weil... egal, das brauchen wir jetzt nicht zu vertiefen. Ihr könnt Meister Mathias Shaw vom SI:7 in der Kaserne in der Altstadt finden. Shaw hat seine Finger in den meisten zwielichtigen oder heimlichen Geschäften der Stadt.\n\nWenn also jemand etwas weiß, dann er.", sourceObjective = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Meister Mathias Shaw.", progress = "Seid gegrüßt. Wie kann ich Euch zu Diensten sein, {class}?", completion = "Was? Was ist das? Ja, ich glaube, ich weiß, wer dieser Mann ist, aber sein Name ist nicht Maelik. Auftragsmörder tragen viele Namen und viele Masken und lassen sie hinter sich, sobald sie ihren Nutzen verloren haben. Ein anderer Name, den dieser Mann benutzt, ist Marzon, obwohl auch das sicherlich nicht sein wirklicher Name ist.\n\nNichtsdestotrotz ist er ein Auftragsmörder, und ich weiß eine ganze Menge über ihn.\n\nMarzon arbeitet derzeit für Lord Gregor Lescovar, einen Lord mit zweifelhaftem Ruf, selbst gemessen am korrupten Adel von Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[394] = { id = 394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kopf des Ganzen", description = "Sucht Shaw in der Altstadt. Teilt ihm mit, dass Ihr Euch um die Bedrohung durch Lescovar gekümmert habt, und berichtet ihm von Eurer Beteiligung an den Plänen des Lords gegen die Stadt. Ich bin sicher, er wird stolz sein, einen weiteren Helden unter den Bürgern Stormwinds zu haben.\n\nEr wird Euch ganz bestimmt zu einem Treffen mit dem Prinzen oder einem anderen Adligen schicken. Lasst Euch das nicht zu Kopfe steigen, {name}. Die Adligen können noch so sehr glauben, dass sie die Stadt beherrschen, aber einige Dinge bleiben für die im Dunklen.", sourceObjective = "Sprecht mit Mathias Shaw in Stormwind.", completion = "Er ist also tot? Ihr wart schnell mit der Vollstreckung des Urteils, {name}. Ich bete zum Licht, dass ich niemals Euer Ziel sein möge!\n\n\n\nDas war nicht als Kritik zu verstehen, {name}. Wie könnte es auch, wo ich doch der Meister aller Auftragsmörder bin? In Wahrheit habt Ihr den Einwohnern von Stormwind einen großen Dienst erwiesen und dafür danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[395] = { id = 395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Bruderschaft", description = "Ach, das hätte ich fast vergessen. Alexston kam vorbei, als Ihr unterwegs wart, und wünschte mit Euch zu sprechen. Zweifellos möchte er den Adligen über die Ränkespiele der Defiasbruderschaft berichten.\n\nEin kleiner Rat, {name}: Sollte Euch jemand fragen, würde ich zwar alle Details offen legen, aber dabei nicht erwähnen, dass es Eure Hand war, die Lescovar erschlug. Vertraut mir. Ich... kenne mich aus... mit solchen Dingen.\n\nUnd was Trias angeht, nun, sprecht mit niemandem über ihn... niemals... wenn Ihr es vermeiden könnt.", sourceObjective = "Sprecht mit Baros Alexston in Stormwind.", completion = "Es ist schön, Euch zu sehen, {name}. Wie ich hörte, wurde Lord Gregor Lescovar vor kurzem tot aufgefunden.\n\nEs sieht also so aus, als wäret Ihr mit Eurer Mission erfolgreich gewesen. Ihr könnt Euch meines Dankes dafür gewiss sein, dass Ihr mich und viele andere vor van Cleefs Rache bewahrt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[396] = { id = 396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz beim König", description = "Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Stormwind loben.\n\nEure Audienz findet in Kürze statt, also solltet Ihr Euch besser beeilen, denn es ist schon ein Stück Weges bis zur Burg Stormwind.", sourceObjective = "Liefert Baros AlexstonsBericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Stormwind ab.", progress = "{name}, richtig? Baros Alexston informierte mich über Euer Kommen. Ich muss sagen, ich bin sehr an Euren Ausführungen interessiert.", completion = "Ihr verdient Lob für die Dienste, die Ihr Stormwind erwiesen habt, {name}. Wenn van Cleef in seinen Machenschaften erfolgreich gewesen wäre, hätte er dem Königreich zweifellos bedeutenden Schaden zugefügt - etwas, das wir natürlich vermeiden müssen.\n\nNehmt dies, {class}, als Zeichen der Dankbarkeit des Königs. Ich bin nur betrübt, dass er es Euch nicht selbst überreichen kann, aber er ist in diplomatischer Mission unterwegs und wird für eine Weile nicht zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[397] = { id = 397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr habt uns gut gedient", description = "Wie ich höre, hat Lord Wishock sein Getränk genossen. \n\nIhr habt uns gut gedient, {name}. Die Hexenmeister von Stormwind werden nun, dank Euch, ohne Störung ihrem Tagewerk nachgehen können. Ich habe ein besonderes Geschenk vorbereitet, um Euch für Eure Mühen zu entlohnen. Sprecht mit meinem Diener, Zggi, um Eure Belohnung zu erhalten.", sourceObjective = "Sprecht mit Zggi, dem Diener von Zardeth von den Blackclaw, um Eure Belohnung zu erhalten.", completion = "Meister sagt, gib {name} Geschenk. Zggi will schönes Geschenk behalten, aber Zggi zu klug, Meister zu verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[398] = { id = 398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Madenauge", description = "Gesucht: Madenauge!\n\nDie selbst für einen Gnoll außerordentlich niederträchtige Kreatur wurde für ihre Verbrechen an den Verlassenen zum Tode verurteilt. Dieser verabscheuungswürdige Verbrecher hat Leichen für die Armee des Lichkönigs gestohlen. Madenauge wurde zuletzt gesehen, als er die Gegend nahe Garrens Schlupfwinkel nördlich von Brill plünderte.\n\nDie Stadt Brill bietet hiermit eine Belohnung für die fähige Seele, die die Exekution durchführt. Zeigt Exekutor Zygand die Tatze des Verbrechers, wenn die Tat getan ist.\n\nGnade ist etwas für die Schwachen.", sourceObjective = "Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten.", progress = "Ja?", completion = "Madenauges abscheuliche Taten wurden endlich gerächt. Vielleicht sind Eure mutigen Taten eine klare Botschaft an die, die unserem Volk Leid zufügen wollen. Ich danke Euch im Namen der Stadt Brill, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[399] = { id = 399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bescheidener Anfang", description = "Es kommt mir so vor, als wäre es ewig her, dass ich als Junge in Westfall auf dem Hof gearbeitet habe. Man sagt ja, man kann niemals in der Zeit zurückgehen, und es stimmt wohl. In meinem Fall trifft das sogar gleich doppelt zu, denn das Heim meiner Familie wurde niedergebrannt und von Dieben besetzt.\n\nIch habe mit meinem Vater über den Verbleib einiger meiner Habseligkeiten gesprochen, darunter mein erster Kompass. Er konnte sie nicht retten. Allerdings meint er auch, dass sie auf dem Hof versteckt sein müssten.\n\nIhr findet den Alexstons Bauernhof westlich der Späherkuppe. Könntet Ihr vielleicht dorthin gehen und mir meinen Kompass wiederbringen?", sourceObjective = "Begebt Euch zu Baros Alexstons Haus in Westfall und sucht nach seinem Kompass. Übergebt ihm diesen dann am Kathedralenplatz von Stormwind.", progress = "{name}! Hattet Ihr Glück?", completion = "Oh, ich danke Euch, {name}! Er hat zwar keinen praktischen Nutzen für mich, aber sein sentimentaler Wert... Ich muss wohl nicht betonen, wie dankbar ich bin, dass Ihr mir dies zurückgebracht habt... unter Einsatz Eures Lebens, ganz zu schweigen von der Zeit, die der lange Weg bis hinunter nach Westfall in Anspruch nahm. Habt Dank, und nehmt dies als ein Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[400] = { id = 400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge für Steelgrill", description = "Beldin Steelgrill ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!\n\nWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.\n\nSein Geschäft, Steelgrills Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.", sourceObjective = "Liefert Beldin Steelgrill seine Werkzeuge.", progress = "Hm? Ihr seht etwas zu jung aus für einen Piloten der Belagerungsmaschinen. Aber egal... Braucht Ihr eine Reparatur?\n\nDann zieht eine Nummer und macht es Euch bequem. Ich arbeite gerade an ein paar Maschinen und werde wenigstens einige Tage lang keine Zeit für weitere Aufträge haben.\n\nOder seid Ihr wegen etwas anderem hier... ?", completion = "Ihr habt meine Werkzeuge? Gut gemacht, Junge, gut gemacht! Ich habe gerade vor einer Stunde meine letzte Zahnratsche zerbrochen, und ich brauche eine, um die Reparatur an Pilot Stonegears Belagerungsmaschine abzuschließen. Gut, dass Ihr diese Werkzeuge hierher geschafft habt, {name}.\n\nHier, nehmt diese Münzen, für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[401] = { id = 401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wartet, bis Sirra fertig ist", description = "Ich bin fast mit der Übersetzung dieser Notiz fertig. Wenn Ihr in ein paar Minuten wiederkommt, dürfte ich fertig sein.", sourceObjective = "Wartet einen Moment und sprecht dann erneut mit Sirra Von'Indi.", completion = "So, hier haben wir's. Übersetzt heißt es... \n\n<Die Luft wird schwerer, als würde sich ein dicker, schwarzer Mantel über das Land legen... >", sourceObjectiveStatus = "unverified-source-field" }
quests[402] = { id = 402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirra ist beschäftigt", description = "Tut mir leid, aber bei dem Zustand, in dem die Stadt sich derzeit befindet, gibt es leider andere Dinge, die meine Aufmerksamkeit erfordern. Vielleicht kann ich diese Übersetzung später beenden, falls wir überleben.", sourceObjective = "Schaut später noch einmal nach, ob Sirra immer noch beschäftigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[403] = { id = 403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das bewachte Fass mit Donnerbier", sourceObjective = "Dieses Fass Bier wird von Jarven Donnerbräu bewacht. Solange er im Keller ist, kann man sich nicht an den Fässern zu schaffen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[404] = { id = 404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eitrige Aufgabe", description = "Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen die Gegend westlich von Brill heim, nahe der alten Brücke.\n\nGeht dorthin und schlagt die Faulenden Toten und Verheerten Kadaver zurück, die Ihr dort vorfindet. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.", sourceObjective = "Bringt Todeswache Dillinger in Brill 7 eitrige Klauen.", progress = "Habt Ihr die Aufgabe erledigt, die ich Euch auftrug? Habt Ihr die eitrigen Klauen?", completion = "Gut gemacht. Schade, dass ich nicht dabei war, um Euch zuzusehen, wie Ihr diese Untoten zu Brei geschlagen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[405] = { id = 405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der abtrünnige Lich", description = "Bethor Iceshard, ein hochrangiger und mächtiger Magier aus Undercity im Süden, befiehlt mir, ihm einen Agenten zu schicken, der seinen Wert gegen die Geißel bereits bewiesen hat. Ihr, {name}, werdet dieser Agent sein.\n\nZeigt Bethor diese Befehle. Er wird Euch daraufhin über Eure Mission aufklären. Ich kenne keine Details, aber es hat etwas damit zu tun, einen eigenwilligen Lich zu rekrutieren. Und es wird gefährlich sein.\n\nAlso macht Euch bereit, {class}. Ihr dürft nicht scheitern.\n\nIhr dürftet Bethor im Magieviertel von Undercity finden.", sourceObjective = "Zeigt Bethor Iceshard in Undercity Sevrens Befehle.", progress = "Seid gegrüßt. Entweder wisst Ihr nicht, wer ich bin, oder Ihr habt dringliche Geschäfte mit mir zu erledigen.\n\nDenn würde beides nicht zutreffen, wärt Ihr nicht töricht genug, mich zu stören...", completion = "Ah, Ihr seid der Agent, den Magistrat Sevren schickt. Also sind Eure Geschäfte mit mir tatsächlich wichtig.\n\nIch gehe davon aus, dass Sevren jemanden ausgewählt hat, der meiner Aufgabe gewachsen ist... aber wir werden sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[407] = { id = 407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felder des Kummers", description = "Harmlose Kürbisse, oder? Zumindest sehen sie so aus. Wenn wir Arthas' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen wir alle Möglichkeiten unseres untoten Daseins nutzen.\n\nMit etwas Einfallsreichtum wird sogar aus einem einfachen Kürbis ein Agent für unsere dunkle Fürstin. Dieser Kürbis wird sich, wenn nach meiner jüngsten Formel behandelt, als eine besondere Leckerei erweisen.\n\nEs wurde schon wieder ein Scharlachroter Zelot gefangen genommen, der derzeit im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird. Bringt dem Trottel diesen Kürbis.", sourceObjective = "Bringt den getränkten Kürbis zum gefangenen Scharlachroten Zeloten, der im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird.", progress = "Bleibt mir vom Leibe, bösartige und unheilige Kreatur! Möge das Licht mich beschützen! Der Scharlachrote Kreuzzug wird Azeroth von Eurer... \n\n... oh, Moment mal. Ist das etwas zu essen für mich? Ich bin so was von hungrig...", completion = "Beim Licht! Endlich etwas zu essen! Süßer, leckerer Kürbis...", sourceObjectiveStatus = "unverified-source-field" }
quests[408] = { id = 408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Familiengruft", description = "Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Captain Dargol, sein Hauptquartier hat. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen uns einzusetzen.\n\nDies darf nicht geschehen, und Ihr müsst es verhindern. Reist zur Gruft der Familie Agamand und besiegt die erweckten Vorfahren der Agamands.\n\nUnd bringt mir den Schädel von Captain Dargol.", sourceObjective = "Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.\n\nTötet Captain Dargol und bringt seinen Schädel zu Magistrat Sevren nach Brill.", progress = "Zeit ist ein Luxus, den wir uns nicht leisten können, {name}. Mit jeder Stunde, die verstreicht, festigt sich der Griff der Geißel um Tirisfal.", completion = "Eure Taten verpassten der Geißel einen merklichen Schlag. Und Euer Sieg wird nicht unbemerkt bleiben - weder von den Verlassenen, noch von unseren Feinden.\n\nKämpft weiter, wie wir alle, {name}, und eines Tages werden wir den Lichkönig daselbst aus Azeroth vertreiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[409] = { id = 409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treuebeweis", description = "Ihr behauptet, Ihr wärt nicht dem Willen des Lichkönigs unterworfen, und die Verzauberung, die Bethor auf mein Buch legte, untermauert dies. Aber bevor ich Euch glaube, muss ich den Beweis haben, dass Ihr der Geißel feindlich gegenübersteht.\n\nEs gibt einen alten, blutigen Altar kurz vor der Südküste dieser Insel. Er wird von einer mächtigen Dienerin der Geißel, Lillith Nefara, verwendet.\n\nNehmt eine Kerze des Heranlockens aus dieser Kiste hier. Entzündet sie auf dem Altar, und Lillith wird erwachen. Vernichtet Lillith, und ich werde Euch glauben, dass Ihr ein Gegner des Lichkönigs seid.", sourceObjective = "Beschafft Euch eine Kerze des Heranlockens.\n\nBeschwört Lillith Nefara und tötet sie.\n\nKehrt zu Gunther auf seiner Insel zurück.", completion = "Ihr habt Lillith Nefara getötet und damit bewiesen, dass Ihr ein Feind der Geißel seid. Unglaublich.\n\nIch glaubte, der einzige Untote mit freiem Willen zu sein, aber Ihr habt mir gezeigt, dass es andere gibt, die der Kontrolle des Lichkönigs getrotzt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[410] = { id = 410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlummernde Schatten", progress = "Dies ist ein alter, abgewetzter, blutiger Tisch.", completion = "Ihr platziert die Kerze des Heranlockens auf dem Tisch und entzündet sie..." }
quests[411] = { id = 411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des abtrünnigen Lichs", description = "Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.", sourceObjective = "Bringt den Netheredelstein zu Bethor Iceshard nach Undercity.", progress = "Habt Ihr Gunthers Buch zurückgebracht? Hat er geantwortet?", completion = "Ihr habt ihn dazu gebracht, sich uns anzuschließen! Ihr habt den Verlassenen einen großen Dienst erwiesen, {name}. Die dunkle Fürstin wird das erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[412] = { id = 412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Rekombobulationsgerät", description = "Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten wir nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten wir dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige Lepragnome verwandelt.\n\nOzzie und ich haben vor, den schrecklichen Lepraeffekt mit unserer jüngsten Erfindung wieder rückgängig zu machen: der Rekombobulator. Die Maschine ist beinahe fertig, aber wir brauchen dringend einige Restabilisationszahnräder und gyromechanische Getriebeteile. Besorgt uns ein paar davon bei den Lepragnomen drüben in Gnomeregan.", sourceObjective = "Bringt Razzle Sprysprocket in Kharanos 8 Restabilisationszahnräder und 8 gyromechanische Getriebeteile.", progress = "Der Rekombobulator wird laufen wie geschmiert, sobald wir ausreichend Restabilisationszahnräder und gyromechanische Getriebeteile haben.", completion = "Diese gyromechanischen Getriebeteile und Restabilisationszahnräder stimmen genau mit Ozzies Bauplan für das Rekombobulationsgerät überein. Sobald ich jetzt etwas Hydroschmiermittel auf die inneren Verbrennungskolben gebe, die Kurbelratsche justiere und die Zähflüssigkeit des Electrogumgels erhöhe, wird das gnomische Volk wieder wie neu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[413] = { id = 413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerstarkbier", description = "Ich möchte, dass mein Bruder Wellart mein neues Schimmerstarkbier ausprobiert. Er ist Gebirgsjäger und im südlichen Wachturm stationiert, einem von zwei Türmen an der Grenze zum Loch Modan.\n\nEr mag vielleicht kein Bierbrauer sein wie der Rest von uns Gerstenbräus, aber er trinkt gern mal einen, und ich bin mir sicher, er wird dies hier mögen.\n\nKönnt Ihr ihm dieses Fass Schimmerstarkbier für mich bringen?", sourceObjective = "Bringt das Fass mit Schimmerstarkbier zu Gebirgsjäger Gerstenbräu.", progress = "Hallo, {class}! Na, welche Geschäfte treiben Euch den weiten Weg bis nach hier draußen?\n\nHoffentlich etwas Aufregendes. Ich hatte seit Tagen keinen ordentlichen Kampf mehr, und dieses Fass Bier ist so gut wie leer...", completion = "<Gebirgsjäger Gerstenbräu probiert das Schimmerstarkbier... >\n\nOh, wow! Dieses Zeug treibt einem wirklich Glanz in die Augen. Ich fühle mich, als könnte ich im Dunkeln sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[414] = { id = 414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starkbier für Kadrell", description = "Ich habe inzwischen mehr von diesem Schimmerstarkbier getrunken, das mein Bruder gebraut hat - das ist großartiges Zeug! Ein Gebirgsjägerkumpel von mir muss das mal probieren. Er heißt Kadrell und patrouilliert normalerweise entlang der Straße durch Thelsamar beim Loch Modan.\n\nUm nach Thelsamar zu gelangen, müsst Ihr südostwärts durch den Tunnel gehen und dann nach Nordosten abbiegen, wenn der Pfad auf eine Straße trifft. Dieser Straße folgt Ihr direkt bis nach Thelsamar.\n\nGebt Gebirgsjäger Kadrell dieses Fässlein Schimmerstarkbier und schaut mal, was er davon hält!", sourceObjective = "Bringt das Fässlein mit Schimmerstarkbier zu Gebirgsjäger Kadrell.", progress = "Seid gegrüßt, {class}, und willkommen in Thelsamar!", completion = "Und jetzt lasst mich mal versuchen... \n\nBeim Barte Magnis! Dieses Zeug haut einem die Birne weg! Und macht dabei die Gliedmaßen so leicht.\n\nIch fühle mich, als könnte ich fliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[415] = { id = 415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejolds neues Gebräu", description = "Rejold Gerstenbräu aus Brewnall hat nach Euch gefragt.\n\nEr möchte mit Euch über ein neues Getränk reden, das er gebraut hat... er sagte etwas davon, dass Ihr ihm vielleicht dabei helfen könntet. Vielleicht wollt Ihr also wieder nach Brewnall zurückkehren, um herauszufinden, worum es geht.\n\nEs könnte etwas Freibier für Euch drin sein...", sourceObjective = "Sprecht mit Rejold Gerstenbräu.", completion = "{name}! Erinnert Ihr Euch an das Schimmerkraut, das Ihr mir gebracht habt? Nun, ich habe es in einigen der Rezepte, an denen ich zuletzt gearbeitet habe, ausprobiert, und eines davon gelang einfach großartig!\n\nHier, versucht es und sagt mir, was Ihr davon haltet...", sourceObjectiveStatus = "unverified-source-field" }
quests[416] = { id = 416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattenfang", description = "Wir haben im Westen ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!\n\nWir wollen, dass sie ausgelöscht werden. Jagt sie, bringt mir ihre Ohren und kassiert das Kopfgeld.\n\nIhr findet die Kobolde der Tunnelratten und ihre Baue westlich von Thelsamar überall über den Berghang verteilt.", sourceObjective = "Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren.", progress = "Seid gegrüßt, {name}. Wie steht es mit der Rattenjagd?", completion = "Igitt! Als ich diese Ohren verlangte, hatte ich keine Ahnung, dass sie so schrecklich stinken würden.\n\nHier ist Eure Belohnung, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[417] = { id = 417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilotenrache", description = "Hildelve schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hildelves Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hildelve in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", sourceObjective = "Tötet Marterklaue.\n\nBringt Pilot Hammerfoot die räudige Klaue des Bären und Hildelves Tagebuch.", progress = "Hallo, {name}. Wisst Ihr etwas über den Verbleib meines Freundes Hildelve?", completion = "Das sind traurige Neuigkeiten, denn Hildelve war ein guter Freund. Ich wünschte, ich hätte dort mit Euch sein können, als Ihr die Bestie Marterklaue gefunden habt!\n\nDanke, {name}. Eure Tat wird den Piloten der Belagerungsbrigade von Ironforge in Erinnerung bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[418] = { id = 418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thelsamar-Blutwurst", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr ein toller {class} seid.\n\nIch brauche Bärenfleisch, Ebergedärme für die Pelle und Spinnensekret als Würzmittel. Bringt mir das alles und überlasst dann Vidra das Kochen!", sourceObjective = "Bringt Vidra Hearthstove in Thelsamar 3 Stück Bärenfleisch, 3 Portionen Ebergedärme und 3 Portionen Spinnensekret.", progress = "Ich bin so weit, dass ich mit dem Kochen anfangen könnte; habt Ihr die Zutaten?", completion = "Vertraut mir, es ist schwerer als es aussieht, aber... \n\nAch, ich habe bisher noch nie jemanden getroffen, der sich sehr für die Herstellung von Würsten interessiert hat, aber ich werde Euch für alle Fälle dennoch das Rezept geben. Hier, und denkt immer daran, sie zu essen, solange sie frisch sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[419] = { id = 419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Pilot", description = "Mein Freund Mori Hildelve, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe in den Hügeln des Nachts das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, {name}. Sucht ihn.", sourceObjective = "Findet Pilot Hildelve.", completion = "Hier liegt die Leiche eines Zwergs - zerfetzt, gefroren und von Aasfressern blankgefressen. Seine Hand umklammert ein Buch, das die grob hingekritzelten Aufzeichnungen von Mori Hildelve enthält. Um ihn gehüllt, nach wie vor in sehr gutem Zustand, ist eine Brigadiersweste.\n\nAn diesem grausigen Ort muss der Pilot der Belagerungsmaschinen sein Ende gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[420] = { id = 420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senirs Beobachtungen", description = "Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Ihr seid aber offenbar hart genug im Nehmen, also solltet ihr wahrscheinlich sicher sein.\n\nEine Wegbeschreibung? Wenn Ihr mit Senir sprechen wollt, findet Ihr ihn in Kharanos.\n\nArbeitet Euch durch den Tunnel und folgt einfach weiter der Straße, wenn Ihr auf der anderen Seite herauskommt, denn sie führt direkt nach Kharanos.", sourceObjective = "Überbringt Senir Whitebeard in Kharanos Grelins Bericht.", progress = "Wie geht es Euch? Wollt Ihr vielleicht etwas mit mir trinken? Es gibt in der Kälte sonst nichts zu tun.", completion = "Was ist das? Ah, der Bericht meines Bruders. Hmm... \n\nIch habe ihm gesagt, er soll den Namen des Königs nur dezent einsetzen, aber er wollte ja nicht auf mich hören. Es kann nicht schaden, schätze ich, aber es werden sich auf alle Fälle einige im Senat die Haare raufen. Nicht, dass die diese Rauferei nicht mal nötig hätten! Ha!\n\nNichtsdestotrotz heißt das wohl, dass ich meinen Bericht ebenfalls nach Ironforge schicken sollte, aber ich muss zugeben, dass ich etwas im Rückstand bin. Verdammte Kälte.\n\nIch dürfte später etwas Arbeit für Euch haben, wenn Ihr Interesse habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[421] = { id = 421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertbeweis", description = "Lady Sylvanas hat Varimathras damit beauftragt, die Gebiete der Menschen und Zwerge im Süden zu erobern.\n\nAber dieser Idiot Arugal - ein Scharlatan aus Dalaran und heutzutage eine verfluchte Kreatur der Burg Shadowfang - hat auf verantwortungslose Weise mit seiner Magie den strategischen Stützpunkt des Silberwaldes verheert.\n\nIch brauche einen geschickten Kämpfer, der dabei hilft, die Suppe auszulöffeln, die Arugal uns eingebrockt hat. Beweist Euch mir, indem Ihr 5 Moonrage-Weißskalps tötet. Man findet die elenden Bestien oft nur ein kleines Stück abseits der Straße, am Fuße des Hügels dort unten.", sourceObjective = "Dalar Dawnweaver auf dem Grabmal will, dass Ihr 5 Moonrage-Weißskalps tötet.", completion = "Ihr habt mir gut gedient, {class}. Mir ist klar, dass Ihr mir eine wertvolle Hilfe sein werdet, wenn ich beginne, den Silberwald von Arugals Fluch zu befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[422] = { id = 422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Wie Arugal in die Kirin Tor aufgenommen wurde, ist mir schleierhaft. Seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck.\n\nAm wichtigsten ist es erst einmal, herauszufinden, welche Art von Magie Arugal genau verwendet hat, damit ich sie gegen ihn verwenden und den Silberwald für die dunkle Fürstin einnehmen kann.\n\nArugal hielt sich zuerst auf der Weizenfarm etwas nördlich der Brücke auf. Einer der Todespirscher berichtete, dass er einige Zauberbücher gesehen hätte, sie aber nicht beschaffen konnte. Beschafft mir den Zauber namens 'Arznei des Arugal' aus diesen Büchern.", sourceObjective = "Beschafft Dalar Dawnweaver auf dem Grabmal die Arznei des Arugal.", progress = "Bevor ich weiß, womit wir es hier genau zu tun haben, {class}, muss ich den Zauber untersuchen, der als 'Arznei des Arugal' bekannt ist. Bringt ihn mir umgehend, oder ich bin gezwungen, mir einen geeigneteren Diener zu suchen.", completion = "Das ist genau der Zauber, den ich suchte, {class}. Wenn Eure Hingabe an die Sache der dunklen Fürstin weiterhin so ungetrübt bleibt, werdet Ihr eine große Zukunft unter den Verlassenen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[423] = { id = 423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Bei der Untersuchung von Arugals Arbeit haben sich meine schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in Dalaran zu leeren, davon, die Kirin Tor in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Narren!\n\nArugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken. Ich muss diese Gegenstände selbst untersuchen. Zieht los und erschlagt so lange Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr genug ihrer verzauberten Fesseln für meine Nachforschungen gesammelt habt. Man hat diese üblen Kreaturen im Norden und Osten gesehen.", sourceObjective = "Bringt Dalar Dawnweaver am Grabmal 6 Nimmersattfesseln und 3 Dunkelseelenfesseln.", progress = "Ich brauche 6 Nimmersattfesseln und 3 Dunkelseelenfesseln, bevor ich die Situation einschätzen und eine endgültige Lösung für Arugal ersinnen kann. Und jetzt kommt meiner Aufforderung nach und erschlagt Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr habt, was ich brauche.", completion = "Ich hoffe, ich kann aus dieser kleinen Auswahl genug Energie ziehen. Vielleicht hätte ich Euch mehr Fesseln holen lassen sollen.\n\nNichtsdestotrotz habt Ihr großes Geschick darin bewiesen, diese zu sammeln, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[424] = { id = 424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugals Torheit", description = "Ich werde tatsächlich länger brauchen, als ich gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken.\n\nIn der Zwischenzeit müsst Ihr Euch um ein kleines Problem kümmern, das unsere Dunkelpirscher entdeckt haben. Es sieht so aus, als hätte Arugal seiner Magie erlaubt, sich bis zur Tiefenfelsmine in den Hügeln im Südosten auszubreiten.\n\nDiese Mine wäre eine ziemlich nützliche Ressource für Varimathras' Vormarsch.\n\nIch will, dass Ihr Grimson den Blassen, den besudelten Großknecht der Mine, enthauptet. Mit seinem Tod sollte die Mine uns gehören.", sourceObjective = "Tötet Grimson den Blassen und bringt seinen Kopf zu Dalar Dawnweaver auf das Grabmal.", progress = "Ist Grimson der Blasse erschlagen? Varimathras wird nicht gerade glücklich sein, wenn wir seine Wünsche ignorieren.", completion = "Wunderbar. Die Mine wird unseren Truppen hervorragende Rohstoffe liefern, wenn wir uns im Silberwald und nach Azeroth hinein ausbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[425] = { id = 425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivar der Verfaulte", description = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.\n\nWir entkamen Ivar, aber er verletzte Quinn schwer. Dank des Trankes, den Ihr ihm gegeben habt, heilt er, aber Ivar könnte wiederkommen, bevor Quinn sich erholt hat.\n\nTötet Ivar, damit Quinn genug Zeit hat, sich zu regenerieren. Ivar hält sich üblicherweise in dem Schuppen da drüben auf und wartet darauf, dass meine Wachsamkeit nachlässt.", sourceObjective = "Tötet Ivar den Verfaulten und bringt Ivars Kopf zu Rane Yorick auf dem Ivar-Feld.", progress = "Habt Ihr Ivar den Verfaulten getötet? Wenn Ihr es nicht für mich und meinen Bruder tun wollt, dann tut es für die Verlassenen.", completion = "Ah, habt Dank. Ihr habt meine Anerkennung, {name}.\n\nUnd ich werde Euch in dem Bericht an meine Vorgesetzten erwähnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[426] = { id = 426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überrannte Mühle", description = "Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.\n\nEs wurden klare Befehle erteilt. Die Diener der Geißel in den Mühlen müssen vernichtet werden.\n\nGeht zu den Mühlen. Sammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.\n\nUm zu den Mühlen zu gelangen, folgt der Straße westwärts. Nachdem Ihr die Brücke überquert habt, nehmt die erste Abzweigung nach Norden und folgt diesem Weg. Wenn Ihr die Windmühlen seht, beginnt die Schlacht.", sourceObjective = "Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück.", progress = "Unser Krieg gegen die Geißel dauert noch immer an, {name}. Tut das Eurige und werft diese verfluchten, hirnlosen Untoten wieder zurück in die Pestländer!", completion = "Eure Bemühungen im Krieg sind spürbar, {name}. Ich werde Euch nicht für etwas Notwendiges danken, aber die Todeswachen von Tirisfal werden sich Eures Namens erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[427] = { id = 427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Krieg mit dem Scharlachroten Kreuzzug", description = "Die Dokumente, die Exekutor Arren uns zur Verfügung stellte, verschaffen uns genau die Atempause, die wir in unserem Kampf gegen den Scharlachroten Kreuzzug benötigen. Wir kennen jetzt dessen genaue Aufenthaltsorte überall in Tirisfal.\n\nAber leider haben die Todeswachen noch ganz andere Sorgen. Die Armee des Lichkönigs wächst jede Nacht an. Wir benötigen jemanden, der wie Ihr gern \"Initiative\" zeigt, um den Scharlachroten Kreuzzug ins Grab zu bringen.\n\nBeweist mir, dass Ihr der dunklen Fürstin dienen könnt, indem Ihr nach Westen zum Turm hinter Sollidens Bauernhof reist und dort 10 Scharlachrote Krieger erschlagt.", sourceObjective = "Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet.", completion = "Wunderbar, {class}. Euer Geschick in der Kriegskunst ist nicht zu leugnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[428] = { id = 428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorenen Todespirscher", description = "Vor einigen Wochen wurden zwei unserer Todespirscher, Rane und Quinn Yorick, auf eine Aufklärungsmission durch den nördlichen Silberwald geschickt. Wir haben nichts mehr von ihnen gehört.\n\nSie könnten der Geißel zum Opfer gefallen sein, doch wenn dem so ist, will ich es bestätigt wissen. Findet diese Todespirscher.\n\nIhre erste Aufgabe war es, die Bauernhöfe im nördlichen Silberwald auszukundschaften. Ihr solltet dort mit Eurer Suche beginnen.", sourceObjective = "Findet die Todespirscher Quinn und Rane Yorick.", completion = "Ihr habt uns gefunden! Und das keinen Moment zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[429] = { id = 429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Herzen", description = "Mein Bruder Quinn wurde von dem Ghul Ivar dem Verfaulten schwer verletzt, und ich glaube nicht, dass er ohne magische Hilfe wieder vollständig genesen wird. Auch wenn ich kein Apotheker bin, so weiß ich doch, dass unsere Apotheker Heiltränke aus verfärbten Worgherzen herstellen können.\n\nSammelt einige solcher Herzen und bringt sie zu Apotheker Renferrel am Grabmal im Süden. Kommt dann mit dem Trank hierher zurück.\n\nZwischen hier und Maldens Obsthain im Osten werdet Ihr jede Menge Worgs vorfinden.", sourceObjective = "Sammelt 6 verfärbte Worgherzen und bringt sie zu Apotheker Renferrel auf dem Grabmal.", progress = "Meine Zeit ist knapp, {class}, denn die dunkle Fürstin hat mich mit einer wichtigen Aufgabe betraut.", completion = "<Renferrel nimmt die Herzen entgegen.>\n\nEs ist beunruhigend zu hören, dass unsere Todespirscher ihren Auftrag nicht erfüllt haben.\n\nHoffen wir, dass solche Fehlschläge die Ausnahme sind.\n\nIch werde Euch den Trank gleich geben, aber hier habt Ihr erst einmal sein Rezept - falls diese Todespirscher wieder einmal Hilfe benötigen, könnt Ihr sie ihnen vielleicht selbst verabreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[430] = { id = 430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Quinn", description = "Hier habt Ihr den Trank, mit dem Ihr Quinn Yoricks Erholung beschleunigen könnt.\n\nWenn Ihr mich jetzt entschuldigen mögt, ich habe wirklich wichtige Dinge zu erledigen...", sourceObjective = "Bringt Quinn Yorick auf dem Ivar-Feld, nördlich des Grabmals, Quinns Trank.", progress = "Meine Schwester sagte mir, Ihr wäret hier, um uns zu helfen. Stimmt das?", completion = "<Quinn nimmt den Trank und trinkt ihn.>\n\nJa, ich kann spüren, wie er wirkt. Ich werde bald wieder reisen können.\n\nIhr habt mir einen großen Gefallen getan, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[431] = { id = 431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kerze des Heranlockens", sourceObjective = "Ihr schnappt Euch eine der Kerzen und verstaut sie in Eurem Rucksack.", sourceObjectiveStatus = "unverified-source-field" }
quests[432] = { id = 432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diese verfluchten Troggs!", description = "Diese vom Licht verfluchten Troggs verwandeln meinen Arbeitsplatz in eine Ruine. Schaut Euch das an, da geht schon wieder ein Pulverfass hoch.\n\nOh, ich wünschte ich könnte da runtergehen und allen einzeln ihre dürren Hälse umdrehen! Ich will sie alle töten!\n\nDas kann nicht gut für meine Gesundheit sein, all dieser Stress und diese Wut... Was haben sie mir gelassen? Nichts!\n\nIch würde sie persönlich umbringen, aber ich ziele nicht mehr so gut wie früher. Geht in den Steinbruch und tötet einige dieser dreckigen Mistviecher! Ich werde Euch bezahlen! Hauptsache, Ihr verletzt sie, tötet sie!", sourceObjective = "Tötet für Großknecht Stonebrow im Gol'Bolar Steinbruch 6 Schädelhauer der Felsenkiefer.", progress = "Das macht mich dermaßen wütend! Grrr...", completion = "Nun, jetzt geht es mir schon etwas besser... \n\nAber ich werde mich erst wieder richtig freuen können, wenn sie alle tot sind! Restlos alle!", sourceObjectiveStatus = "unverified-source-field" }
quests[433] = { id = 433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Volkes", description = "Als Mitglied des Senats und der Forscherliga habe ich mir vorgenommen, mich um den Teil der Trogg-Plage zu kümmern, die unser Land heimsucht.\n\nSie haben den Gol'Bolar Steinbruch wirklich ziemlich verwüstet, und das ohne erkennbaren Grund. Als wir tiefer in die Erde hineingruben, strömten sie heraus, zerstörten unsere Ausrüstung und verjagten die Minenarbeiter. Wir können nicht viel mehr tun, als das ganze Pack auszulöschen, alles wieder aufzubauen und dann wieder an die Arbeit zu gehen.\n\nWenn Ihr mir mit den Troggs helft, werde ich Euch gern für Eure Zeit, die Ihr dafür opfert, entschädigen.", sourceObjective = "Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer.", progress = "Wenn wir die Troggs vom Gol'Bolar Steinbruch entfernen können, wäre das der Erste von vielen Schritten, die wir unternehmen müssen, um uns von dieser Bedrohung zu befreien.", completion = "Das ist ein Anfang. Hoffentlich können wir ihn nutzen und einige Gebirgsjäger hineinschicken, um das Gebiet zu sichern. Dann können wir damit anfangen, unsere Infrastruktur wieder aufzubauen und unsere Minenarbeiter wieder an die Arbeit schicken.\n\nDanke für Eure Unterstützung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[434] = { id = 434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff!", description = "Nachdem ich dem Spionagebot die Verkleidung angelegt habe, begibt er sich hinein, um mit Lescovar zu sprechen. Die Wachen sollten ihn ohne Probleme durchlassen.\n\nWährend Ihr Material für mich gesammelt habt, habe ich Marzon darüber informiert, dass es für ihn und Lescovar an der Zeit sei, sich wieder zu treffen. Ich habe sogar einige falsche Informationen verlautbaren lassen.\n\nLescovar wird seine Wachen wegschicken und hier draußen im Garten auf Marzon warten. Tretet in Aktion, wenn Ihr etwas über die Defias hört. Ihr müsst sie beide eliminieren. Kapiert?\n\nWenn Ihr das erledigt habt, sprecht Ihr mit Trias.", sourceObjective = "Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Stormwind zu Elling Trias zurückkehrt.", completion = "Es ist also vollbracht? Gut. Ich danke Euch vielmals für Eure Diskretion, {name}. Ihr habt Euch in mehr als einer Hinsicht als würdig erwiesen. Ich werde Euch und Euren Aufstieg innerhalb der Allianz ganz bestimmt im Auge behalten.\n\nAchtet darauf, dass Ihr Eure Finger nicht schmutzig macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[435] = { id = 435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eskorte für Erland", description = "Die Wölfe da draußen wollen nicht abhauen, und jedesmal, wenn ich einen Schritt aus der Tür mache, schauen sie mich böse an. Sie müssen unglaublich hungrig sein, wenn sie mich für essenswert halten.\n\nIch muss mich bei meiner Kampfgefährtin, Todespirscherin Rane Yorick, melden. Und um zu Rane zu kommen, brauche ich Hilfe gegen diese Wölfe.\n\nBitte begleitet mich! Ach ja, da draußen sind eine Menge Wölfe, wir hätten also eine bessere Chance, wenn Ihr Freunde dabei hättet, die ebenfalls helfen können...", sourceObjective = "Begleitet Erland durch die Wölfe hindurch zu Rane Yorick.", completion = "Danke für die Hilfe, {name}. Ich hatte befürchtet, Erland wäre den Gefahren des Silberwaldes erlegen. Aber dank Eurer Hilfe war dem offensichtlich nicht so.", sourceObjectiveStatus = "unverified-source-field" }
quests[436] = { id = 436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironbands Ausgrabungsstätte", description = "Ausgrabungsleiter Ironband leitet die Ausgrabung einiger alter Ruinen östlich des Sees. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den wir ihm geschickt haben.\n\nIronband ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher mache ich mir Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten.\n\nGeht zu Ironbands Ausgrabungsstätte und sprecht mit Magmar Fellhew. Er kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht.\n\nUm zur Ausgrabungsstätte zu gelangen, müsst Ihr um die Südspitze des Sees herum und dann nach Osten gehen.", sourceObjective = "Sprecht mit Forscher Fellhew.", completion = "Jern will wissen, was uns aufhält, hm?\n\nIronband verfasst gerade seinen jüngsten Fortschrittsbericht mit allen Details, aber ich kann Euch Folgendes sagen:\n\nEs sind die Troggs!", sourceObjectiveStatus = "unverified-source-field" }
quests[437] = { id = 437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Todesfeld", description = "Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. Wir haben kleine Angriffe auf sie gestartet, aber jedesmal werden sie von der Banshee Nachtseele unterstützt, die ihre Magie einsetzt, um unsere Truppen in die Flucht zu schlagen.\n\nWir wollen Nachtseele vernichtet sehen.\n\nGeht ins Todesfeld und greift die Moderfelle an. Falls Ihr Nachtseele nicht seht, tötet so lange Moderfellgnolle, bis sie auftaucht, und besiegt sie dann.\n\nIhre Essenz wird zu Staub zerfallen. Bringt mir diesen Staub als Beweis.", sourceObjective = "Tötet Gnolle der Moderfelle auf dem Todesfeld.\n\nSobald Nachtseele auftaucht, tötet sie ebenfalls.\n\nBringt Nachtseeles Essenz zu Hochexekutor Hadrec auf das Grabmal.", progress = "Habt Ihr Nachtseele besiegt, {name}? Unser Erfolg im Kampf gegen die Moderfelle hängt von ihrer Vernichtung ab!", completion = "Ich habe von Eurem erfolgreichen Überfall auf die Moderfellgnolle gehört, {name}, und diese Essenz ist der Beweis für Nachtseeles Tod.\n\nDie Geißel hat heute an Boden verloren. Euer Ansehen bei den Verlassenen ist gestiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[438] = { id = 438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfallene Fähre", description = "{name}, wir haben ein neues Nest der Geißel entdeckt: Die verfallene Fähre. Die Fähre liegt östlich des Grabmals und wird von Moderfellgnollen und anderen Untoten schwer bewacht.\n\nEs muss einen Grund dafür geben, warum die Geißel dieses Gebiet besetzt hat. Geht zur verfallenen Fähre und findet heraus, warum die Geißel sich dort aufhält.", sourceObjective = "Geht zur verfallenen Fähre.\n\nSucht nach dem Grund, warum die Geißel dort ist.", completion = "In diesem Boot ist ein Haufen eingewickelter Leichen aufgestapelt. Und wenn man nach Osten über den Lordameresee schaut, kann man gegenüber auf der Insel Fenris ein Dock sehen.\n\nDas Schicksal muss diese Toten auf der Insel Fenris ereilt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[439] = { id = 439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren der Moderfelle", description = "Aus den Leichen ragt eine nicht eingewickelte Hand heraus. Es handelt sich um die Hand einer Frau, von der Seuche pockennarbig, aber relativ frisch. \n\nAn der Hand befindet sich ein Ring. Als Ihr den Ring entfernt und untersucht, entdeckt Ihr eine Gravur:\n\n\"Für Deliah\".", sourceObjective = "Bringt Deliahs Ring zu Hochexekutor Hadrec auf das Grabmal.", progress = "{name}. Ihr kehrt zurück; darf ich also annehmen, dass Eure Nachforschungen Früchte trugen?", completion = "Ihr sagt, dieser Ring wurde von einer erst kürzlich getöteten Frau getragen?\n\nDie einzige nahe gelegene Quelle für solch einen Körper wären die Massengräber in Tirisfal. Die Moderfellgnolle müssen die Leichen wohl zur Insel Fenris bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[440] = { id = 440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gravierte Ring", description = "Wenn Ihr den Ehemann oder Geliebten finden wollt, der Deliah ihren Ring gab... dann sprecht mit Magistrat Sevren in Brill. Er sollte alle Dokumente über die jüngsten Todesfälle haben und wird mit etwas Glück herausfinden können, wer Deliah ist.\n\nAber ich würde meine Hoffnungen nicht zu hoch stecken. Wer auch immer ihr den Ring gab, ist wahrscheinlich tot. Oder, wenn er untot ist, kümmert Deliah ihn wahrscheinlich nicht mehr.", sourceObjective = "Bringt Deliahs Ring zu Magistrat Sevren nach Brill.", progress = "Hallo, {name}. Was führt Euch nach Brill zurück?", completion = "Vor nicht allzu langer Zeit lebte in Brill eine Deliah. Sie wurde im Massengrab beigesetzt, aber wenn das, was Ihr sagt, zutrifft, dann müssen die Moderfellgnolle ihre Leiche gestohlen und in den Silberwald gebracht haben.\n\nDie Moderfelle müssen, wie alle Teile der Geißel, vernichtet werden. Ich vertraue darauf, dass Ihr darauf hinarbeitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[441] = { id = 441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raleigh und Undercity", description = "Deliah hatte einen Ehemann, Raleigh, der nun in Undercity sein Zuhause hat. Wenn die Deliah, die in Brill wohnte, die ist, der dieser Ring gehörte, dann wird es Raleigh wissen.\n\nRaleigh ist im Handwerksviertel von Undercity.", sourceObjective = "Bringt Deliahs Ring zu Raleigh.", progress = "Kenne ich Euch?", completion = "Ja, dieser Ring gehörte meiner Frau. Ihr Schicksal war das all derer, die diese harten Zeiten nicht überstehen. Ihr Tod bedeutet mir nichts, genauso wenig wie die Geschichte, die Ihr von der Entwendung ihrer Leiche erzählt.\n\nSolche Gefühle sind vor langer Zeit in mir erloschen. Doch ein Verlangen brennt immer noch in meinem toten Herzen, {name}.\n\nDas Verlangen nach Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[442] = { id = 442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Insel Fenris", description = "Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris.\n\nIhr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten. Ich will seinen Kopf!\n\nDiese Mission ist so gefahrvoll, wie sie entscheidend ist, {name}. Ihr dürft nicht scheitern.", sourceObjective = "Bringt Hochexekutor Hadrec auf dem Grabmal Thules Kopf.", progress = "Der Geißel darf nicht gestattet werden, im Silberwald zu bleiben, {name}. Kommt zu mir zurück, wenn Ihr den Beweis für Thules Tod habt.", completion = "Der Tod von Thule Rabenklaue war kein unwichtiges Ereignis, {name}. Renferrel sagt mir, dass die Energien, die frei wurden, als Ihr Thule vernichtet habt, bis zum Grabmal zu spüren waren.\n\nDie Nachricht von Euren Taten verbreitet sich bei den Verlassenen wie ein Lauffeuer. Euer Wert für uns wächst unaufhörlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[443] = { id = 443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moderfellsekret", description = "Bevor wir einen Angriff auf die Insel Fenris starten können, müssen wir erst herausfinden, wer hinter den Moderfellgnollen steht. Unsere Apotheker glauben, ihr Ursprung liegt in der seltsamen Flüssigkeit, die durch ihre Körper fließt.\n\nGeht zur Insel Fenris, östlich der verfallenen Fähre, und sammelt Moderfellsekret von den Gnollen dort. Bringt es zu Apotheker Renferrel, draußen vor dem Grabmal.", sourceObjective = "Bringt 8 Flaschen Moderfellsekret zu Apotheker Renferrel auf das Grabmal.", progress = "Habt Ihr das Moderfellsekret, {name}?", completion = "Sehr gut. Dieses Sekret wird uns dabei helfen, die Natur der Moderfelle zu verstehen, und könnte uns ihre Schwächen aufzeigen... \n\n... sofern sie welche haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[444] = { id = 444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ursprünge der Moderfelle", description = "Ich habe das Sekret, das Ihr mir gebracht habt, in seine Grundbestandteile aufgelöst. Meine Ergebnisse sind nicht sehr aufschlussreich, aber ich konnte ermitteln, dass Hexenmeister- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden.\n\nWährend ich weiter das Sekret untersuche, möchte ich, dass Ihr eine Probe davon zu Bethor Iceshard nach Undercity bringt. Bethor ist kein Apotheker, aber sein Wissen von der Magie könnte uns helfen, das Geheimnis um die Moderfelle zu lüften.\n\nGeht. Ihr dürftet Bethor im Magieviertel von Undercity finden.", sourceObjective = "Bringt die Sekretprobe zu Bethor Iceshard nach Undercity.", progress = "Meine Studien erfordern große Konzentration. Ich will also hoffen, dass Euer Besuch von Bedeutung ist.", completion = "Diese Substanz ist mit mächtigen Zaubern versetzt, von denen ich einige seit einer langen, langen Zeit nicht mehr gesehen habe... \n\nEinen Moment - ich muss einen Erkenntniszauber sprechen...", sourceObjectiveStatus = "unverified-source-field" }
quests[445] = { id = 445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung in den Silberwald", description = "Zeit ist ein Luxus, den sich diejenigen, die für Lady Sylvanas arbeiten, nicht leisten können. Aber das wisst Ihr inzwischen sicher selbst.\n\nAls Mitglied der königlichen Apothekervereinigung ist es meine Pflicht, mein Wissen mit meinen Kollegen zu teilen, auf dass unsere gemeinsamen Bemühungen der dunklen Fürstin eines Tages die neue Seuche bescheren werden, die sie so ersehnt.\n\nBringt diese Erkenntnisse zu Apotheker Renferrel, der beim Grabmal im Silberwald stationiert ist. Folgt der Straße von Brill aus nach Süden. Geht dann nach Undercity südwestwärts.", sourceObjective = "Bringt Apotheker Johaans Erkenntnisse zu Apotheker Renferrel im Silberwald.", progress = "Was wollt Ihr von mir, {class}?", completion = "Ah, wie zuvorkommend von Apotheker Johaan, mir seine Nachforschungen zu schicken. Dank der ganzen jüngsten Entwicklungen hier im Silberwald hätte ich beinahe die Erkenntnisse vergessen, die aus Lordaeron und Tirisfal kommen. Das erinnert mich daran, dass ich diese Proben umgehend zur Nekropole losschicken muss.\n\nIhr müsst meine Abschweifungen entschuldigen. Verlängert Euren Aufenthalt im Silberwald ein wenig, {name}. Ein kräftiger {class} wie Ihr wäre hier durchaus von Nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[446] = { id = 446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thule Rabenklaue", description = "Dieses Sekret wurde von einem alten Kollegen von mir hergestellt: Thule Rabenklaue. Vor dem großen Krieg war er ein junger, aufstrebender Magier, aber als der Lichkönig immer mächtiger wurde, verriet er seine Brüder und verbündete sich mit der Geißel.\n\nIch hätte nicht gedacht, dass er noch lebt, geschweige denn, dass er die Moderfelle bei ihren Vorstößen gegen uns anführt.\n\nIch kenne viele seiner Zauber und kann dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt. Nehmt diese Spruchrolle mit zurück zu Apotheker Renferrel. Auf ihr stehen die Beschwörungsformeln, die man für den Trank braucht.", sourceObjective = "Bringt Bethors Spruchrolle zu Apotheker Renferrel auf das Silberwald-Grabmal.", progress = "Seid gegrüßt, {name}. Was hat Bethor gesagt?", completion = "Diese Schriftrolle ist voll mächtiger Magie. Ich habe noch nie solche Kräfte in einem Trank verwendet... Es wird eine mächtige Mixtur sein und dürfte Euch wertvolle Dienste leisten, wenn Ihr Thule in seiner Festung auf der Insel Fenris angreift.", sourceObjectiveStatus = "unverified-source-field" }
quests[447] = { id = 447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept für den Tod", description = "Arthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten wir sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen.\n\nMeine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. Sammelt Proben von den Spinnen im Huschdunkel im Nordwesten und von den Bären, die im Silberwald umherstreifen. Bringt diese Reagenzien zu Meisterapotheker Faranell von der königlichen Apothekervereinigung in Undercity.", sourceObjective = "Sammelt 6 Herzen von ergrauten Bären und 6 Proben Huschendes Blut und bringt diese zu Meisterapotheker Faranell nach Undercity.", progress = "Seid gegrüßt, {class}. Was wollt Ihr von der königlichen Apothekervereinigung?", completion = "Wie gut, dass Apotheker Renferrel Euch zu mir geschickt hat, {name}. Diese Proben werden sich als durchaus nützlich für unsere Zwecke erweisen. Ich werde gleich damit anfangen, ihre toxischen und verseuchenden Eigenschaften zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[448] = { id = 448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Hadrec", description = "Bevor Ihr einen Angriff auf die Insel Fenris unternehmt, meldet Euch bei Hochexekutor Hadrec. Er könnte zusätzliche Informationen oder Ausrüstung haben, die Ihr brauchen werdet.", sourceObjective = "Meldet Euch bei Hochexekutor Hadrec auf dem Grabmal.", completion = "Wenn das, was Bethor sagt, wahr ist, dann stellt Thule Rabenklaue eine Macht dar, um die sich jemand kümmern muss, und zwar bald.\n\nUm Euch bei dieser Aufgabe zu helfen, könnt Ihr Euch an unserem Arsenal hier bedienen...", sourceObjectiveStatus = "unverified-source-field" }
quests[449] = { id = 449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bericht der Todespirscher", description = "Auch wenn Quinns Wunden heilen, möchte ich doch unseren Bericht so schnell wie möglich zu Hochexekutor Hadrec bringen. Er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.", sourceObjective = "Bringt den Todespirscherbericht zu Hochexekutor Hadrec auf das Grabmal.", progress = "Habt Ihr herausgefunden, was den Todespirschern zustieß?", completion = "Ich hatte nicht mit einem solchen Ausmaß an Aktivitäten der Geißel im Silberwald gerechnet, geschweige denn mit den Problemen, die unsere Todespirscher bei ihren Erkundungsversuchen hatten.\n\nEure Hilfe für unsere Todespirscher war unschätzbar, {name}. Dafür erhaltet Ihr eine Belobigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[450] = { id = 450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept für den Tod", description = "Ihr könnt der königlichen Apothekervereinigung noch weiter zu Diensten sein, {name}.\n\nAls Arugal seine elenden Zauber über den Wald gelegt hat, verfluchte er eines unserer viel versprechendsten Mitglieder, Apotheker Berard. Als hirnloser Diener von Arugal ist Berard jetzt für uns nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat.\n\nBergt Berards Tagebuch aus seinem Studierzimmer im Gasthaus von Pyrewood und bringt es zu Apotheker Renferrel.", sourceObjective = "Bergt Apotheker Berards Tagebuch aus Pyrewood und bringt es zu Apotheker Renferrel auf das Grabmal.", progress = "Wie ich sehe, seid Ihr wieder zurück, {name}.", completion = "Apotheker Berards Tagebuch! Ihr seid wirklich recht tapfer, {name}. Jetzt lasst uns mal sehen, was Berard vorhatte, bevor er wahnsinnig wurde...", sourceObjectiveStatus = "unverified-source-field" }
quests[451] = { id = 451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezept für den Tod", description = "Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.\n\nEr erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem Finsterflossenmurloc entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte.\n\nSammelt Proben von diesem Moos sowie von dem seltenen verhärteten Tumor und bringt beides zu Meisterapotheker Faranell nach Undercity.", sourceObjective = "Bringt 6 Proben Seeschleicher-Moos, 6 Proben Seekrabbler-Moos und einen verhärteten Tumor zu Meisterapotheker Faranell nach Undercity.", progress = "Was führt Euch nach Undercity zurück, {name}?", completion = "Was für ein Schlag für die königliche Apothekervereinigung, Berard zu verlieren. Aber dank Eurer harten Arbeit und Apotheker Renferrels gewissenhaften Nachforschungen werden Berards Studien dennoch der dunklen Fürstin in ihrer Misere helfen können.\n\nWir stehen hier kurz vor einer großen Entdeckung, {name}. Wärt Ihr nicht so in der Kriegskunst erfahren, würde ich versuchen, Euch als Mitglied für die Vereinigung anzuwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[452] = { id = 452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pyrewood-Überfall", description = "Ihr kommt gerade rechtzeitig, {name}!\n\nDer Rat von Pyrewood wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Pyrewood unter seiner Kontrolle zu halten. Aber ich glaube, dass die Söhne von Arugal sich ohne die Führung durch den Rat von Pyrewood gegen ihren Meister stellen werden.\n\nIch werde nicht allein mit ihnen allen fertig. Ihr müsst mir helfen. Gemeinsam können wir den Rat für Lady Sylvanas zerschlagen.", sourceObjective = "Helft Todespirscher Faerleia, den Rat von Pyrewood zu töten.", completion = "Ihr habt wie ein wahrer Jünger der dunklen Fürstin gekämpft, {name}. Nachdem der Rat nun tot ist, können wir vielleicht ein für alle Mal die Kontrolle über diesen Ort erlangen und Arugal aus der Burg Shadowfang vertreiben. Ich ziehe den Hut vor Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[453] = { id = 453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach der Schattengestalt", description = "Viel Glück, {name}. Ich hoffe, Ihr könnt den Kerl finden, und dass er dann noch am Leben ist.\n\nWenn er die Sicherheit von Dunkelhain hinter sich gelassen hat, könnte er leicht Wildtieren zum Opfer gefallen sein.", sourceObjective = "Findet die Schattengestalt. Eure Hinweise:\n\nEr stammt nicht aus Dunkelhain.\n\nEr ist eine nervöse, hektische Person.\n\nEr verließ Dunkelhain und ging nach Westen.", progress = "Wer seid Ihr?? Lasst mich in Ruhe!", completion = "<Jitters seufzt... >\n\nJa, ich bin der Autor dieses Buches. Ihr habt mich letztendlich dann doch gefunden, wie?\n\nNun, wenn Ihr dieses Tagebuch gelesen habt... dann wisst Ihr gerade mal die Hälfte!", sourceObjectiveStatus = "unverified-source-field" }
quests[454] = { id = 454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach dem Hinterhalt", description = "Wir hatten vor dieser... Geschichte die Pulverfässer in mehreren Fuhren transportiert. Jetzt müssen wir die Arbeit aufteilen. Miran nimmt die Fässer, und ich passe auf die anderen auf.\n\nIch fühle mich nicht wohl dabei, Miran den Rest der Fracht ganz allein transportieren zu lassen. Vielleicht könntet Ihr ihn auf seiner nächsten Tour begleiten, wenn er fertig zur Abreise ist?", sourceObjective = "Sprecht mit Miran.", completion = "Hallo, {class}.\n\nIhr werdet mich zur Ausgrabungsstätte begleiten? Das hört man gern... Wer weiß, was die Dunkeleisenzwerge nach Saean und seinen Spießgesellen noch alles auf Lager haben?\n\nWie auch immer, lasst mich nur noch einige letzte Kontrollen durchführen. Sprecht wieder mit mir, wenn Ihr abreisefertig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[455] = { id = 455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Algaz-Spießrutenlauf", description = "Orcs vom Dragonmawklan haben im Sumpfland eine Zufluchtstätte. Und jetzt haben sie sich nach Dun Algaz ausgebreitet. Wir können nicht zulassen, dass sie ihren Einfluss auf dieses Gebiet behalten, sonst wird der Loch Modan vom Hafen von Menethil, unserer Hafenfestung im Sumpfland, abgeschnitten.\n\nBrecht durch Dun Algaz in das dahinterliegende Sumpfland durch und tötet dabei ein paar Orcs. Meldet Euch bei Valstag Ironjaw im Hafen von Menethil.\n\nNach Menethil kommt Ihr, indem Ihr Dun Algaz durchquert, anschließend nordwärts der Straße folgt und Euch dann an der Biegung westwärts haltet.\n\nWir verlassen uns auf Euch, {name}. Ihr dürft nicht scheitern.", sourceObjective = "Durchquert Dun Algaz.\n\nTötet 8 Späher der Dragonmaw und 6 Grunzer der Dragonmaw.\n\nMeldet Euch bei Valstag Ironjaw im Hafen von Menethil.", completion = "Euer Bericht enthält viele schlechte Nachrichten!\n\nIch weiß, dass die Dragonmaw verstärkt nach Algaz hineindrängen. Normalerweise verstecken sich die Dragonmaw nur oben in den Hügeln. Was sie dazu gebracht hat, nach Algaz hineinzuströmen, ist immer noch ein Rätsel... \n\nDanke, {name}. Und wir werden wahrscheinlich Eure Hilfe wünschen, wenn es darum geht, sich um diese Orcs zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[456] = { id = 456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht der Natur", description = "Seid gegrüßt, {name}. Ich bin Konservator Ilthalaine. Meine Aufgabe in Shadowglen ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.\n\nDie Frühjahrsniederschläge waren dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten.\n\nUnglücklicherweise sind die Bestände an Nachtsäblern und Distelebern zu stark angewachsen. Shadowglen kann nur eine gewisse Menge Futter für diese Tiere erzeugen. Zieht los, {class}, und dünnt die Eber- und die Säblerpopulation etwas aus, auf dass die Harmonie der Natur erhalten bleibt.", sourceObjective = "Tötet 7 junge Nachtsäbler sowie 4 junge Disteleber und kehrt dann zu Konservator Ilthalaine zurück.", completion = "Ihr habt Eure Pflichten gut erfüllt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[457] = { id = 457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht der Natur", description = "Die Jungbestände einiger Kreaturen hier im Shadowglen auszudünnen, war ein guter Anfang, {name}, aber es gibt immer noch etwas zu tun.\n\nDie Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Begebt Euch in den Wald und erschlagt im Namen des Gleichgewichts räudige Nachtsäbler und Disteleber.", sourceObjective = "Konservator Ilthalaine verlangt von Euch, 7 räudige Nachtsäbler und 7 Disteleber zu töten.", completion = "Ihr habt Eure Hingabe an die Natur deutlich bewiesen, {name}. Ein junger {class} wie Ihr hat eine viel versprechende Zukunft vor sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[458] = { id = 458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschützerin des Waldlandes", description = "Was ein Glück, dass Ihr hier seid, {class}. Vom Wispern der Waldgeister wurden mir seltsame Neuigkeiten zugetragen.\n\nDie geheimnisvolle Beschützerin des Waldlandes, Tarindrella, ist nach Shadowglen zurückgekehrt. Jahrelang war die Gegenwart der Dryade in den Wäldern Kalimdors nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.\n\nSucht Tarindrella und findet heraus, was sie in unseren Hain führt. Eine der Schildwachen berichtete, sie südwestlich von Aldrassil gesehen zu haben.", sourceObjective = "Sucht die Dryade, die als Tarindrella bekannt ist.", completion = "Es sieht so aus, als hättet Ihr mich gefunden, junger {race}. Melithar ist ein weiser Druide, wenn er Euch geschickt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[459] = { id = 459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschützerin des Waldlandes", description = "Etwas Böses braut sich im Wald von Teldrassil zusammen. Schaut Euch die Hügel an, in denen die friedlichen Furbolgs früher hausten. Sie haben ihre Heime verlassen und sammeln sich unter dem Banner des Knarzklauenstamms.\n\nNur die Verderbtheit des bösartigen Teufelsmooses könnte eine solche Wandlung geschehen lassen. Die Grells und Grellkin suchen die Gegend heim und bedrohen die Einwohner von Shadowglen. \n\nSpürt diese Grells und Grellkins auf, {name}, und überzeugt Euch, ob sie wirklich unter dem Einfluss des bösartigen Teufelsmooses stehen.", sourceObjective = "Sammelt 8 Stücke Teufelsmoos und bringt sie zu Tarindrella.", progress = "Bestätigt meinen Verdacht, {name}. Bringt mir 8 Stücke Teufelsmoos.", completion = "Der Dienst, den Ihr den Lebewesen in Shadowglen erwiesen habt, ist eine Belohnung wert, {name}.\n\nLeider habt Ihr aber dennoch meine Befürchtungen bestätigt. Wenn die Grells von dem Teufelsmoos besudelt wurden, dann ist kaum auszudenken, was aus den Furbolgs des Knarzklauenstamms geworden ist, die einst hier lebten.\n\nSolltet Ihr Euch jemals in Dolonaar wiederfinden, {class}, sucht den klugen Druiden Athridas Bearmantle auf. Er teilt unsere Sorge um das Wohlergehen des Waldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[460] = { id = 460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stücken begraben", description = "Ihr seht nicht aus wie ein Moderfell. Gut. Ich hatte die Hoffnung schon aufgegeben...\n\nMein Name ist Alaric und ich war einst Thules oberster Diener und Leibwächter. Er nutzte seine Magie, um mich vor der Pest des Untodes zu \"schützen\", ein schöner Schutz... denn sein Zauber bürdete mir ein Unleben auf, dem ich nicht entrinnen kann. Und nachdem er diese verfluchten  der Moderfellgnolle erschaffen hatte, hat Thule mich geköpft... und meinen Kopf den Gnollen zum Spielen gegeben!\n\nBitte, bringt mich zu meinem Körper. Ich glaube, die Gnolle haben ihn hier in der Burg Fenris, nahe den Stallungen, in einem namenlosen Grab verscharrt.", sourceObjective = "Bringt Alarics Kopf zu seinem Grab.", progress = "Dieses Grab wurde in aller Eile gebuddelt.", completion = "Danke, {name}. Ich hatte schon befürchtet, die Gnolle hätten meinen Körper zerstört. Gut zu wissen, dass dem nicht so ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[461] = { id = 461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versteckte Nische", description = "Ich kenne eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist. Außerdem enthält sie noch etwas, das Ihr nützlich finden könntet. Bringt mich dorthin!\n\nDie Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.\n\nNehmt meinen Körper mit, aber lasst die Stiefel hier. Die haben mir sowieso nie richtig gepasst.", sourceObjective = "Bringt Alaric zur versteckten Nische.", progress = "Hier ist es! Bringt mich etwas näher heran...", completion = "Na bitte, sie ist offen. Lasst mich hier. Ich habe die besten Jahre meines Lebens in dieser Burg verbracht, und der Gedanke daran, in diesen Mauern zu ruhen, wirkt tröstlich.\n\nAchtet darauf, die Nische ordentlich zu schließen - ich möchte nicht von diesen Moderfellen gefunden werden.\n\nOh, und nehmt dies. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[463] = { id = 463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sumpfhüter", description = "Ihr habt vom Sumpfhüter gehört? Ihr sucht doch nicht etwa nach ihm, oder? Nun, ich behaupte ja, Ihr seid verrückt, wenn dem so ist, aber wer bin ich, dass ich <einen Narren/eine Närrin> davon abhalte, in den Tod zu gehen?\n\nFalls Ihr ihn sucht - hmmm, ich habe gehört, er sei in den Marschen, ostwärts von dort, wo die Straße nach Dun Modr abzweigt. Er lungert dort bei den Kroks und Schlimmerem herum!\n\nAch, und lasst Euer Geld besser hier. Ihr werdet es dort, wo Ihr hingeht, nicht brauchen... und Ihr wollt doch sicher nicht, dass der alte Grünling sich an Eurem Gold einen Zahn ausbricht, wenn er Euch mittendurch beißt.", sourceObjective = "Findet den Sumpfhüter.", completion = "Die Wurzeln und Farne sagen Gutes über Euch, Kleiner. Obwohl ich viele Namen habe, höre ich doch nur auf wenige. Aber Ihr mögt mich Rethiel nennen.\n\nUnd Ihr müsst mir lauschen... denn dieses Land leidet an eiternden Wunden, und ich betraue Euch damit, sie zu heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[464] = { id = 464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsflaggen", description = "Der orcische Dragonmawklan war am Ende des zweiten Krieges so gut wie vernichtet, nachdem sie die Kontrolle über ihre Schoßtierchen, die roten Drachen, verloren hatten. Die Drachen waren nicht sehr freundlich zu ihren früheren Herren und machten gnadenlos Jagd auf die Dragonmaw. Die wenigen, die überlebten, flohen aus Grim Batol in die Berge östlich von Whelgars Ausgrabungsstätte.\n\nJetzt haben sie an Stärke gewonnen und besitzen ein Lager nordöstlich von Menethil.\n\nWir wollen, dass Ihr dieses Lager angreift. Sammelt und bringt mir ihre Kriegsflaggen als Beweis.", sourceObjective = "Bringt Captain Stoutfist 8 Kriegsflaggen der Dragonmaw.", progress = "Habt Ihr das Lager der Dragonmaw angegriffen?", completion = "Gut gekämpft, {name}. Die Dragonmaw sind keine solche Bedrohung mehr wie zu den Zeiten, als sie noch Drachen unter sich hatten, aber sie sind dennoch harte Gegner.\n\nDie Dragonmaw werden angeführt von Nek'rosh, Sohn von Nekros, der vor vielen Jahren der Anführer der Dragonmaw war. Nekros verwendete mächtige Magie, um die roten Drachen zu bändigen, aber als ihn diese Magie im Stich ließ ... waren die Drachen nicht glücklich.\n\nNekros wurde getötet, und sein Sohn hat Rache an den Drachen geschworen, die seinen Vater erschlugen.", sourceObjectiveStatus = "unverified-source-field" }
quests[465] = { id = 465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nek'roshs Schachzug", description = "Während Ihr die Dragonmaw bekämpft habt, haben wir mehr über deren Pläne herausgefunden.\n\nNek'rosh hat Katapulte gebaut und beabsichtigt, Menethil zu belagern! Und dank der Kämpfe in Dun Algaz sind wir effektiv von Verstärkungen abgeschnitten!\n\nIhr müsst diese Katapulte zerstören. Sie befinden sich im Lager der Dragonmaw.\n\nHier, nehmt diesen Zunder. Kämpft Euch zu den Katapulten durch und lasst sie mit dem Zunder in Flammen aufgehen.\n\nUnd nachdem Ihr das getan habt, findet und tötet Nek'rosh. Wir müssen dieser Dragonmawbestie den Kopf abschlagen.", sourceObjective = "Zerstört die Katapulte der Dragonmaw.", progress = "Ihr seht das erste Katapult vor Euch. Wollt Ihr es entzünden?", completion = "Ihr legt etwas von dem Zunder auf das Katapult und schlagt dann einen Funken darauf.\n\nFlammen schlagen hervor und breiten sich schnell aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[466] = { id = 466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Pyrophor", description = "Ich habe gehört, im Sumpfland wurde in einer Höhle nordwestlich vom Algaz-Tor ein seltenes Erz namens Pyrophor gefunden. Pyrophor ist instabil und schwer anzuwenden, ohne sich dabei selbst in die Luft zu sprengen, aber ich bin mir sicher, wenn man es auf die richtige Art und Weise verhüttet, könnte man daraus Kanonenkugeln mit einer ziemlichen Durchschlagskraft herstellen.\n\nBesorgt mir Pyrophorerz und ich finde jemanden, der mutig genug ist, damit zu experimentieren.\n\nOh, und um dieses Erz aus einer Ader zu schürfen, müsst Ihr Euch mit Bergbau auskennen. Wenn dem nicht so ist, dann... nehmt einen Freund mit in diese Höhle, der es tut!", sourceObjective = "Bringt 6 Ladungen Pyrophorerz zu Pilot Stonegear nach Dun Morogh.", progress = "Wo ist denn das Erz, {name}?!", completion = "Ihr habt das Erz! Gut gemacht, {name}! Ich werde sofort jemanden damit arbeiten lassen. Wollen wir hoffen, dass er sich dabei nicht in die Luft sprengt!", sourceObjectiveStatus = "unverified-source-field" }
quests[467] = { id = 467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonegears Suche", description = "Pilot Stonegear liebt seine Belagerungsmaschine, wie jeder Pilot es auch sollte! Und er ist immer begierig, neue Wege zu finden, die Feuerkraft seines Panzers zu vergrößern!\n\nEr hat Gerüchte über ein seltenes Erz gehört und sucht jetzt nach jemandem, der es für ihn auftreibt. Wenn es Euch also in den Fingern juckt, dann sucht Stonegear in Steelgrills Depot in Dun Morogh auf und schaut mal, was er will.", sourceObjective = "Sprecht mit Pilot Stonegear.", completion = "Hallo {name}. Ihr seid hier wegen des Auftrags, den ich habe, hm? Es tut gut zu sehen, dass Ihr ein junger {race} seid, dessen Blut bei der Aussicht auf Abenteuer in Wallung gerät.", sourceObjectiveStatus = "unverified-source-field" }
quests[468] = { id = 468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Gebirgsjäger Rockgar", description = "Gebirgsjäger Rockgar sucht nach Freiwilligen für eine Mission durch Dun Algaz und in das Sumpfland hinein. \n\nWenn Ihr also Lust habt, Euch Eure Stiefel in dieser sumpfigen Gegend im Norden schmutzig zu machen, dann sprecht mit Rockgar in Dun Algaz. Dun Algaz liegt weiter die Straße entlang im Norden, hinter dem Wachturm.", sourceObjective = "Sprecht mit Gebirgsjäger Rockgar.", completion = "Hallo, {class}! Ihr seid wegen der Spähmission hier, stimmt's? Sehr gut!\n\nIch hoffe, Eure Ausrüstung ist in gutem Zustand, denn aus dieser \"Späh\"-Mission ist ein... größerer Schlamassel geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[469] = { id = 469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliche Lieferung", description = "Seid gegrüßt!\n\nIhr seid nicht zufällig in Richtung Menethil unterwegs? Falls nicht, würde ich Euch empfehlen, dort Halt zu machen, denn es ist ein guter Ort, um Waren zu kaufen oder etwas trinken zu gehen und sich auszuruhen.\n\nTja, wenn Ihr also zufälligerweise in diese Richtung unterwegs seid, dann habt Ihr doch sicher nichts dagegen, dieses Bündel Krokiliskenhäute zu James Halloran, dem Gerber, zu bringen?\n\nIch würde es ja selbst tun, aber meine Frau ist in letzter Zeit ziemlich launisch, und ich würde es gern so lange wie möglich aufschieben, ihr zu begegnen.", sourceObjective = "Liefert das Bündel Krokiliskenhäute bei dem Gerber James Halloran im Hafen von Menethil ab.", progress = "Guten Tag auch, {class}. Kann ich Euch für ein Paar Stiefel interessieren? Vielleicht einige frisch gegerbte Häute?", completion = "Hmm, das ist von Einar, oder? Er hat mir schon seit bald einer Woche seine Häute nicht mehr persönlich geliefert. Er hat sicher wieder Ärger mit seiner Frau!\n\nVielleicht lasse ich meine Frau mal mit Sida sprechen...", sourceObjectiveStatus = "unverified-source-field" }
quests[470] = { id = 470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stochern im Brühschlamm", description = "Bei meinem wöchentlichen Besuch an Ironbeards Grabmal wurde ich von grässlichen, triefenden Brühschlammern angegriffen! Natürlich geriet ich in Panik.\n\nIch habe meine Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung! Der Brühschlammer saugte sie einfach auf... Glücklicherweise gab mir das genug Zeit wegzulaufen.\n\nDie schlechte Nachricht ist, dass ich dringend den Inhalt meiner Tasche benötige!\n\nIch weiß nicht, nach welchem Brühschlammer ich meine Tasche geworfen habe; sie sehen alle gleich aus! Ironbeards Grabmal liegt nordöstlich von hier, in der Nähe von Dun Modr. Ich danke Euch wirklich sehr!", sourceObjective = "Einer der Brühschlammer bei Ironbeards Grabmal hat Sidas Tasche. Bergt sie und bringt sie ihr zurück in den Hafen von Menethil.", progress = "Habt Ihr meine Tasche gefunden?", completion = "Oh, danke sehr, {name}! Ich hatte schon befürchtet, sie wäre für immer verloren!\n\n\n\nHm, ich kann damit nicht mehr viel anfangen, aber wenn Ihr sie sauber macht, könnt Ihr sie bestimmt noch gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[471] = { id = 471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrlingspflichten", description = "Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen... Sagen wir einfach, es war kein schöner Anblick.\n\nDie Schwester sagt, er könnte durchkommen, aber derweil brauche ich immer noch meine Häute!\n\nUnd wenn Ihr noch ein paar von den Monstern töten wollt, hätte ich nichts dagegen, nach allem, was sie getan haben. Ihr findet die Kroks, wenn Ihr die Küste entlang nach Norden geht, hinter den Hütten der Murlocs.", sourceObjective = "Sammelt 6 riesige Krokiliskenhäute und bringt sie zu James Halloran in den Hafen von Menethil.", progress = "Mein Lehrling ist wie ein Sohn für mich. Wird hart für ihn sein, sein Leben mit nur einem Bein zu fristen.\n\nAh, {name}, wie läuft's? Habt Ihr meine Häute?", completion = "Hmm... Ihr habt nicht zufällig Lust, bei mir in die Lehre zu gehen?\n\nHa! Nein, war nur ein Witz. Ihr seid sowieso viel zu alt. Außerdem - nach Eurem Aussehen zu urteilen, habt Ihr wahrscheinlich andere Ambitionen im Leben. Dennoch habt Ihr da ein paar feine Häute besorgt und ich werde damit etwas anfangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[472] = { id = 472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Dun Modr", description = "Dun Modr ist an die Dunkeleisenzwerge gefallen!\n\nMeine Wunden sind schwer, {class}. Ein Großteil meines Regiments wurde getötet! Diese Rohlinge der Dunkeleisenzwerge haben uns angegriffen, bevor wir uns nach dem Überfall auf den Thandol-Übergang wieder sammeln konnten.\n\nUnser Anführer, Longbraid, blies zum Rückzug. Als wir die Stadt verließen, wurde ich von einer verirrten Axt in den Rücken getroffen und alles wurde schwarz um mich.\n\nIch wachte hier in Menethil auf, aber ich fürchte um meine Kameraden. Ich hege allerdings noch Hoffnung. Vielleicht ist Longbraid noch am Leben! Seht nach, ob Ihr ihn in der Nähe von Dun Modr finden könnt, {race}!", sourceObjective = "Sucht nahe der Stadt von Dun Modr nach Longbraid.", completion = "Welcher mutige {class} bringt Kunde aus Menethil? Ah, {name} werdet Ihr genannt.\n\nIhr bringt Hoffnung in eine hoffnungslose Situation. Gut zu wissen, dass der junge Harlo überlebt hat. Auf der Flucht wurde ihm eine ernste Wunde zugefügt. Wir hatten kaum die Zeit, ihn auf dem Rücken des letzten überlebenden Reittiers unseres Regiments fortzuschicken.\n\nAber wir sind hier in einer gefährlichen Lage. Dun Modr ist gefallen, und wir sind nur ein Schatten des großen Regiments, das wir einmal waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[473] = { id = 473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Captain Stoutfist", description = "{name}. Der Dragonmawklan der Orcs zeigt nicht nur in Algaz Stärke. Captain Stoutfist wünscht mit denen zu sprechen, die Hilfe gegen diese Orcs anbieten wollen. Er ist in der Burg, im Kriegsraum.", sourceObjective = "Sprecht mit Captain Stoutfist.", completion = "{name}. Valstag klärte mich über Eure bisherigen Erfolge mit den Orcs des Dragonmawklans in Dun Algaz auf. Ihr seid ein {race} von Wert.\n\nUnd ich habe eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[474] = { id = 474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg über Nek'rosh", description = "Jetzt, nachdem die Katapulte abgebrannt wurden, sucht und tötet Häuptling Nek'rosh.", sourceObjective = "Tötet Häuptling Nek'rosh.\n\nBringt Nek'roshs Kopf zu Captain Stoutfist.", progress = "Habt Ihr Nek'rosh getötet?", completion = "Saubere Arbeit, {name}. Ihr habt den Orcs vom Dragonmawklan einen deutlichen Schlag verpasst. Vielleicht erholen sie sich nie wieder davon. Außerdem hat die Zerstörung dieser Katapulte den Hafen von Menethil gesichert.\n\nIhr seid ein vorzüglicher {race}, und das Königreich von Ironforge belohnt die, die ihm gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[475] = { id = 475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein beunruhigender Wind", description = "Ein beunruhigender Wind weht durch den Wald.\n\nGaerolas Talvethren dient den schlafenden Druiden der Kralle in den Grabhügeln von Ban'ethil als Großer Aufseher. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit Ysera gerecht werden.\n\nAber es gab länger keine Nachricht von Gaerolas, und ich werde etwas nervös. Reist nach Osten, zum Dorf Starbreeze, und bringt mir einen Bericht von Gaerolas, auf dass ich meine Sorgen begraben kann, da ich weiß, dass meine träumenden Brüder sicher schlummern.", sourceObjective = "Sucht Gaerolas Talvethren im Dorf Starbreeze auf.", completion = "Dank sei den Waldgeistern, dass Ihr hier seid! Ich wusste, Athridas würde die Probleme spüren und Hilfe schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[476] = { id = 476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis der Knarzklauen", description = "Der Knarzklauenstamm ist verderbt worden!\n\nDie einstmals friedliebenden Furbolgs haben sich gegen die Beschützer des Waldes gewandt. Sie haben mich hinterrücks überfallen, als ich auf dem Weg zum Grabhügel von Ban'ethil war und liefen weiter, um Starbreeze zu plündern. Ursal der Raufer, ihr Häuptling, benutzt die bösen Mächte des Teufelsmooses, um sie wahnsinnig werden zu lassen.\n\nMeine Wunden sind zu schwer, ich kann nicht zu Athridas zurückkehren und ihm diese schlimme Nachricht überbringen. Junger {class}, diese Aufgabe bleibt Euch überlassen. Wir können nur hoffen, dass die verrückten Knarzklauen noch nicht bis nach Ban'ethil vorgedrungen sind!", sourceObjective = "Kehrt zu Athridas Bearmantle nach Dolanaar zurück.", completion = "Bei den Sternen! Dies ist wirklich sehr furchterregend!", sourceObjectiveStatus = "unverified-source-field" }
quests[477] = { id = 477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzübergänge", description = "Wie Ihr vielleicht bereits wisst, die Stadt Ambermill ist weiterhin eine Quelle der menschlichen Opposition, die nötige Unterstützung erhalten sie meist durch die Hexer von Dalaran.\n\nIch weiß nicht, wie ihr Plan aussieht, aber ihr Interesse an einem Hinterwäldler-Dorf wie Ambermill zeigt mir, dass es von größerer Bedeutung sein muss.\n\nVon Hillsbrad aus haben sie wagenweise Kisten geliefert. Viele dieser Vorräte werden in ein kleines Camp nördlich von Pyrewood gebracht. Bringt mir den Inhalt einer dieser Kisten.", sourceObjective = "Holt den Inhalt einer der Kisten von den Hexern aus Dalaran. Ihr findet Pyrewood im Süden.", completion = "<Als Ihr den Kistendeckel aufstemmt, findet Ihr eine Anzahl sorgfältig verpackter Objekte. Oben auf der Kiste liegt ein Bündel vergilbter Landkarten, auf denen anscheinend der Silberwald und andere Teile von West-Lordaeron abgebildet sind.\n\nUnter den Landkarten liegt ein geheimnisvoll aussehender magischer Anhänger.>", sourceObjectiveStatus = "unverified-source-field" }
quests[478] = { id = 478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karten und Runen", description = "<Schnell entnehmt Ihr den Anhänger aus der Kiste und setzt den Deckel wieder auf.>", sourceObjective = "Bringt den seltsamen Anhänger zu Schattenpriester Allister in dem Grabmal.", progress = "Habt Ihr etwas Nützliches erfahren, {name}?", completion = "Karten und diesen... Anhänger, hm? Interessant.\n\nEs ist offensichtlich, dass die Hexer von Dalaran sich aus einem bestimmten Grund für Ambermill interessieren, aber ihr Ziel ist mir bislang noch verborgen.\n\nVielleicht weiß Dalar etwas über ihren Zweck.", sourceObjectiveStatus = "unverified-source-field" }
quests[479] = { id = 479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambermill-Nachforschungen", description = "Dalar versucht die Quelle für die Zaubereien der Hexer zu finden. In der Zwischenzeit müssen wir ihren Fortschritt mit allen Mitteln aufhalten...\n\nAlle Herbeizauberer, Magier und Beschützer tragen mit Sicherheit ihre Anhänger. Nehmt sie ihnen ab und bringt sie hierher.\n\nFolgt der Hauptstraße in südlicher Richtung und nehmt dann die östliche Abzweigung nach Ambermill.", sourceObjective = "Beschafft 8 Anhänger aus Dalaran für Schattenpriester Allister beim Grabmal.", progress = "Wir müssen uns eilen, ihr Plan darf keinerlei Früchte tragen, oder wir können unsere Herrschaft über den Silberwald verlieren.", completion = "Dalar hat herausgefunden, dass trotz des Rückschlags das Wirken schon weit fortgeschritten ist.\n\nEin sehr mächtiger Hexer leitet die magische Energie. Er muss schnellstmöglich aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[480] = { id = 480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wirker", description = "Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten. Das ist eine schwierige Tat, denn ohne Zweifel wird er von anderen Magiern und Wärtern beschützt.\n\nIhr müsst ihn schnellstens erledigen. Bringt mir seinen Stab, sobald er tot ist. Geht jetzt.", sourceObjective = "Tötet den Erzmagier von Dalaran und bringt seinen Stab zu Schattenpriester Allister in dem Grabmal.", progress = "Schnell, die Zeit ist knapp, {name}!", completion = "Die Magie der Hexer löst sich auf und die Leyenergien kehren in ihren Ruhezustand zurück. {name}, Eure Bemühungen waren erfolgreich. Wir haben unseren Feinden einen mächtigen Schlag versetzt, wie auch den übermächtigen Hexern von Dalaran.\n\nDennoch müssen wir weiterhin wachsam sein, da wir wissen, dass die Quelle der Energie so nahe liegt... Für die Zukunft müssen Pläne gemacht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[481] = { id = 481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalars Analyse", description = "Bringt den Anhänger zu Dalar Dawnweaver, vielleicht kann er Licht in das Dunkel der Hexerpläne bringen.", sourceObjective = "Bringt den mit Runen gravierten Anhänger zu Dalar Dawnweaver in dem Grabmal.", progress = "Ja, {class}? Was ist?", completion = "Interessant, weitere Machenschaften der Kirin Tor, wie es scheint. Dies ist ein mächtiges Artefakt. Es wurde häufig von mächtigen Hexern der Kirin Tor benutzt, um magische Energien zu kanalisieren.\n\nDie Anzahl, die sie davon nach Ambermill bringen, sagt mir, dass sie ein Projekt großen Ausmaßes durchführen wollen.\n\nIch werde versuchen, ihre Schilde zu durchdringen und ihre Absicht zu ermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[482] = { id = 482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalaran Absichten", description = "Natürlich! Wie konnte ich das vergessen?\n\nAmbermill war einer der Orte, die von den Kirin Tor gekennzeichnet wurden, weil dort ein ruhender Leyenergieknoten liegt. Mit Sicherheit haben die Hexer vor, diesen Knoten wiederzuerwecken und seine Energien für etwas Größeres zu nutzen.\n\nDas dürfen wir nicht zulassen...\n\nUm die Leyenergien des Gebietes zu aktivieren, bedarf es einer großen Macht. Wir können sie aufhalten, indem wir die Anhänger der Hexer an uns nehmen.\n\nBringt diese Information zu Allister, er wird dann über das weitere Vorgehen entscheiden.", sourceObjective = "Sprecht mit dem Schattenpriester Allister in dem Grabmal.", completion = "Ihr bringt schlechte Neuigkeiten, {name}. Sollte Dalar recht behalten - und ich habe keinerlei Grund, dies zu bezweifeln - müssen wir schnell handeln.\n\nIch muss unseren Angriffsplan mit ihm beraten. In der Zwischenzeit müssen wir ihr Weiterkommen aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[483] = { id = 483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Relikte des Erwachens", description = "Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen.\n\nWenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.\n\nReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Weck-Ritual vorbereiten kann.", sourceObjective = "Bringt die Relikte des Erwachens zu Athridas Bearmantle nach Dolanaar.", progress = "{name}, die entführten Druiden der Kralle werden auf ewig im Smaragdgrünen Traum gefangen gehalten, wenn wir die Relikte des Erwachens nicht aus dem Grabhügel von Ban'ethil im Westen herbringen können.\n\nJede Minute, die wir zögern, bringt ihr Schicksal einen Schritt näher an die ewige Verdammnis.", completion = "Ihr hattet Erfolg, junger {class}! Gut gemacht. Und gerade rechtzeitig, wie ich hinzufügen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[484] = { id = 484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häute junger Krokilisken", description = "Ich bin James Halloran, der Gerber. Meine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt.\n\nHabt Ihr Einar getroffen? Er ist einer der Jäger, die mir Krokiliskenhäute bringen.\n\nMir fehlen zurzeit weichere Häute, wie die von jungen Krokilisken.\n\nDa ich bald keine mehr habe, bin ich bereit, Euch einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Ihr könnt die jungen Kroks in den Marschen gleich außerhalb der Stadt finden.", sourceObjective = "Besorgt Euch 4 Häute junger Krokilisken für James Halloran im Hafen von Menethil.", progress = "{name}, nicht wahr? Habt Ihr meine Häute?", completion = "Ihr habt gute Arbeit geleistet, {name}. Die Qualität dieser Häute ist superb. Ich muss so bald wie möglich mit dem Gerben dieser Häute beginnen. Oh, bevor ich jedoch damit anfangen kann, habe ich noch eine andere Aufgabe zu erledigen. Ich denke, dass Ihr sie übernehmen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[485] = { id = 485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht OOX-09/HL!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe Obnoticus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe von Skulk Rock abgestürzt, dort, wo der Fluss entspringt!\"", sourceObjective = "Bringt das Notsignal zu Oglethorpes Leitroboter an der Quelle des Flusses im Hinterland, nahe Skulk Rock.", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-09/HL funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[486] = { id = 486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursal der Raufer", description = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. {name}, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.\n\nIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. Erst dann ist das Ritual vollkommen.\n\nEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Begebt Euch nach Südwesten zur Höhle der Knarzklauen und erschlagt ihn.", sourceObjective = "Tötet Ursal den Raufer und kehrt zu Athridas Bearmantle nach Dolanaar zurück.", completion = "{name}, Ihr habt Euch als ein zutiefst würdiger und geschickter {class} erwiesen. Ein {race}, welcher dem Pfad der Ehre so sicher folgt wie Ihr, findet mit Sicherheit großen Ruhm in dieser Welt.\n\nMögen die Waldgeister Euch auf all Euren Wegen beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[487] = { id = 487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße nach Darnassus", description = "Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.\n\nJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.\n\n{class}, bewaffnet Euch im Namen des Heiligen Waldes. Ihr Bau liegt irgendwo unterhalb dieser Position. Erschlagt 6 Wegelagerer der Knarzklauen und berichtet mir dann.", sourceObjective = "Erschlagt 6 Wegelagerer der Knarzklauen und kehrt zu Schildwache Amara Nightwalker außerhalb Dolanaars zurück.", progress = "Die Straße ist noch immer nicht sicher, {class}. Kehrt um und erschlagt 6 Wegelagerer der Knarzklauen und kommt zu mir zurück.", completion = "Ihr habt den guten Leuten von Dolanaar und Darnassus gute Dienste geleistet, tapferer {class}. Als Mitglied der Schildwache von Teldrassil beglückwünsche ich Euch zu Euren Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[488] = { id = 488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenns Aufträge", description = "Ihr seid bereit zu arbeiten, wie ich sehe. Ihr habt Glück, denn es vergeht kein Tag, an dem ich mir nicht wünschte, ein junger {class} wäre hier, der mir zur Hand geht.\n\nIhr seht, {name} , ich kann Euch zu Eurem Glück verhelfen und mit Dingen versorgen, von denen Ihr nie zu träumen wagtet. Damit dies jedoch geschieht, müsst Ihr mir gewisse Dinge beschaffen.\n\nMeine Angelegenheiten im Wald erfordern oft gewisse... Reagenzien. Bringt mir 3 Nachtsäbler-Fangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.\n\nDas soll unser kleines Geheimnis bleiben, {race}.", sourceObjective = "Bringt Zenn Foulhoof außerhalb von Dolanaar 3 Nachtsäblerfangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.", progress = "Ihr wart also ein fleißiges Bienchen, {name}? Ich habe darauf gewartet, dass Ihr mir das bringt, was ich benötige.", completion = "Ha ha! Wirklich hervorragend.\n\nWer hätte jemals gedacht, dass ein {race} mir, Zenn Foulhoof, meine Wünsche erfüllen würde? Selbst ich hätte es nicht geglaubt. Aber so geht es nun mal... unsere so geliebte Welt ist doch voller Überraschungen.\n\nEin Hoch auf die Naiven und Gutgläubigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[489] = { id = 489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Befreiung!", description = "Der Rat des Waldes hat die Meldung erhalten, dass Ihr Zenn Foulhoof behilflich gewesen seid. Der Satyr ist ein Feind des Waldes. Als {race} müsstet Ihr eigentlich mehr Verstand haben, als den Wald zu entweihen, indem Ihr Kreaturen der Natur tötet.\n\nIhr müsst Eure Ehre in den Augen des Rates wiederherstellen, wenn Ihr weiterhin ein Freund von Teldrassil bleiben wollt.\n\nErteilt Foulhoof eine Lektion, dann habt ihr Eure Schuld beglichen. Teufelszapfen sind verderbte Samen, die von Bäumen fallen. Sie sondern grünen Rauch ab.\n\nGebt Foulhoof einige davon. Er wird denken, dass Ihr ihm eine harmlose Leckerei gebracht habt.", sourceObjective = "Sammelt 3 Teufelszapfen und gebt sie Zenn Foulhoof außerhalb von Dolanaar.", progress = "Was habt Ihr für mich, {name}? Eine leckere kleine Zwischenmahlzeit, nehme ich an?", completion = "Wie nett von einem {race}! Ich wusste, dass Ihr nützlich sein würdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[491] = { id = 491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberstab an Bethor", description = "Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab herstellten, der aus den Lehrlingszauberstäben zusammengewoben wurde, den jeder Magier besaß. Dieser Zauberstab war ein Symbol ihrer Freundschaft, und obwohl Thule ihn hinterher verachtete, konnte er sich doch weder davon trennen noch ihn den anderen überlassen. Also stahl er den Zauberstab und versteckte ihn in Burg Fenris.\n\nHier. Bringt den Zauberstab zu Bethor Iceshard, einem Freund von Thule aus vergangenen Zeiten. Ich bin sicher, er möchte ihn haben.", sourceObjective = "Bringt den gewebten Zauberstab zu Bethor Iceshard in das Magieviertel von Undercity.", progress = "{name}. Habt Ihr Thule Rabenklaue besiegt?", completion = "... was ist das? Thule hatte unseren gewebten Zauberstab? Ich dachte, er sei verloren, als unsere Freundschaft zerbrach und er sich auf die Seite des Lichkönigs stellte!\n\nEr kann seine Macht nie verwendet haben, denn das hätte ich gespürt. Und es ist gut, dass er ihn nicht benutzt hat...\n\nDies ist ein wunderbarer Fund. {name}, Ihr habt meinen Dank und sollt belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[492] = { id = 492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Seuche", description = "Berichten der Todeswachen zufolge wurde gerade ein weiterer dieser dummen Zwergen-Gebirgsjäger gefangen genommen. Die Todeswächter benutzen gern den Keller der Taverne Zur Galgenschlinge als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann.\n\nWarum... kümmert... Ihr Euch nicht um den gefangenen Gebirgsjäger und schaut, wie er das Spezialgetränk verträgt, das ich für ihn gemacht habe? Das ist nur ein kleiner Eindruck dessen, was die dunkle Fürstin für den Rest von Azeroth geplant hat.", sourceObjective = "Bringt Johaans Spezialgetränk zum gefangenen Gebirgsjäger.", progress = "Hätte ich nur mein getreues Gewehr bei mir, wärt Ihr so gut wie tot, {class}. Wartet nur, bis die Dampfpanzerbrigade eintrifft, um mich zu retten!", completion = "Ah, endlich, etwas zu trinken. Das ist zwar sicherlich kein Rhapsody-Malz, aber zum jetzigen Zeitpunkt ist mir alles recht, um meine Kehle anzufeuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[493] = { id = 493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in das Vorgebirge von Hillsbrad", description = "Die Königliche Apothekervereinigung steht unter enormem Druck seitens der dunklen Fürstin, eine neue Seuche zu entwickeln. Wir arbeiten sehr hart und haben bereits einige Fortschritte gemacht. Wir denken, dass der Erfolg sich umso schneller einstellen wird, wenn wir innerhalb der Vereinigung Informationen austauschen.\n\nAus diesem Grunde möchte ich, dass Ihr meine letzten Funde an Apotheker Lydon in Tarrens Mühle überbringt, einem kleinen Städtchen, das sich im Vorgebirge von Hillsbrad befindet. Die Reise wird sehr lange dauern.\n\nBegebt Euch Richtung Süden und bleibt auf den Straßen. Beachtet die Schilder auf das Genaueste!", sourceObjective = "Bringt die Funde von Apotheker Renferrel zu Apotheker Lydon nach Tarrens Mühle im Vorgebirge von Hillsbrad.", progress = "Habt Ihr etwas für mich?", completion = "Ah, wie wunderbar. Ich habe den größten Respekt vor Apotheker Renferrel. Ich brenne darauf, seine Arbeiten zu studieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[494] = { id = 494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Zuschlagen", description = "Schweigt und passt auf, {class}.\n\nIch wurde an diesen Ort geschickt, um die Stadt Hillsbrad zu sondieren. Es handelt sich um eine Aufklärungsmission. Dabei ist von äußerster Wichtigkeit, dass Ihr sofort die Hochexekutorin Darthalia in Tarrens Mühle benachrichtigt. Bestellt ihr, ich, Todespirscherin Lesh, lasse ihr folgende Nachricht ausrichten:\n\n\"Der Schrei des Raben locket vom Westen her.\"\n\nFolgt der Straße gen Osten und beachtet die Schilder genau. Nun aber schnell! Macht Euch auf den Weg nach Tarrens Mühle. Es ist Eile geboten!", sourceObjective = "Reist nach Tarrens Mühle, um die Nachricht von Todespirscherin Lesh an Hochexekutorin Darthalia zu überbringen.", completion = "Der Schrei des Raben locket vom Westen her?\n\nWas für superbe Neuigkeiten! Hillsbrad ist reif für den Angriff. Jetzt können wir unseren Zerstörungsplan durchführen. Das wird Varimathras erfreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[495] = { id = 495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Mug'Thol und seine Ogerkriegsmeute wurde nach Alterac geschickt, um die Krone des Willens für Lady Sylvanas zu holen. Anstatt sie zurückzubringen, hat der Idiot allerdings versucht, sie aufzusetzen... Oger können wohl einfach keinen Dingen widerstehen, die glitzern und schimmern, nehme ich an.\n\nSeine stümperhaften Aktionen sind allerdings zu einem Problem geworden. Die Krone des Willens hat ihm geholfen, der Besessenheit zu widerstehen, die ihm auferlegt wurde, damit er Lady Sylvanas dient.\n\nDie dunkle Fürstin möchte ein Exempel statuieren. Begebt Euch nach Tarrens Mühle in Hillsbrad und meldet Euch bei Melisara, meinem dortigen Offizier.", sourceObjective = "Meldet Euch bei Melisara in Tarrens Mühle im Vorgebirge von Hillsbrad.", completion = "Ihr wurdet von Shalindra geschickt? Nun gut, Ihr werdet sehen, dass ich nicht viel Zeit mit Geplauder verplempere.\n\nMug'Thol ist ein Ärgernis und wir werden uns um ihn kümmern, schnell, gründlich und ohne Zwischenfälle.", sourceObjectiveStatus = "unverified-source-field" }
quests[496] = { id = 496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier des Leidens", description = "Ah, und wieder ein ekelhafter Tag in Tarrens Mühle. Diese ganze gesunde Luft verdirbt mir gründlich die Laune, {name}.\n\nJe schneller wir die Menschen hier erkranken lassen können, desto besser. Ich habe intensive Studien über mögliche tödliche Zutaten für meine Gebräue durchgeführt, aber ich habe nicht die Zeit, sie alle zu sammeln.\n\nWenn Ihr Euch nützlich machen wollt, dann besorgt mir Folgendes: 10 Graubärzungen sowie das sehr seltene und schwer zu findende Krabblersekret. Bären und Krabbler könnt Ihr gleich außerhalb von Tarrens Mühle finden.", sourceObjective = "Apotheker Lydon aus Tarrens Mühle möchte 10 Graubärzungen und etwas Krabblersekret.", progress = "Wie ich sehe, seid Ihr zurück. Ich hoffe, Ihr konntet mir die Zutaten beschaffen, die ich benötige. Diese Todesfreien Tage machen mich immer so trübsinnig.", completion = "Diese Exemplare sind perfekt. Nun, {name}, Ihr habt es vollbracht, mir eine winzigkleine Freude an einem weiteren dieser elendiglichen Tage zu machen. Ich weiß Eure Bemühungen zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[498] = { id = 498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung", description = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.\n\nAls wir nach Durnholde kamen, um uns umzusehen, wurden wir von einer großen Anzahl der Menschen überrascht. Wir haben mutig gekämpft, aber allein ihre Anzahl war so überwältigend groß, um uns zu besiegen. Sie haben einige von uns als Gefangene genommen, aber ich konnte entkommen.\n\nDurnholde befindet sich nicht weit südöstlich von uns, nur über den Fluss. Drull und Tog'thar werden dort gefangen gehalten, Ihr müsst sie retten.", sourceObjective = "Krusk in Tarrens Mühle braucht Euch, um Drull und Tog'thar aus der Burg Durnholde zu befreien.", completion = "Die Menschen wollten also unsere Krieger zu Sklaven machen, wie? Wir werden es ihnen zeigen!\n\nEs scheint, als hätten sie Gol'dir, unseren Anführer, an einen anderen Ort gebracht. Wir müssen ihn finden und befreien. Aber wir haben im Moment keine Ahnung, wo er sich befindet ...\n\nSobald wir eine Spur haben, werde ich Euch mit Sicherheit benachrichtigen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[499] = { id = 499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier des Leidens", description = "Es wird einen Moment dauern, diese Komponenten zu vermengen, damit ein, wie ich es nenne, Elixier des Leidens entsteht.\n\nDann mal los! Ah, es gibt doch nichts Schöneres in diesem elendiglichen Vorgebirge, als ein wenig Leiden in die Welt zu bringen.\n\nLasst uns mal überprüfen, ob unser kleiner Trank auch seine gewünschte Wirkung hat.\n\nGebt meiner Assistentin Umpi einen kleinen Schluck von dem, was die dunkle Fürstin sowohl für Menschen als auch für die Geißel geplant hat.", sourceObjective = "Gebt Umpi das Elixier des Leidens", progress = "Quaaaaak!", completion = "Quak!", sourceObjectiveStatus = "unverified-source-field" }
quests[500] = { id = 500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushridge-Kopfgeld", description = "Die Crushridge-Oger haben einen Ogerhort im Alteracgebirge nahe der verfallenen Stadt Alterac gebaut. Meine Späher berichteten mir, dass sie auch die Ruinen da erobert haben.\n\nWir dürfen aber nicht zulassen, dass sie sich da fest einnisten. Falls sie sich dort zu sicher fühlen, werden sie bestimmt ins Vorgebirge eindringen und wären dann praktisch vor unserer Haustür!\n\nBegebt Euch nach Norden in das Alteracgebirge auf Ogerjagd. Bringt mir die schmutzigen Knöchelknochen, die sie tragen, und Ihr habt Euch ein hübsches Kopfgeld verdient.", sourceObjective = "Sammelt 9 schmutzige Knöchelknochen von Crushridge-Ogern im Alteracgebirge. Bringt sie zu Marshal Redpath in Southshore.", progress = "{name}, immer noch auf Ogerjagd? Habt Ihr die Knöchelknochen, die Ihr laut meinem Befehl sammeln solltet?", completion = "Sehr gut, {name}. Ihr müsst Euch durch eine ganze Schiffsladung Oger gehackt haben, um diese Anzahl Knöchelknochen zu erhalten.\n\nDas sollte sie uns vom Halse halten. Zumindest für eine kleine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[501] = { id = 501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Schmerzen", description = "Oh, {name}..., in Hillsbrad blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.\n\nSo gern ich auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, meine Pflicht gegenüber der dunklen Fürstin ruft mich. Würdet Ihr mir helfen? Meine Forschungen führen mich zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Bringt mir etwas davon, dann können wir ein bisschen Spaß haben.", sourceObjective = "Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle.", progress = "Ich erinnere mich an Euch, {name}. Ihr wolltet mir dabei helfen mein neuestes Elixier zu brauen. Das Blut brauche ich, um den Einwohnern von Hillsbrad mein höchsteigenes, hausgemachtes Spezial-Elend zu präsentieren.", completion = "Wunderbare Sammlung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[502] = { id = 502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Schmerzen", description = "Ah, es geht doch nichts über den Geruch von frischem Blut im Vorgebirge!\n\nDann lasst uns eine Prise davon und ein wenig hiervon vermischen - und der einzig wahre Spaß kann beginnen! Die Kreation aus diesem Blut möchte ich Elixier der Schmerzen nennen. Wenn meine Berechnungen korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Lady Sylvanas sein. Aber wir müssen erst mal einen Testlauf machen.\n\nBringt dieses Elixier zum nördlichen Hof in den Feldern von Hillsbrad im Südwesten. Lasst uns sehen, wie Stanley, dem kleinen Hund von Bauer Ray, dieses 'Leckerli' so schmeckt.", sourceObjective = "Füttert Stanley mit dem Elixier der Schmerzen.", progress = "Wuff?", completion = "Ihr schüttet etwas von dem Elixier in Eure Hand und haltet es vor Stanleys Schnauze.", sourceObjectiveStatus = "unverified-source-field" }
quests[503] = { id = 503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gol'dir", description = "Soweit ich das aus den Dokumenten, die Ihr herbrachtet, ersehen kann, wird Gol'dir in einem großen Syndikatsstützpunkt im Norden festgehalten, höchstwahrscheinlich im Alteracgebirge. Er ist schon zu lange dort gefangen und muss endlich befreit werden.", sourceObjective = "Befreit Gol'dir und kehrt dann zu Krusk in Tarrens Mühle zurück.", progress = "Gebt mir den Schlüssel, {class}, ich werde das Schloss selbst aufschließen.", completion = "Danke, {name}. Laut Befehl des Kriegshäuptlings hatte ich die Führung der Expedition von Durotar, aber wie Ihr sehen könnt, lief es nicht ganz so wie eigentlich geplant. Sie haben mich in dieser Stadt gefangen gehalten, mich gezwungen zu arbeiten, ich musste Lasten tragen, graben...\n\nWas ich erlitten habe, ist jedoch unwichtig. Ich habe wichtige Informationen, die Ihr dem jetzigen Anführer unserer Gruppe überbringen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[504] = { id = 504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushridge-Kriegstreiber", description = "Nun, da Ihr die Bekanntschaft der Crushbridge-Oger gemacht habt, möchte ich, dass Ihr ihnen so richtig zeigt, was eine Harke ist...\n\nGeht zu den Ruinen von Alterac und sucht die Crushridge-Kriegstreiber. Ihr sollt eine große Anzahl von ihnen erschlagen - das ist der einzige Weg, um diese Schläger von dem Gebiet der Allianz fern zu halten.", sourceObjective = "Erschlagt 15 Crushridge-Kriegstreiber und kehrt dann zu Marshal Redpath in Southshore zurück.", completion = "Sehr gut. Hier ist Eure Belohnung.\n\nAls Ihr diese Kriegstreiber gesehen habt, konntet Ihr sehen, wie es um die Stadt von Alterac bestellt ist? Ich nehme an, nicht sehr gut. Oger sind nicht gerade für ihre Reinlichkeit bekannt.\n\nDank Eurer Bemühungen werden sie sich wohl jetzt von Southshore fern halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[505] = { id = 505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragsmörder des Syndikats", description = "Ich bin der neue Magistrat von Southshore. Ich wurde erst kürzlich ernannt, nachdem der vorherige Magistrat ermordet worden ist. Die Mörder wurden nie gefunden, aber unsere Nachforschungen haben ergeben, dass sie höchstwahrscheinlich vom Syndikat angeworben wurden - einer Gruppe von Dieben, angeführt von schurkischen Edlen des jetzt gefallenen Königsreichs von Alterac.\n\nDas Syndikat hat ein Lager nördlich von Tarrens Mühle, das von der Horde besetzt ist, und unsere neuesten Hinweise führen genau in dieses Lager. Erschlagt die Syndikatsmitglieder, die Ihr dort vorfindet.", sourceObjective = "Tötet 12 Schleicher des Syndikats und 8 Diebe des Syndikats, kehrt dann zurück zu Magistrat Henry Maleb nach Southshore.", completion = "Danke, {name}. Ein Teil dieser Bande dürfte zwar noch immer hier herumlungern, aber wir hoffen, dass einige der Diebe und Schleicher, die Ihr erschlagen habt, für den Tod des letzten Magistraten verantwortlich waren. Doch selbst wenn dem nicht so wäre, stellt das Syndikat auf jeden Fall eine Besudelung dieses Landes dar und ist ein Schandfleck für das gesamte Volk der Menschen. \n\nSouthshore wird ihren Tod begrüßen.", sourceObjectiveStatus = "unverified-source-field" }
quests[506] = { id = 506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackmoores Vermächtnis", description = "Vor ein oder zwei Tagen erhielt ich Besuch vom Anführer dieses Syndikats. Sein Name war Aliden Perenolde und er nannte sich selbst Lord dieses Landes. Er vertraute mir seine Pläne an, die Orcs, die sich gegen ihn gewandt hatten, zu Sklaven zu machen, genau wie es einst auch sein Vater und Mentor, der geächtete Blackmoore, geplant hatte.\n\nAber viel wichtiger war, dass er seine Geliebte mitbrachte, ein zartes Mädchen namens Elysa. Um ihren Hals trug sie den Anhänger, den der Kriegshäuptling als sein Eigen wünscht.\n\nGeht jetzt, ich gehe meine eigenen Wege, nachdem ich meine Geschäfte hier erledigt habe.", sourceObjective = "Bringt die von Gol'dir gesammelten Informationen zu Krusk in Tarrens Mühle.", completion = "Diese überheblichen Menschen haben vielleicht Nerven! Wir werden ihnen zeigen, dass die Orcs sich ihrem Willen niemals unterwerfen werden!\n\nDas wird nun unsere Mission, zusätzlich zur Bergung des Schmuckstücks, das der Kriegshäuptling zu haben wünscht. Es scheint, als würde das Erfüllen der einen Mission gleichzeitig die Erfüllung der anderen bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[507] = { id = 507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Aliden Perenolde", description = "Es ist unumstritten, dass Perenolde getötet werden und seine Verderbtheit ausgelöscht werden muss. Sein Herrenhaus liegt weit nördlich von hier, an den Ufern des Lordameresees. {name}, tut Eure Pflicht, holt danach den Anhänger, den der Kriegshäuptling zu haben wünscht, und kehrt dann hierher zurück.", sourceObjective = "Tötet Lord Aliden Perenolde und befragt seine Geliebte Elysa nach Tarethas Anhänger.", progress = "W-was wollt Ihr?", completion = "Nein, nein, bitte tut mir nichts! Ich wollte Eurem Volk niemals Schaden zufügen, er hat mich gegen meinen Willen genommen! Ich flehe Euch an... verschont mich!", sourceObjectiveStatus = "unverified-source-field" }
quests[508] = { id = 508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarethas Geschenk", description = "Den Anhänger? Aber natürlich könnt Ihr ihn haben... Nehmt ihn! Nichts soll mich an ihn erinnern... nur bitte geht, bitte geht in Frieden...", sourceObjective = "Bringt Tarethas Anhänger zu Krusk nach Tarrens Mühle.", progress = "Ihr seid zurückgekehrt, {name}. Habt Ihr einen Erfolg zu vermelden?", completion = "Es ist schon merkwürdig, dass der Kriegshäuptling so viel Aufwand um so ein kleines Ding macht. Ich behaupte nicht, dass ich ihn verstehe, aber ich folge ihm, egal wie seine Befehle lauten. Ihr habt gute Arbeit geleistet, {name}, der Kriegshäuptling wird über Euren Erfolg erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[509] = { id = 509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Ein neuer Tag, ein neues Elixier. Wenn ich was zu sagen hätte, würde ich diese lächerlichen Menschen und die Geißel die Sache einfach unter sich ausmachen lassen. Sie scheinen ohnehin absolut darauf versessen zu sein, sich gegenseitig umzubringen.\n\nAber leider hat es sich unsere dunkle Fürstin in den Kopf gesetzt, das Ganze ein wenig zu beschleunigen. Also warum diese düsteren Tage nicht dazu nutzen und hier ein wenig Tod und Krankheit verbreiten?\n\n{name}, das ist mein Plan: Ihr macht Euch auf den Weg zur Nethander-Siedlung. Das ist südlich von Tarrens Mühle und östlich des Flusses und Southshore. Sammelt in den Feldern dort 6 Morastschnauzenkappen für mein nächstes Elixier.", sourceObjective = "Bringt 6 Morastschnauzenkappen zu Apotheker Lydon in Tarrens Mühle.", progress = "Hattet Ihr Erfolg in der Nethander-Siedlung?", completion = "Ah, der fürchterliche Gestank von Morastschnauzenkappen. Wenigstens sind diese dreckigen Gnolls für etwas gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[510] = { id = 510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchteinflößende Pläne", description = "Unter diesen Dokumenten befindet sich eine Liste der benötigten Vorräte. Das sind unter anderem ganz banale Dinge (Nahrung, Waffen, Kleidung) wie auch etwas exotischere Ausrüstungsgegenstände (Masken, Öl, Gift).\n\nAber am auffälligsten ist die Dringlichkeit dieses Auftrags - diese Vorräte werden schnellstens benötigt, um eine Unternehmung zu starten, die in dem Dokument als 'wichtige Mission gegen Southshore' beschrieben wird.", sourceObjective = "Bringt die furchteinflößenden Pläne zu Magistrat Henry Maleb nach Southshore.", progress = "{name}, Ihr seht so besorgt aus. Möchtet Ihr mir etwas mitteilen?", completion = "<Maleb liest die Dokumente.>\n\nDas ist wirklich sehr beunruhigend, {name}. Aus den Informationen in diesen Dokumenten und aus früheren Aktionen des Syndikats geht hervor, dass diese Bande von Halsabschneidern Southshore den Krieg erklärt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[511] = { id = 511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselter Brief", description = "Einer der Briefe auf diesem Tisch ist verschlüsselt und nicht zu ergründen.", sourceObjective = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore.", progress = "Ja, werter Herr? Was gibt es denn?", completion = "Was ist dies? Wartet einen Moment... lasst es mich genauer betrachten.\n\n...\n\nHm, ich habe diese Form der Verschlüsselung niemals gesehen, aber ich muss zugeben, dass mein Wissen auf diesem Gebiet bei weitem nicht vollständig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[512] = { id = 512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Edlen", description = "Ich fürchte, die Führung, die hinter dem Syndikat steht, will Southshore unbedingt ruinieren. Wir müssen diese Anführer mit aller Kraft schlagen, bevor sie ihre Pläne in die Tat umsetzen können.\n\nGeht zu den Ruinen von Strahnbrad, im Alteracgebirge im Norden. Wir glauben, dass das Syndikat dieses Gebiet als Hauptquartier benutzt.\n\nWir wissen, dass diese Bande von Halsabschneidern von ehemaligen Adligen von Alterac angeführt wird. Sie mögen sich als normale Agenten des Syndikats verkleiden, aber wenn Ihr sie tötet, werdet Ihr einen Edlen an dem Siegelring erkennen, den er trägt.\n\nBringt mir diese Siegelringe.", sourceObjective = "Bringt 7 Alteracsiegelringe zu Magistrat Henry Maleb nach Southshore.", progress = "Habt Ihr das Syndikat gejagt? Habt Ihr die Ringe?", completion = "Wird das Syndikat seiner Adligen beraubt, geht auch seine Fähigkeit verloren, entschlossen zu handeln, und übrig bleibt nur eine Bande von Abschaum.\n\nIhr habt Eurer Allianz gut gedient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[513] = { id = 513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Gerade dachte ich noch, ein weiterer Tag ohne jegliches Amüsement, und da kommt Ihr und bringt diese wunderbaren Morastschnauzenkappen.\n\nZuerst werde ich sie zu einem feinen Gemisch zusammenrühren. Dann werden wir Meisterapotheker Faranell in Undercity benötigen, damit er seine Paste des Verfalls hinzufügt, und dann geht der Spaß erst richtig los!\n\nHier, {name}, nehmt dieses Morastschnauzengemisch und bringt es schnell zu Meister Faranell.", sourceObjective = "Bringt das Morastschnauzengemisch zu Meisterapotheker Faranell in Undercity.", progress = "Könnt Ihr nicht sehen, {class}, dass ich beschäftigt bin? Die dunkle Fürstin besteht auf einer neuen Pest, bevor die Vorhut der Geißel aus Northrend uns überwältigt. Und dann noch die menschliche Bedrohung aus dem Süden. Meine Zeit ist im Augenblick sehr wertvoll. Es ist hoffentlich von Bedeutung!", completion = "Apotheker Lydon hat Euch geschickt? Warum habt Ihr das nicht gleich gesagt!\n\nTrotz seiner etwas düsteren Einstellung ist Apotheker Lydon doch eines unserer hingebungsvollsten und geschicktesten Mitglieder.\n\nDer Gute schickt mir Morastschnauzengemisch! Nun weiß ich, was unser Freund in Hillsbrad vorhat. Und mir gefällt seine Denkweise. Die dunkle Fürstin wäre äußerst beeindruckt von dem Fortschritt, den er in Richtung neue Seuche macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[514] = { id = 514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief an Stormpike", description = "Ich habe einen Kollegen in Ironforge, der bei der Entschlüsselung dieses Briefes behilflich sein kann. Begebt Euch zur Bibliothek in der Halle der Forscher in Ironforge und sprecht mit Ausgrabungsleiter Stormpike. Richtet ihm aus, dass ich Euch geschickt habe, und zeigt ihm diesen Brief. Wenn es jemanden nördlich der Blackrockspitze gibt, der das hier lesen kann, dann ist er das.", sourceObjective = "Bringt den geschickt verschlüsselten Brief zu Ausgrabungsleiter Stormpike nach Ironforge.", progress = "Dibbs aus Southshore hat Euch also geschickt? Wie geht’s dem alten Bücherwurm?", completion = "Ah, eine Verschlüsselung! Eine meiner Spezialitäten. Lasst mich mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[515] = { id = 515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Ein Morastschnauzengemisch? Das ist wirklich brillant! Warum ist mir das nicht eingefallen?\n\nLasst mich meine Paste des Verfalls diesem Teufelsgebräu hinzufügen.\n\nDamit die verunreinigenden Agenzien in dieser Morastschnauzenmixtur aktiviert werden, benötigt Lydon starken Trollbluttrank, sowie einige Säbelflossenschuppen und Fetzenflossenaugen von der Südküste Hillsbrads. Er wird wissen, was zu tun ist, sobald Ihr alle Reagenzien zusammengetragen habt. Ich kann es kaum abwarten zu erfahren, wie sein Experiment ablaufen wird!", sourceObjective = "Bringt die Morastschnauzenmixtur, einen starken Trollbluttrank, 5 Säbelflossenschuppen und 5 Fetzenflossenaugen zu Apotheker Lydon nach Tarrens Mühle.", progress = "Ich bin ja so froh, dass Ihr wieder da seid, {name}. Ich habe mich hier entsetzlich gelangweilt. Hier gab es ja nichts Unterhaltsameres zu tun, als Umpi zu vergiften und krank zu machen und sie dann wiederzubeleben... und das immer und immer und immer wieder.\n\nWie war Eure Reise nach Undercity? Hattet Ihr ein bisschen Glück und konntet ein paar Menschen auf dem Weg dorthin umbringen?", completion = "Die Aufregung dieses Experiments macht mich ganz schwummerig! Ihr wart so eine große Hilfe, {name}. Zusammen werden wir Krankheit und Tod in diesem Land verbreiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[516] = { id = 516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beren's Peril", description = "Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.\n\nLeider sind meine Informationen gelinde gesagt unvollständig. Laut Bericht verstecken sie sich an einem Ort, der als Beren's Peril bekannt ist. Ihr genauer Standort ist unbekannt, aber es scheint eine Höhle in den Hügeln zu sein, nahe einem Nest der Hexer von Dalaran.\n\nIch vertraue auf Euren Einfallsreichtum. Findet sie und macht alles dem Erdboden gleich.", sourceObjective = "Findet zuerst Beren's Peril, tötet 6 Zwangsarbeiter von Rabenklaue sowie 6 Wächter von Rabenklaue und kehrt dann zu Schattenpriester Allister in das Grabmal zurück.", completion = "Wenn unsere Späher und Agenten weiterhin solch wertvolle Informationen beibringen, dauert es nicht mehr lange, bis wir die Geißel des Lichkönigs aus unserem Land vertrieben haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[517] = { id = 517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Das neue Elixier ist endlich bereit für einen Test. Aber warum solch eine vollkommene, höchst ansteckende Seuche an einen einfachen Frosch oder Hund verschwenden? Wir sollten uns in Lady Sylvanas Namen eine kleine Freude erlauben.\n\nGeht nach Dun Garok. Ihr kennt doch die Kasernen, in denen diese widerlichen kleinen Zwerge umhersausen. Ihr stehlt ein Fässchen Shindigger-Starkbier für mich. Sobald ich dieses Fässchen habe, können wir beide, Ihr und ich, eine kleine Party feiern, {name}.", sourceObjective = "Bringt ein Fässchen mit Shindigger-Starkbier zu Apotheker Lydon nach Tarrens Mühle.", progress = "Manchmal wird mir hier in Tarrens Mühle so elendiglich langweilig, dass ich am liebsten einen Krug Formaldehyd öffnen möchte und sein liebliches Aroma durch die Luft ziehen ließe. Umpi wird dann aber immer so nervös.\n\nKonntet Ihr ein Fässchen von den Zwergen besorgen? Wenn ich auch nur noch einen Tag länger dieses Elixier anstarren muss, ohne es benutzen zu können, dann schreie ich.", completion = "Endlich! Dann können wir ja anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[518] = { id = 518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Mug'Thol und seine Crushridge-Oger haben die Ruinen von Alterac überrannt. Ihm eine schwere Strafe zukommen zu lassen, ohne die Anzahl der Oger zu verringern, wird nicht einfach sein.\n\nWir machen sie erst weich und sehen dann weiter.\n\nVerstanden? Gut. Dann geht.", sourceObjective = "Tötet 14 Crushridge-Raufer für Melisara in Tarrens Mühle.", completion = "Der Schnee leuchtet rot von Ogerblut, aber wir dürfen unsere Bemühungen nicht einstellen, ehe nicht der Geist und die Zahl der Crushridge zermalmt und in den Dreck und Schnee getreten worden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[519] = { id = 519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Targ, Muckrake und Glommus sind Mug’Thols Offiziere. Sie sind ihm loyal ergeben, aber wer weiß schon, was einen Oger loyal sein lässt.\n\nBringt mir ihre Köpfe, {name}, und dann muss nur noch Mug'Thols Kopf, mitsamt Krone, rollen.", sourceObjective = "Tötet Targ, Muckrake und Glommus und bringt ihre Köpfe zu Melisara nach Tarrens Mühle.", progress = "Ich will ihre Köpfe, {name}, keine Entschuldigungen.", completion = "... und ich dachte Oger röchen so schon ekelhaft genug.\n\nWenn Ihr mir Mug'Thols Kopf bringt, werde ich alle vier auf Stangen oberhalb Alteracs aufstellen lassen. Ein passendes Denkmal für alle diejenigen, die sich den Wünschen der dunklen Fürstin entgegenstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[520] = { id = 520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Nun, da Mug'Thols Offiziere tot sind, muss nur noch Mug'Thol selbst getötet und die Krone des Willens wieder zurückgebracht werden. Ich bin mir ziemlich sicher, dass er sie nur äußerst unwillig wieder hergeben wird. Außerdem wird er Euch wahrscheinlich bereits erwarten, in Anbetracht des... Ablebens... seiner Kumpanen.\n\nFindet Mug'Thol und bringt mir seinen Kopf und die Krone. Der Crushridge-Widerstand wird damit beendet sein.", sourceObjective = "Tötet Mug'Thol und bringt seinen Kopf mit der Krone des Willens zu Melisara nach Tarrens Mühle.", progress = "Drei Köpfe habe ich, einen vierten brauch ich noch. Das wird Mug'Thols sein, oder es wird der Eure, {name}. Das ist ein Versprechen.", completion = "Ihr habt Eure Pflicht gut erledigt, {name}. Mug'Thols Kopf wird die höchste Spitze der Ruinen von Alterac verzieren und die Todeswache wird die Überbleibsel der Crushridge in den Boden stampfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[521] = { id = 521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Willens", description = "Es bleibt nur noch, die Krone des Willens zu Sharlindra nach Undercity zu bringen. Sie wird dafür sorgen, dass sie an Lady Sylvanas weitergeleitet wird. Ich warne Euch, auch nur daran zu denken, sie für Eure eigenen Zwecke zu verwenden, {name}, Mug'Thols Schicksal sollte Beispiel genug sein.", sourceObjective = "Bringt die Krone des Willens zu Sharlindra in Undercity.", progress = "Ja? Habt Ihr etwas zu berichten?", completion = "Das ist also das Relikt, das der Oger benutzte, um den Willen der dunklen Fürstin zu unterlaufen...\n\nSeltsam, dass etwas so Einfaches so eine große Macht ausüben kann. Und dazu noch in solch ungeschickte Hände fiel. Gut gemacht, {name}, ich werde die Krone Lady Sylvanas überbringen und dafür sorgen, dass sie von Eurem Verdienst hört.", sourceObjectiveStatus = "unverified-source-field" }
quests[522] = { id = 522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auftragsmördervertrag", description = "Dies ist ein Vertrag für die Ermordung des Magistrats Henry Maleb. Er wurde mit einem unverwechselbaren Siegelring in rotem Wachs gestempelt und versiegelt.", sourceObjective = "Bringt den Auftragsmörder-Vertrag zu Magistrat Maleb nach Southshore.", progress = "Ihr seid ja vollkommen außer Atem! Habt Ihr etwas zu berichten?", completion = "<Maleb inspiziert den Vertrag.>\n\nDas erklärt den letzten Angriff auf Southshore. Das Syndikat ist bestimmt auch hinter mir her, so wie hinter dem letzten Magistraten!", sourceObjectiveStatus = "unverified-source-field" }
quests[523] = { id = 523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ableben des Barons", description = "Der Vertrag, den Ihr gebracht habt, wurde von Baron Vardus unterschrieben, einem Edlen aus dem ehemaligen Königreich von Alterac, und jemand der bekannt ist für seine Kaltherzigkeit und brutale Vorgehensweisen. Es überrascht mich nicht, dass jemand wie der Baron dahinter steckt.\n\nFindet diesen Mann. Findet ihn und führt ihn seiner gerechten Strafe zu. Er befindet sich sicherlich irgendwo in den Schlupfwinkeln des Syndikats - vielleicht in den Ruinen von Strahnbrad oder irgendwo in dem Tal im Norden davon.", sourceObjective = "Bringt den Kopf von Baron Vardus zu Magistrat Maleb nach Southshore.", progress = "Baron Vardus kann doch nicht im Ernst glauben, dass er ungestraft seine Rohlinge gegen Southshore aussenden kann. Ich will seinen Kopf!", completion = "Ich danke Euch, {name}. Jetzt kann ich ein wenig ruhiger schlafen, da ich weiß, dass dieser Schurke auf ewig schlafen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[524] = { id = 524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Pein", description = "Nebenan halten die Todeswachen einige Bauern als Geiseln gefangen. Hochexekutorin Darthalia hatte vermutet, dass sich einer der Militärstrategen aus Stormwind unter ihnen versteckte. Anscheinend wurde dieser Militärstratege gestern Nacht tot in den Pestländern gefunden. Darthalia denkt ja immer so nett an mich und hat entschieden, dass die Gefangenen mir zu überlassen sind.\n\nIch denke, es ist höchste Zeit, dass wir für diese Bauern eine kleine Party schmeißen. Hört sich doch nach einer tollen Zeit an!\n\nStellt dieses besudelte Fässchen auf den Teppich in ihrem Zimmer. Seuchenbräu für alle!", sourceObjective = "Stellt das besudelte Fässchen auf den Teppich für die gefangenen Bauern.", progress = "Ein muffiger Geruch steigt von dem Teppich empor.", completion = "Ihr stellt das besudelte Fässchen auf dem verstaubten Teppich ab.", sourceObjectiveStatus = "unverified-source-field" }
